def _pi_score(d: dict) -> int:
    """Position Intelligence score — ports v1 piScore() exactly."""
    score = 50
    rsi = float(d.get("rsi") or 50)
    s50 = float(d.get("sma50_pct") or 0)
    s200 = float(d.get("sma200_pct") or 0)
    w52h = float(d.get("week52_high_pct") or 0)
    w52l = float(d.get("week52_low_pct") or 0)
    pos52 = 50
    if w52h != 0 or w52l != 0:
        rng = abs(w52h) + abs(w52l)
        pos52 = (abs(w52l) / rng * 100) if rng > 0 else 50
    short_flt = float(d.get("short_float_pct") or 0)
    eps_growth = float(d.get("eps_qoq") or d.get("eps_past_5y") or 0)
    # SMA alignment
    if s200 > 0 and s50 > 0: score += 12
    elif s200 > 0: score += 5
    elif s200 < -5: score -= 12
    # RSI zone
    if rsi > 70: score -= 8
    elif rsi > 55: score += 5
    elif rsi < 30: score -= 10
    elif rsi < 45: score -= 4
    # 52wk position
    if pos52 > 80: score += 8
    elif pos52 > 60: score += 3
    elif pos52 < 20: score -= 8
    # Short float
    if short_flt > 20: score -= 5
    # EPS growth
    if eps_growth > 15: score += 6
    elif eps_growth > 5: score += 3
    elif eps_growth < -10: score -= 5
    return max(0, min(100, score))


def _weighted_beta(positions):
    """Compute market-value-weighted beta from enrichment cache. Null-safe: a new/unpriced position
    (e.g. just-bought SPCX or a delisted CUSIP) may carry beta=None and/or market_value=None — default
    beta to 1.0 and treat missing market_value as 0 so one new holding can't crash the whole overview."""
    ec = _load_json(STATE_DIR / "ticker_enrichment_cache.json") or {}
    total_mv = sum((p.get("market_value") or 0) for p in positions)
    if total_mv <= 0:
        return 0
    beta_sum = 0.0
    for p in positions:
        sym = p.get("symbol", "")
        raw = (ec.get(sym) or {}).get("beta") if isinstance(ec.get(sym), dict) else None
        try:
            beta = float(raw) if raw is not None else 1.0
        except (TypeError, ValueError):
            beta = 1.0
        weight = (p.get("market_value") or 0) / total_mv
        beta_sum += beta * weight
    return round(beta_sum, 3)


def overview():
    h = _load_json(STATE_DIR / "holdings.json") or {}
    perf = _load_json(STATE_DIR / "performance_history.json") or {}
    fresh = _load_json(STATE_DIR / "_freshness.json") or {}
    news = _load_json(STATE_DIR / "portfolio_news.json") or {}

    holdings = h.get("holdings", [])
    totals = h.get("portfolio_totals", {})
    periods = perf.get("periods", {})
    active_positions = [p for p in holdings if not p.get("is_cash") and (p.get("market_value") or 0) > 100]

    # Sector allocation — prefer the pipeline's look-through breakdown (holdings.json resolved_sectors:
    # funds decomposed into underlying sectors). Holding ROWS carry no sector field, so the old per-row
    # sector_type aggregation collapsed everything into "Other". Fall back to it only if look-through is absent.
    resolved = h.get("resolved_sectors")
    if isinstance(resolved, list) and resolved:
        sector_list = [(r.get("sector") or "Other / Unclassified", r.get("value") or 0)
                       for r in resolved if (r.get("value") or 0) > 0][:13]
    else:
        sectors = {}
        for p in active_positions:
            s = p.get("sector_type") or "Other"
            sectors[s] = sectors.get(s, 0) + (p.get("market_value") or 0)
        sector_list = sorted(sectors.items(), key=lambda x: -x[1])[:10]

    # Top movers
    movers = sorted(active_positions, key=lambda p: abs(p.get("day_change") or 0), reverse=True)[:6]

    # Notifications count
    notif_rows = _db_query("SELECT count(*) AS cnt FROM notification_log", fetch="one")
    aq_cnt = (_db_query("SELECT count(*) AS cnt FROM action_queue WHERE status='pending'", fetch="one") or {}).get("cnt", 0)
    jdq_cnt = (_db_query("SELECT count(*) AS cnt FROM john_decision_queue WHERE status='pending_john'", fetch="one") or {}).get("cnt", 0)
    pending_rows = {"cnt": aq_cnt + jdq_cnt}

    # Today's change = sum of per-holding day_change (actual market-hours move)
    today_change = sum(p.get("day_change") or 0 for p in holdings)
    total_val = totals.get("total_value", 0)
    today_pct = (today_change / (total_val - today_change) * 100) if total_val > abs(today_change) else 0
    # per-account breakdown (operator 2026-06-12: "show what's moved today by account") + top movers
    today_by_account = {}
    for p in holdings:
        a = p.get("account") or "unknown"
        d = today_by_account.setdefault(a, {"change": 0.0, "value": 0.0})
        d["change"] += p.get("day_change") or 0
        d["value"] += p.get("market_value") or 0
    for a, d in today_by_account.items():
        base = d["value"] - d["change"]
        d["change"] = round(d["change"], 2)
        d["pct"] = round(d["change"] / base * 100, 2) if base > 0 else None
        d["value"] = round(d["value"], 2)
        movers_a = sorted([p for p in holdings if (p.get("account") or "unknown") == a],
                          key=lambda p: abs(p.get("day_change") or 0), reverse=True)[:2]
        d["top_movers"] = "; ".join(f"{m.get('symbol')} {('+' if (m.get('day_change') or 0) >= 0 else '')}"
                                    f"{round(m.get('day_change') or 0)}" for m in movers_a if m.get("day_change"))

    # Trade AI run data
    import glob
    _runs = sorted(glob.glob(str(PROJECT_ROOT / "reports" / "2026-*" / "*" / "run_summary.json")))
    tai = {}
    if _runs:
        tai = _load_json(Path(_runs[-1])) or {}

    # Journal stats (exclude flat/zero-pnl trades from win rate, matching v1)
    journal = _load_json(STATE_DIR / "trade_journal.json") or {}
    j_all = journal.get("closed_trades") or journal.get("trades") or []
    j_total_pnl = sum(t.get("pnl") or t.get("realized_pnl") or 0 for t in j_all)
    j_real = [t for t in j_all if (t.get("pnl") or t.get("realized_pnl") or 0) != 0]
    j_wins = sum(1 for t in j_real if (t.get("pnl") or t.get("realized_pnl") or 0) > 0)
    j_win_rate = (j_wins / len(j_real) * 100) if j_real else 0
    # Use pre-computed stats if available
    j_stats = journal.get("stats", {})
    if j_stats.get("win_rate"):
        j_win_rate = j_stats["win_rate"]
    if j_stats.get("total_pnl") is not None:
        j_total_pnl = j_stats["total_pnl"]

    _derived_total = round(sum(p.get("market_value") or 0 for p in holdings), 2)
    if _derived_total > 0 and (not total_val or abs(_derived_total - total_val) > 500):
        total_val = _derived_total
        today_change = round(sum(p.get("day_change") or 0 for p in holdings), 2)
        today_pct = (today_change / (total_val - today_change) * 100) if total_val > abs(today_change) else 0
    _fv_meta = (_load_json(STATE_DIR / "finviz_quote_cache.json") or {}).get("_meta") or {}
    return {
        "portfolio_value": total_val,
        "derived_total_value": _derived_total,
        "total_cash": totals.get("total_cash", 0),
        "today_change": round(today_change, 2),
        "today_pct": round(today_pct, 2),
        "reprice_source": h.get("reprice_source", ""),
        "pricing": {
            "last_repriced": h.get("last_repriced", ""),
            "reprice_source": h.get("reprice_source", ""),
            "finviz_cache_updated": _fv_meta.get("last_updated", ""),
            "holdings_as_of": h.get("as_of", ""),
            "derived_total_value": _derived_total,
            "canonical_total_value": totals.get("total_value", 0),
        },
        "today_by_account": today_by_account,
        "position_count": len(active_positions),
        "account_count": len(h.get("account_summaries", {})),
        "as_of": h.get("as_of", ""),
        "last_repriced": h.get("last_repriced", ""),
        "periods": {k: {"change_pct": v.get("change_pct"), "change": v.get("change"),
                        "estimated": v.get("source") == "repriced"}
                    for k, v in periods.items() if isinstance(v, dict)},
        "sectors": [{"name": n, "value": v} for n, v in sector_list],
        "sectors_by_account": {acct: [{"name": r.get("sector"), "value": r.get("value")} for r in (rows or [])]
                               for acct, rows in (h.get("resolved_sectors_by_account") or {}).items()},
        "top_movers": [{"symbol": m.get("symbol"), "name": (m.get("name") or "")[:30],
                        "day_change": m.get("day_change", 0), "day_change_pct": m.get("day_change_pct", 0)}
                       for m in movers],
        "trade_ai": {
            "vix": tai.get("vix"),
            "breadth": tai.get("breadth"),
            "go_count": tai.get("goCount", tai.get("go_count", 0)),
            "wait_count": tai.get("waitCount", tai.get("wait_count", 0)),
            "no_go_count": tai.get("noGoCount", tai.get("no_go_count", 0)),
            "run_date": tai.get("runDate", tai.get("date", "")),
            "run_label": tai.get("runLabel", tai.get("run_label", "")),
        },
        "journal": {
            "trade_count": len(j_all),
            "total_pnl": round(j_total_pnl, 2),
            "win_rate": round(j_win_rate, 1),
            "source": "journal",
        },
        "news_count": len(news.get("catalysts", [])),
        "notification_count": (notif_rows or {}).get("cnt", 0),
        "pending_approvals": (pending_rows or {}).get("cnt", 0),
        "pipeline_status": fresh.get("status", "unknown"),
        "pipeline_completed": fresh.get("completed_at", ""),
        # Sprint 4A additions
        "total_cash": totals.get("total_cash", 0),
        "weighted_beta": _weighted_beta(active_positions),
        "concentration_alerts": [{"symbol": p.get("symbol"), "pct": p.get("portfolio_pct", 0)}
                                  for p in active_positions if (p.get("portfolio_pct") or 0) > 20],
        "pending_pipeline": h.get("pending_pipeline_run", False),
        "last_repriced": h.get("last_repriced", ""),
        "index_tape": {
            "spy": tai.get("spy"), "qqq": tai.get("qqq"), "iwm": tai.get("iwm"),
        },
        "delta_events": tai.get("delta_events", 0),
    }


def _fib_analysis(price, high_pct, low_pct):
    """52-week fib retracement from %-from-high / %-above-low. The retracement position
    and nearest level are computable from the percentages alone (price cancels out);
    absolute dollar levels are added only when a real `price` is supplied (proxies omit
    them since the proxy's price scale differs from the fund NAV). Returns None if not
    computable (e.g. NAV-priced funds with no technical data)."""
    try:
        high_pct = float(high_pct); low_pct = float(low_pct)
    except (TypeError, ValueError):
        return None
    # Work in a price-independent frame (P=100) to get the retracement position.
    try:
        rel_high = 100.0 / (1 + high_pct / 100.0)   # high_pct = (price-high)/high*100
        rel_low = 100.0 / (1 + low_pct / 100.0)      # low_pct  = (price-low)/low*100
    except ZeroDivisionError:
        return None
    rel_rng = rel_high - rel_low
    if rel_rng <= 0 or rel_high <= 0:
        return None
    ratios = [("0% (52w high)", 0.0), ("23.6%", 0.236), ("38.2%", 0.382),
              ("50%", 0.5), ("61.8%", 0.618), ("78.6%", 0.786), ("100% (52w low)", 1.0)]
    retr = (rel_high - 100.0) / rel_rng * 100.0   # 0 at high, 100 at low
    nearest = min(ratios, key=lambda lr: abs(lr[1] * 100 - retr))
    out = {"retracement_from_high_pct": round(retr, 1), "nearest_level": nearest[0]}
    # Absolute dollar levels only when a real price is provided.
    try:
        p = float(price)
        if p > 0:
            high = p / (1 + high_pct / 100.0); low = p / (1 + low_pct / 100.0); rng = high - low
            if rng > 0:
                out["week52_high"] = round(high, 2)
                out["week52_low"] = round(low, 2)
                out["levels"] = {label: round(high - rng * r, 2) for label, r in ratios}
    except (TypeError, ValueError):
        pass
    return out


