def _system_applications():
    """GET /api/v2/system/applications — read-only installed software inventory."""
    import subprocess as _sp, shutil

    def _run(cmd, timeout=5):
        try:
            r = _sp.run(cmd, capture_output=True, text=True, timeout=timeout)
            return r.stdout.strip() if r.returncode == 0 else r.stderr.strip()[:200]
        except FileNotFoundError:
            return None
        except _sp.TimeoutExpired:
            return "timeout"
        except Exception as e:
            return f"error: {str(e)[:100]}"

    def _ver(raw):
        """Extract version string from command output."""
        if not raw:
            return None
        import re
        m = re.search(r'(\d+\.\d+[\.\d]*)', raw)
        return m.group(1) if m else raw[:60]

    def _drift(installed, latest):
        if not installed or not latest or installed == latest:
            return {"status": "current" if installed and latest and installed == latest else "unknown", "detail": ""}
        import re
        iv = re.findall(r'\d+', installed)
        lv = re.findall(r'\d+', latest)
        if len(iv) >= 3 and len(lv) >= 3:
            if iv[0] != lv[0]:
                return {"status": "major_behind", "detail": f"{installed} → {latest}"}
            if iv[1] != lv[1]:
                return {"status": "minor_behind", "detail": f"{installed} → {latest}"}
            try:
                d = int(lv[2]) - int(iv[2])
                if d > 0:
                    return {"status": "patch_behind", "detail": f"{d} patch versions behind"}
            except ValueError:
                pass
        return {"status": "unknown", "detail": f"{installed} vs {latest}"}

    pr = str(PROJECT_ROOT)
    apps = []

    # ── Load weekly version cache (fast) ──
    _vcache = {}
    _vcache_ts = None
    try:
        import json as _jvc
        _vcf = Path(pr) / "data" / "state" / "system_versions_latest.json"
        if _vcf.exists():
            _vcd = _jvc.loads(_vcf.read_text())
            _vcache = {k: v.get("latest") for k, v in _vcd.get("packages", {}).items()}
            _vcache_ts = _vcd.get("checked_at", "")
    except Exception:
        pass

    def _latest(key):
        return _vcache.get(key)

    # ── Core ──
    py_ver = _ver(_run(["python3", "--version"]))
    apps.append({"name": "Python", "category": "core",
        "installed": py_ver, "latest": _latest("python3"), "path": shutil.which("python3"),
        "version_cmd": "python3 --version",
        "update_cmd": "Manual OS package review required"})

    apps.append({"name": "Python (venv)", "category": "core",
        "installed": _ver(_run([f"{pr}/.venv/bin/python", "--version"])),
        "latest": py_ver, "path": f"{pr}/.venv/bin/python",
        "version_cmd": ".venv/bin/python --version",
        "update_cmd": "Manual review required"})

    apps.append({"name": "Node.js", "category": "core",
        "installed": _ver(_run(["node", "--version"])),
        "latest": _latest("nodejs"), "path": shutil.which("node"),
        "version_cmd": "node --version",
        "update_cmd": "Manual OS package review required"})

    apps.append({"name": "npm", "category": "core",
        "installed": _ver(_run(["npm", "--version"])),
        "latest": _latest("npm"), "path": shutil.which("npm"),
        "version_cmd": "npm --version",
        "update_cmd": "Manual review required"})

    pg_ver = _ver(_run(["psql", "--version"]))
    apps.append({"name": "PostgreSQL", "category": "core",
        "installed": pg_ver, "latest": _latest("postgresql"),
        "path": shutil.which("psql"),
        "version_cmd": "psql --version",
        "update_cmd": "Manual OS package review required"})

    apps.append({"name": "Git", "category": "core",
        "installed": _ver(_run(["git", "--version"])),
        "latest": _latest("git"), "path": shutil.which("git"),
        "version_cmd": "git --version",
        "update_cmd": "Manual OS package review required"})

    ollama_ver = _ver(_run(["ollama", "--version"]))
    apps.append({"name": "Ollama", "category": "core",
        "installed": ollama_ver, "latest": _latest("ollama"),
        "path": shutil.which("ollama"),
        "version_cmd": "ollama --version",
        "update_cmd": "Manual review required"})

    # Ollama models
    try:
        import urllib.request, json as _j
        resp = urllib.request.urlopen("http://localhost:11434/api/tags", timeout=3)
        models = _j.loads(resp.read()).get("models", [])
        for m in models:
            size_gb = m.get("size", 0) / 1024 / 1024 / 1024
            apps.append({"name": f"Ollama: {m['name']}", "category": "model",
                "installed": f"{size_gb:.1f}GB",
                "latest": None, "path": None,
                "version_cmd": "ollama list",
                "update_cmd": f"ollama pull {m['name']}"})
    except Exception:
        pass

    # llama.cpp
    llamacpp_ver = _ver(_run(["llama-cli", "--version"])) or _ver(_run(["llama-server", "--version"]))
    llamacpp_path = shutil.which("llama-cli") or shutil.which("llama-server")
    apps.append({"name": "llama.cpp", "category": "core",
        "installed": llamacpp_ver or ("installed" if llamacpp_path else None),
        "latest": None, "path": llamacpp_path,
        "version_cmd": "llama-cli --version",
        "update_cmd": "Manual review required"})

    # Gemma4 31B (llama.cpp, not Ollama)
    gemma4_path = None
    for p in ["/usr/share/ollama/.ollama/models", str(Path.home() / ".ollama/models"),
              str(PROJECT_ROOT / "models")]:
        if Path(p).exists():
            gemma4_files = list(Path(p).rglob("*gemma*4*")) if Path(p).exists() else []
            if gemma4_files:
                gemma4_path = str(gemma4_files[0].parent)
                break
    apps.append({"name": "Gemma4 31B (llama.cpp)", "category": "model",
        "installed": "31B Q4" if gemma4_path else "available via llama.cpp",
        "latest": None, "path": gemma4_path or "llama.cpp offline runner",
        "version_cmd": "llama-cli --version",
        "update_cmd": "Manual review required",
        "note": "Tier 3a deep analysis, off-hours only, ~8min per job"})

    # ── AI / Agent ──
    hermes_ver = None
    # Global Hermes install (sidecar retired 2026-06-06). Status read from the global venv.
    _hpip = _run([os.path.expanduser("~/.local/share/hermes-agent-venv/bin/pip"), "show", "hermes-agent"], timeout=10)
    if _hpip:
        import re as _re2
        _hm = _re2.search(r'Version:\s*(\S+)', _hpip)
        hermes_ver = _hm.group(1) if _hm else _ver(_hpip)
    hermes_latest = _latest("hermes-agent")
    apps.append({"name": "Hermes Agent", "category": "agent",
        "installed": hermes_ver, "latest": hermes_latest,
        "path": "~/.local/share/hermes-agent-venv/",
        "version_cmd": "hermes --version",
        "update_cmd": "~/.local/share/hermes-agent-venv/bin/pip install --upgrade hermes-agent (requires backup + approval)"})

    claude_ver = _ver(_run([str(Path.home() / ".local/bin/claude"), "--version"]))
    claude_latest = _latest("claude-code")
    apps.append({"name": "Claude Code CLI", "category": "agent",
        "installed": claude_ver, "latest": claude_latest,
        "path": str(Path.home() / ".local/bin/claude"),
        "version_cmd": "claude --version",
        "update_cmd": "claude install",
        "note": "Auto-update may lack permission. Handle as separate operator maintenance."})

    # OpenClaw
    oc_ver = _ver(_run(["openclaw", "--version"]))
    apps.append({"name": "OpenClaw Gateway", "category": "agent",
        "installed": oc_ver or "running (version unknown)",
        "latest": None, "path": shutil.which("openclaw"),
        "version_cmd": "openclaw --version",
        "update_cmd": "Manual review required"})

    # ── Data / Integrations ──
    ts_ver = _ver(_run(["tailscale", "version"]))
    ts_latest = _latest("tailscale")
    apps.append({"name": "Tailscale", "category": "integration",
        "installed": ts_ver, "latest": ts_latest,
        "path": shutil.which("tailscale"),
        "version_cmd": "tailscale version",
        "update_cmd": "Manual review required"})

    gog_ver = _ver(_run(["gog", "--version"]))
    apps.append({"name": "GOG (Google CLI)", "category": "integration",
        "installed": gog_ver or ("installed" if shutil.which("gog") else None),
        "latest": None, "path": shutil.which("gog"),
        "version_cmd": "gog --version",
        "update_cmd": "Manual review required"})

    # ── Infrastructure (Docker containers) ──
    docker_ver = _ver(_run(["docker", "version", "--format", "{{.Server.Version}}"]))
    apps.append({"name": "Docker Engine", "category": "infrastructure",
        "installed": docker_ver, "latest": None,
        "path": shutil.which("docker"),
        "version_cmd": "docker version --format '{{.Server.Version}}'",
        "update_cmd": "Manual review required"})

    # SearXNG (internal-only search layer)
    searxng_status = None
    searxng_ver = None
    try:
        import urllib.request as _ur
        _sr = _ur.urlopen("http://127.0.0.1:18888/", timeout=3)
        searxng_status = "running"
        searxng_ver = "internal"
    except Exception:
        searxng_status = "stopped"
    apps.append({"name": "SearXNG", "category": "infrastructure",
        "installed": searxng_ver or searxng_status,
        "latest": None,
        "path": "infra/searxng/docker-compose.yml",
        "version_cmd": "curl -s http://127.0.0.1:18888/",
        "update_cmd": "sg docker -c 'docker compose -f infra/searxng/docker-compose.yml pull && docker compose -f infra/searxng/docker-compose.yml up -d'",
        "note": "Internal-only shared search layer. 127.0.0.1:18888. Not integrated with Hermes or production."})

    # ── Frontend ──
    try:
        import json as _j
        pkg = _j.loads((Path(pr) / "apps/command-center-v2/package.json").read_text())
        deps = pkg.get("dependencies", {})
        dev = pkg.get("devDependencies", {})
        _npm_pkgs = {"React": "react", "React Router": "react-router-dom",
                     "Vite": "vite", "TypeScript": "typescript", "Chart.js": "chart.js"}
        for display, npm_name in _npm_pkgs.items():
            ver = deps.get(npm_name) or dev.get(npm_name)
            if ver:
                lat = _latest(npm_name)
                apps.append({"name": display, "category": "frontend",
                    "installed": ver.lstrip("^~"), "latest": lat,
                    "path": "apps/command-center-v2/package.json",
                    "version_cmd": f"npm view {npm_name} version",
                    "update_cmd": "npm outdated (requires separate approval)"})
    except Exception:
        pass

    # Compute drift for all
    for app in apps:
        d = _drift(app.get("installed"), app.get("latest"))
        app["drift"] = d

    summary = {
        "total": len(apps),
        "current": sum(1 for a in apps if a["drift"]["status"] == "current"),
        "behind": sum(1 for a in apps if "behind" in a["drift"]["status"]),
        "unknown": sum(1 for a in apps if a["drift"]["status"] == "unknown"),
        "not_installed": sum(1 for a in apps if not a.get("installed")),
    }

    return {"ok": True, "applications": apps, "summary": summary, "versions_checked_at": _vcache_ts}


def _hermes_infra():
    """GET /api/v2/hermes/infra — service health (SearXNG/Docker, gateway, Ollama, Postgres),
    web-source provenance (domains), and the research funnel (staged→promoted→embedded)."""
    import urllib.request as _u
    from urllib.parse import urlparse as _up

    def _ping(url, timeout=3):
        try:
            with _u.urlopen(url, timeout=timeout) as r:
                return 200 <= r.status < 500
        except Exception:
            return False

    services = []
    # HTTP health is the source of truth (proves reachability). Slightly longer timeout to avoid false
    # DOWN under transient load; any 200-499 response from SearXNG counts as up.
    sx_up = _ping(os.environ.get("SEARXNG_URL", "http://127.0.0.1:18888/").split("/search")[0] or "http://127.0.0.1:18888/", timeout=6)
    sourced = _db_query("SELECT COUNT(*) c FROM hermes_research_intelligence WHERE source_urls_json IS NOT NULL AND source_urls_json::text NOT IN ('null','[]','{}')", fetch="one") or {}
    services.append({"name": "SearXNG", "kind": "docker", "status": "up" if sx_up else "down", "detail": "127.0.0.1:18888 (searxng/searxng)", "sourced_rows": _json_clean(sourced.get("c", 0))})
    # Ollama + loaded models
    ol_up = _ping("http://127.0.0.1:11434/api/tags")
    models = ""
    try:
        with _u.urlopen("http://127.0.0.1:11434/api/ps", timeout=3) as r:
            import json as _j
            models = ", ".join(m.get("name", "") for m in _j.loads(r.read()).get("models", []))
    except Exception:
        pass
    services.append({"name": "Ollama (LLM)", "kind": "service", "status": "up" if ol_up else "down", "detail": models or "no models loaded"})
    # Hermes gateway (global ~/.hermes pid file). Sidecar gateway retired/disabled 2026-06-06; gateway is
    # not run in the global profile model (chat-only), so this is normally "down" by design.
    gw = "down"
    try:
        pidf = Path.home() / ".hermes" / "gateway.pid"
        if pidf.exists():
            raw = pidf.read_text().strip()
            import json as _j
            pid = int(_j.loads(raw).get("pid")) if raw.startswith("{") else int(raw)
            os.kill(pid, 0); gw = "up"
    except Exception:
        gw = "down"
    services.append({"name": "Hermes Gateway", "kind": "process", "status": gw, "detail": "global Hermes; sidecar gateway retired/disabled (profiles are chat-only)"})
    services.append({"name": "Postgres", "kind": "db", "status": "up", "detail": "trade_ai"})  # this query proves it

    # Web-source domains (provenance) — parse source_urls_json
    domains = {}
    rows = _db_query("SELECT source_urls_json FROM hermes_research_intelligence WHERE source_urls_json IS NOT NULL AND source_urls_json::text NOT IN ('null','[]','{}') LIMIT 500") or []
    for r in rows:
        try:
            urls = r["source_urls_json"]
            if isinstance(urls, str):
                import json as _j; urls = _j.loads(urls)
            if isinstance(urls, dict):
                urls = list(urls.values())
            for u in (urls or []):
                if isinstance(u, str) and u.startswith("http"):
                    d = _up(u).netloc.replace("www.", "")
                    if d:
                        domains[d] = domains.get(d, 0) + 1
        except Exception:
            continue
    top_domains = sorted(domains.items(), key=lambda x: -x[1])[:15]

    # Research funnel (provenance flow counts)
    f = _db_query("SELECT COUNT(*) FILTER (WHERE status='staged') staged, COUNT(*) FILTER (WHERE status='promoted') promoted, COUNT(*) total FROM hermes_research_intelligence", fetch="one") or {}
    emb = _db_query("SELECT COUNT(*) c FROM hermes_embedding_queue WHERE embedding_status='completed'", fetch="one") or {}
    return {
        "services": services,
        "source_domains": [{"domain": d, "n": n} for d, n in top_domains],
        "funnel": {"staged": _json_clean(f.get("staged", 0)), "promoted": _json_clean(f.get("promoted", 0)),
                   "embedded": _json_clean(emb.get("c", 0)), "total": _json_clean(f.get("total", 0))},
    }


def _hermes_sources():
    """GET /api/v2/hermes/sources — registry split: connectors / news maturity / web yield + vetting queue."""
    try:
        import hermes_source_registry as hsr
        rows = _db_query("SELECT source_type, source_name, source_url, credibility_score, specialty, active, notes "
                         "FROM research_sources ORDER BY active DESC, source_type, credibility_score DESC") or []
        out = []
        for r in rows:
            sp = r.get("specialty")
            out.append({"type": r["source_type"], "name": r["source_name"], "url": r.get("source_url"),
                        "credibility": _json_clean(r.get("credibility_score")), "active": r.get("active"),
                        "specialty": (sp[0] if isinstance(sp, list) and sp else sp), "notes": r.get("notes")})
        enriched = hsr.enrich_source_rows(out)
        active = sum(1 for x in out if x["active"])
        return {
            "sources": out,
            "active": active,
            "total": len(out),
            **enriched,
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _hermes_source_policy(query: dict | None):
    """GET /api/v2/hermes/sources/policy?source= — runtime ingest/promotion policy for one source."""
    try:
        import hermes_source_policy as hsp
        src = str((query or {}).get("source") or "").strip()
        if not src:
            return {"ok": False, "error": "source query param required"}
        pol = hsp.resolve(src, force_refresh=True)
        return {"ok": True, "policy": pol.as_dict()}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _hermes_source_approve(body: dict):
    """POST /api/v2/hermes/sources/approve — operator activates a news maturity source."""
    try:
        import sys
        sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import hermes_source_registry as hsr
        from db_adapter import _get_conn, USE_DB
        if not USE_DB:
            return {"ok": False, "error": "database unavailable"}
        b = body or {}
        name = str(b.get("source_name") or b.get("source") or "").strip()
        if not name:
            return {"ok": False, "error": "source_name required"}
        conn = _get_conn()
        cur = conn.cursor()
        try:
            result = hsr.approve_news_source(cur, name, operator=str(b.get("operator") or "operator"))
            if result.get("ok"):
                conn.commit()
            else:
                conn.rollback()
            return result
        finally:
            cur.close()
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _hermes_provenance():
    """GET /api/v2/hermes/provenance — per-research-item provenance for the node-graph lane:
    SearXNG → source domain → research item → (promoted) → RAG/embedded."""
    from urllib.parse import urlparse as _up
    import json as _j
    try:
        rows = _db_query("""
            SELECT r.id, COALESCE(NULLIF(r.symbol,''), LEFT(r.topic, 26)) AS label, r.status, r.research_type,
                   r.source_urls_json, r.hermes_agent_name,
                   EXISTS(SELECT 1 FROM hermes_embedding_queue q
                          WHERE q.source_research_id = r.id AND q.embedding_status='completed') AS embedded
            FROM hermes_research_intelligence r
            ORDER BY r.created_at DESC LIMIT 36""") or []
        items = []
        for r in rows:
            dom = None
            try:
                urls = r["source_urls_json"]
                if isinstance(urls, str):
                    urls = _j.loads(urls)
                if isinstance(urls, dict):
                    urls = list(urls.values())
                for u in (urls or []):
                    if isinstance(u, str) and u.startswith("http"):
                        dom = _up(u).netloc.replace("www.", ""); break
            except Exception:
                pass
            items.append({"id": r["id"], "label": r["label"] or f"#{r['id']}", "status": r["status"],
                          "type": r["research_type"], "agent": r["hermes_agent_name"],
                          "domain": dom, "embedded": bool(r["embedded"])})
        return {"items": items}
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _hermes_agent_footprint():
    """GET /api/v2/hermes/agent-footprint — VALIDATED per-agent execution footprint.
    Separates approval-state (governance) from actual runtime rows so the workflow graph
    shows whether jobs are really flowing, not just the design-doc label."""
    try:
        by_agent = _db_query(
            "SELECT hermes_agent_name AS agent, COUNT(*) AS rows, MAX(created_at)::date AS last_active "
            "FROM hermes_research_intelligence WHERE hermes_agent_name IS NOT NULL "
            "GROUP BY 1 ORDER BY 2 DESC") or []
        # active job classifications (research_type breakdown) per agent — "what they're working on"
        types = _db_query(
            "SELECT hermes_agent_name AS agent, research_type AS klass, COUNT(*) AS n "
            "FROM hermes_research_intelligence WHERE hermes_agent_name IS NOT NULL AND research_type IS NOT NULL "
            "GROUP BY 1,2 ORDER BY 1, 3 DESC") or []
        cls_by_agent = {}
        for t in types:
            cls_by_agent.setdefault(t["agent"], []).append({"type": t["klass"], "n": _json_clean(t["n"])})
        for a in by_agent:
            a["classifications"] = cls_by_agent.get(a["agent"], [])
        eq = _db_query("SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE embedding_status='completed') AS completed, "
                       "MAX(created_at)::date AS last_active FROM hermes_embedding_queue", fetch="one") or {}
        pa = _db_query("SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE dry_run) AS dry_run, "
                       "COUNT(*) FILTER (WHERE approved_by IS NOT NULL) AS approved, MAX(promoted_at)::date AS last_active "
                       "FROM hermes_promotion_audit", fetch="one") or {}
        me = _db_query("SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE metadata_json->>'test' = 'true') AS smoke_tests, "
                       "MAX(created_at)::date AS last_active FROM hermes_memory_events", fetch="one") or {}
        return {
            "by_agent": [{k: _json_clean(v) for k, v in r.items()} for r in by_agent],
            "embedding_queue": {k: _json_clean(v) for k, v in eq.items()},
            "promotion_audit": {k: _json_clean(v) for k, v in pa.items()},
            "memory_events": {k: _json_clean(v) for k, v in me.items()},
            "note": "Execution footprint is independent of approval. Rows present ≠ governance-approved; many are autonomous-loop / dry-run / smoke-test writes.",
        }
    except Exception as e:
        return {"ok": False, "error": str(e)}


def _hermes_agent_runstate():
    """GET /api/v2/hermes/agent-runstate — LIVE run-state per Hermes fleet agent, computed from real
    evidence (coordinator heartbeat + each agent's last actual output) so the UI can't show a dormant
    agent as 'operational'. Read-only."""
    import os as _os
    import time as _time
    ROOT = str(PROJECT_ROOT)
    # agent_id -> ('file', relpath) | ('table', table, where, tscol)
    EVIDENCE = {
        "coordinator":      ("file", "logs/hermes_coordinator.log"),
        "research_curator": ("file", "data/runtime/research_critique_latest.json"),
        "source_discovery": ("table", "hermes_research_intelligence",
                             "hermes_agent_name ILIKE '%source%' OR research_type='source_discovery'", "created_at"),
        "librarian":        ("table", "hermes_research_intelligence", "hermes_agent_name ILIKE '%librarian%'", "created_at"),
        "embedding":        ("table", "hermes_embedding_queue", "1=1", "created_at"),
        "promotion":        ("table", "hermes_promotion_audit", "1=1", "promoted_at"),
        "backlog":          ("table", "hermes_research_intelligence",
                             "research_type IN ('research_backlog','backlog_resolution')", "created_at"),
        "autonomous":       ("table", "hermes_research_intelligence", "hermes_agent_name ILIKE '%autonomous%'", "created_at"),
    }

    def _age_hours(ev):
        try:
            if ev[0] == "file":
                p = _os.path.join(ROOT, ev[1])
                if not _os.path.exists(p):
                    return None
                return (_time.time() - _os.path.getmtime(p)) / 3600.0
            _, tbl, where, tscol = ev
            r = _db_query(f"SELECT EXTRACT(EPOCH FROM (NOW()-max({tscol})))/3600 AS h FROM {tbl} WHERE {where}", fetch="one")
            return float(r["h"]) if r and r.get("h") is not None else None
        except Exception:
            return None

    # coordinator heartbeat is the fleet signal
    coord_age = _age_hours(EVIDENCE["coordinator"])
    fleet_down = coord_age is None or coord_age > 2.0  # coordinator runs */15; >2h = not ticking

    def _state(agent_id, age):
        if agent_id != "coordinator" and fleet_down:
            return "fleet_down"
        if age is None:
            return "dormant"
        if age < 6:
            return "live"
        if age < 48:
            return "idle"
        return "dormant"

    out = []
    for aid, ev in EVIDENCE.items():
        age = coord_age if aid == "coordinator" else _age_hours(ev)
        out.append({
            "id": aid,
            "live_state": _state(aid, age),
            "age_hours": round(age, 2) if age is not None else None,
            "last_active_h": round(age, 1) if age is not None else None,
            "evidence": ev[1] if ev[0] == "file" else f"{ev[1]}",
        })
    return {
        "coordinator_heartbeat_h": round(coord_age, 2) if coord_age is not None else None,
        "fleet_live": not fleet_down,
        "agents": out,
        "note": "live_state computed from real evidence (coordinator log mtime + each agent's last output); "
                "overrides the static UI labels. live=<6h · idle=<48h · dormant=stale/never · fleet_down=coordinator not ticking.",
    }


def _hermes_research_backlog():
    """GET /api/v2/hermes/research-backlog — read-only research backlog items."""
    rows = _db_query("""
        SELECT id, symbol, topic, LEFT(summary, 400) AS summary, confidence_score,
               status, evidence_json, source_urls_json, created_at
        FROM hermes_research_intelligence
        WHERE research_type = 'research_backlog'
        ORDER BY created_at DESC
    """) or []
    items = []
    for r in rows:
        ej = r.get("evidence_json") or []
        if isinstance(ej, str):
            import json as _jrb
            try:
                ej = _jrb.loads(ej)
            except Exception:
                ej = []
        meta = ej[0] if ej else {}
        items.append({
            "id": r["id"],
            "symbol": r.get("symbol"),
            "topic": r.get("topic", ""),
            "summary": r.get("summary", ""),
            "confidence_score": r.get("confidence_score"),
            "status": r.get("status"),
            "priority": meta.get("priority", "unknown"),
            "owner_agent": meta.get("owner_agent", "unknown"),
            "backlog_type": meta.get("backlog_type", "unknown"),
            "created_at": _json_clean(r.get("created_at")),
        })
    return {
        "ok": True,
        "items": items,
        "total": len(items),
        "advisory_notice": "Research Backlog — Advisory Only — Not Execution — No Autonomous Research",
    }


def _hermes_sl_drilldown():
    """GET /api/v2/hermes/self-learning/drilldown — filtered item list with workflow context."""
    qs = _current_query or {}
    status_f = qs.get("status")
    rtype_f = qs.get("type")
    category_f = qs.get("category")
    agent_f = qs.get("agent")
    symbol_f = qs.get("symbol")
    section_f = qs.get("section")  # legacy compat

    # Map section param to type for backwards compat
    if section_f and not rtype_f:
        rtype_f = section_f

    where = ["1=1"]
    params = []
    if status_f:
        where.append("r.status=%s"); params.append(status_f)
    if rtype_f:
        where.append("r.research_type=%s"); params.append(rtype_f)
    if agent_f:
        where.append("r.hermes_agent_name=%s"); params.append(agent_f)
    if symbol_f:
        where.append("r.symbol=%s"); params.append(symbol_f)

    rows = _db_query(f"""
        SELECT r.id, r.symbol, r.research_type, r.hermes_agent_name, r.confidence_score,
               r.status, LEFT(r.topic,200) as topic, LEFT(r.summary,300) as summary,
               r.source_urls_json::text, r.created_at, r.updated_at,
               CASE WHEN ce.id IS NOT NULL THEN true ELSE false END AS embedded,
               CASE WHEN pa.source_id IS NOT NULL THEN true ELSE false END AS promoted_audit
        FROM hermes_research_intelligence r
        LEFT JOIN content_embeddings ce ON ce.source_type='hermes_research' AND ce.source_id=r.id
        LEFT JOIN hermes_promotion_audit pa ON pa.source_id=r.id
        WHERE {' AND '.join(where)}
        ORDER BY r.created_at DESC LIMIT 100
    """, params=tuple(params) if params else None) or []

    # Enrich each row with workflow context
    def _classify(r):
        rt = r.get("research_type", "")
        topic = (r.get("topic") or "").lower()
        sym = r.get("symbol") or ""
        conf = r.get("confidence_score") or 0
        status = r.get("status", "")

        # Display category
        if rt == "ops_backlog":
            if "finviz" in topic or "cookie" in topic or "feed" in topic:
                cat, domain = "OPS_FEED", "Feed Health"
            elif "maria" in topic or "agent" in topic or "stale" in topic:
                cat, domain = "OPS_AGENT", "Agent Health"
            elif "gemma" in topic or "ollama" in topic or "llm" in topic or "queue" in topic:
                cat, domain = "OPS_LLM", "LLM Queue Health"
            elif "pipeline" in topic or "cron" in topic:
                cat, domain = "OPS_PIPELINE", "Pipeline Health"
            else:
                cat, domain = "OPS", "System Operations"
        elif rt == "research_backlog":
            if "backtest" in topic or "strategy" in topic or "scalp" in topic:
                cat, domain = "STRATEGY", "Strategy Learning"
            elif "income" in topic or "dividend" in topic or "portfolio" in topic:
                cat, domain = "PORTFOLIO", "Portfolio Research"
            else:
                cat, domain = "RESEARCH", "Research Backlog"
        elif "source_discovery" in rt:
            cat, domain = "SOURCE_DISCOVERY", "Source Discovery"
        elif rt == "pipeline_quality_validation":
            cat, domain = "OPS_PIPELINE", "Pipeline Quality"
        elif rt == "ticker_challenger" and sym:
            cat, domain = sym, "Ticker Analysis"
        elif sym:
            cat, domain = sym, "Symbol Research"
        else:
            cat, domain = "SYSTEM", "System"

        # Workflow stage
        if status == "promoted":
            stage, stage_order = "Promoted to Production", 5
        elif r.get("embedded"):
            stage, stage_order = "Embedded in RAG", 4
        elif status == "staged" and conf >= 0.5:
            stage, stage_order = "Ready for Review", 3
        elif status == "staged":
            stage, stage_order = "Staged — Needs Quality Check", 2
        elif status == "rejected":
            stage, stage_order = "Rejected", 0
        else:
            stage, stage_order = "New / Unprocessed", 1

        # Owner agent
        owner = r.get("hermes_agent_name") or ("ticker_challenger" if rt == "ticker_challenger" else "hermes_research")

        # Priority
        if cat.startswith("OPS") and conf < 0.4:
            priority = "HIGH"
        elif cat == "STRATEGY" or (sym and conf >= 0.5):
            priority = "MEDIUM"
        else:
            priority = "LOW"

        # Next action
        if status == "promoted":
            next_action = "Monitor — already in production cache"
        elif status == "rejected":
            next_action = "No action — rejected"
        elif cat == "OPS_FEED":
            next_action = "Verify feed health, rotate credentials if failing"
        elif cat == "OPS_AGENT":
            next_action = "Check agent output freshness, restart if stale"
        elif cat == "OPS_LLM":
            next_action = "Review LLM queue failures, check model health"
        elif cat == "OPS_PIPELINE":
            next_action = "Review pipeline run status, check for failures"
        elif cat == "STRATEGY":
            next_action = "Review strategy findings, validate against backtest data"
        elif cat == "SOURCE_DISCOVERY":
            next_action = "Classify source relevance, archive if not portfolio-linked"
        elif cat == "PORTFOLIO":
            next_action = "Review portfolio-level insight for rebalance/allocation"
        elif sym and conf >= 0.5:
            next_action = f"Review {sym} thesis, consider for incubator or watchlist"
        elif sym:
            next_action = f"Quality-check {sym} research, improve if low confidence"
        else:
            next_action = "Review and classify"

        # Why it matters
        if cat.startswith("OPS"):
            why = "Operational issue that may affect pipeline reliability or data freshness"
        elif cat == "STRATEGY":
            why = "Strategy-level insight that could improve trading rules or parameters"
        elif cat == "SOURCE_DISCOVERY":
            why = "New research source that may improve intelligence quality"
        elif sym:
            why = f"Hermes research on {sym} — may surface actionable trade thesis"
        else:
            why = "System-level finding requiring operator awareness"

        # Blocker
        blocker = None
        if conf < 0.3:
            blocker = "Very low confidence — needs evidence improvement"
        elif status == "staged" and not r.get("embedded"):
            blocker = "Not yet embedded — awaiting embedding worker"

        r["display_category"] = cat
        r["domain"] = domain
        r["workflow_stage"] = stage
        r["workflow_stage_order"] = stage_order
        r["owner_agent"] = owner
        r["operator_priority"] = priority
        r["why_it_matters"] = why
        r["recommended_next_action"] = next_action
        r["blocker_reason"] = blocker
        return r

    enriched = [_classify({k: _json_clean(v) for k, v in r.items()}) for r in rows]

    # Post-query category filter (display_category is computed, not in DB)
    if category_f:
        enriched = [r for r in enriched if r.get("display_category") == category_f or r.get("display_category", "").startswith(category_f + "_")]

    return {"ok": True, "items": enriched, "total": len(enriched)}


def _hermes_proposal_sandbox():
    """GET /api/v2/hermes/proposal-sandbox — read-only file-based proposal draft packets."""
    import json as _jps
    drafts_dir = Path.home() / ".hermes" / "drafts" / "proposals"  # global (sidecar retired 2026-06-06)
    packets = []
    if drafts_dir.exists():
        for f in sorted(drafts_dir.glob("*.json")):
            try:
                d = _jps.loads(f.read_text())
                packets.append({
                    "filename": f.name,
                    "symbol": d.get("symbol"),
                    "company": d.get("company"),
                    "sector": d.get("sector"),
                    "thesis_summary": d.get("thesis", {}).get("summary"),
                    "strategy_fit": d.get("thesis", {}).get("strategy_fit"),
                    "timeframe": d.get("thesis", {}).get("timeframe"),
                    "direction": d.get("thesis", {}).get("direction"),
                    "composite_score": d.get("quality_scores", {}).get("composite"),
                    "quality_scores": d.get("quality_scores"),
                    "catalyst": d.get("evidence", {}).get("catalyst"),
                    "technical": d.get("evidence", {}).get("technical"),
                    "why_not_trade": d.get("why_not_trade", []),
                    "review_checklist": d.get("required_human_review", {}).get("review_checklist", []),
                    "risk": d.get("risk"),
                    "portfolio_fit": d.get("portfolio_fit"),
                    "generated_by": d.get("generated_by"),
                    "generated_at": d.get("generated_at"),
                    "execution_statement": d.get("execution_statement"),
                })
            except Exception:
                pass
    return {
        "packets": packets,
        "total": len(packets),
        "sandbox_type": "FILE_ONLY",
        "level7": "PROHIBITED",
        "advisory_notice": "These are file-only sandbox drafts. NOT proposals. NOT trades. Read-only visibility.",
    }


def _hermes_sl_timeline():
    """GET /api/v2/hermes/self-learning/timeline — recent events across all systems."""
    events = []
    # Recent staged rows
    for r in (_db_query("SELECT id, symbol, research_type, created_at FROM hermes_research_intelligence ORDER BY created_at DESC LIMIT 10") or []):
        events.append({"type": "staged", "id": r["id"], "symbol": r.get("symbol"), "detail": r.get("research_type"), "at": _json_clean(r["created_at"])})
    # Recent promotions
    for r in (_db_query("SELECT source_id, promoted_at FROM hermes_promotion_audit ORDER BY promoted_at DESC LIMIT 5") or []):
        events.append({"type": "promoted", "id": r["source_id"], "at": _json_clean(r["promoted_at"])})
    # Recent embeddings
    for r in (_db_query("SELECT source_id, created_at FROM content_embeddings WHERE source_type='hermes_research' ORDER BY created_at DESC LIMIT 5") or []):
        events.append({"type": "embedded", "id": r["source_id"], "at": _json_clean(r["created_at"])})
    # Recent advisory events
    for r in (_db_query("SELECT id, event_type, source_id, created_at FROM hermes_advisory_events ORDER BY created_at DESC LIMIT 5") or []):
        events.append({"type": "event", "id": r["id"], "detail": r.get("event_type"), "at": _json_clean(r["created_at"])})
    # Sort by time desc
    events.sort(key=lambda e: e.get("at", ""), reverse=True)
    return {"ok": True, "events": events[:20]}


def _hermes_self_learning_overview():
    """GET /api/v2/hermes/self-learning-overview — visual cockpit data."""
    import json as _jso
    # Hermes row counts
    rows = _db_query("SELECT COUNT(*) as total, COUNT(*) FILTER (WHERE status='staged') as staged, COUNT(*) FILTER (WHERE status='promoted') as promoted, COUNT(*) FILTER (WHERE research_type='research_backlog') as backlog, COUNT(*) FILTER (WHERE research_type='ops_backlog') as ops_backlog FROM hermes_research_intelligence", fetch="one") or {}
    # Embeddings
    emb = _db_query("SELECT COUNT(*) as c FROM content_embeddings WHERE source_type='hermes_research'", fetch="one") or {}
    # Cache
    cache = _db_query("SELECT COUNT(*) as c FROM llm_intelligence_cache WHERE section LIKE 'hermes_%'", fetch="one") or {}
    # Events
    events = _db_query("SELECT COUNT(*) as total, COUNT(*) FILTER (WHERE event_status='pending') as pending, COUNT(*) FILTER (WHERE event_status='completed') as completed, COUNT(*) FILTER (WHERE event_status='skipped') as skipped FROM hermes_advisory_events", fetch="one") or {}
    # LLM queue
    llm = _db_query("SELECT COUNT(*) as total, COUNT(*) FILTER (WHERE status='completed') as completed, COUNT(*) FILTER (WHERE status='failed') as failed FROM high_llm_job_queue", fetch="one") or {}
    # Age buckets
    age = _db_query("""
        SELECT CASE WHEN age <= 1 THEN '0-1d' WHEN age <= 3 THEN '2-3d' WHEN age <= 7 THEN '4-7d' ELSE '8d+' END as bucket, COUNT(*) as c
        FROM (SELECT EXTRACT(DAY FROM NOW()-created_at) as age FROM hermes_research_intelligence WHERE status='staged') sub
        GROUP BY bucket ORDER BY bucket
    """) or []
    # Agent touch
    agents = _db_query("SELECT hermes_agent_name, COUNT(*) as c, MAX(created_at) as last FROM hermes_research_intelligence GROUP BY hermes_agent_name ORDER BY c DESC") or []
    # Promotion review
    pr_path = Path(str(PROJECT_ROOT)) / "docs" / "hermes" / "promotion_reviews" / "latest_promotion_review.json"
    pr = {}
    if pr_path.exists():
        try:
            pr = _jso.loads(pr_path.read_text())
        except Exception:
            pass
    lanes = pr.get("lanes", {})
    # Feed health
    feed = _db_query("SELECT status, symbols_scanned FROM screener_run_health ORDER BY id DESC LIMIT 1", fetch="one") or {}
    # Observation
    obs_path = Path(str(PROJECT_ROOT)) / "docs" / "hermes" / "observations" / "latest_observation_summary.json"
    obs_ts = None
    if obs_path.exists():
        try:
            obs_ts = _jso.loads(obs_path.read_text()).get("timestamp")
        except Exception:
            pass

    return {
        "ok": True,
        "maturity": "LEVEL6_CERTIFIED_STABLE",
        "level7": "PROHIBITED",
        "hermes": {k: _json_clean(v) for k, v in rows.items()},
        "embeddings": emb.get("c", 0),
        "cache_sections": cache.get("c", 0),
        "events": {k: _json_clean(v) for k, v in events.items()},
        "llm_queue": {k: _json_clean(v) for k, v in llm.items()},
        "age_buckets": [{k: _json_clean(v) for k, v in a.items()} for a in age],
        "agents": [{k: _json_clean(v) for k, v in a.items()} for a in agents[:10]],
        "promotion_lanes": {k: len(v) for k, v in lanes.items()},
        "feed_health": {"status": feed.get("status", "UNKNOWN"), "symbols": feed.get("symbols_scanned", 0)},
        "last_observation": obs_ts,
    }


def _hermes_dual_opinion():
    """GET /api/v2/hermes/dual-opinion — side-by-side TradeAI vs Hermes opinions."""
    import json as _jdo
    opinions_dir = PROJECT_ROOT / "data" / "advisory" / "dual_opinion"
    if not opinions_dir.exists():
        return {"total": 0, "opinions": [], "advisory_notice": "No dual opinions generated yet."}
    # Find latest file
    files = sorted(opinions_dir.glob("*.json"), reverse=True)
    if not files:
        return {"total": 0, "opinions": [], "advisory_notice": "No dual opinions generated yet."}
    try:
        data = _jdo.loads(files[0].read_text())
        return data
    except Exception:
        return {"total": 0, "opinions": [], "advisory_notice": "Error reading dual opinion data."}


def _hermes_dual_opinion_inline():
    """GET /api/v2/hermes/dual-opinion/inline — filter dual opinions by symbol/strategy/type."""
    import json as _jdoi
    qs = _current_query or {}
    symbol_f = qs.get("symbol")
    strategy_f = qs.get("strategy")
    obj_type_f = qs.get("object_type")
    obj_id_f = qs.get("object_id")

    # Gather from all opinion sources
    all_opinions = []
    opinion_dirs = [
        PROJECT_ROOT / "data" / "advisory" / "dual_opinion",
        PROJECT_ROOT / "data" / "advisory" / "journal_dual_opinions",
        PROJECT_ROOT / "data" / "advisory" / "backtest_dual_opinions",
    ]
    for d in opinion_dirs:
        if not d.exists():
            continue
        for f in sorted(d.glob("*.json"), reverse=True)[:1]:
            try:
                data = _jdoi.loads(f.read_text())
                all_opinions.extend(data.get("opinions", []))
            except Exception:
                pass

    # Filter
    if symbol_f:
        all_opinions = [o for o in all_opinions if o.get("symbol") == symbol_f]
    if strategy_f:
        all_opinions = [o for o in all_opinions if o.get("strategy") == strategy_f]
    if obj_type_f:
        all_opinions = [o for o in all_opinions if o.get("object_type") == obj_type_f]
    if obj_id_f:
        all_opinions = [o for o in all_opinions if str(o.get("object_id")) == str(obj_id_f)]

    return {"opinions": all_opinions, "total": len(all_opinions)}


def _queue_control_tower():
    """GET /api/v2/system/queue-control-tower — actionable queue/timer/LLM view."""
    import subprocess as _sp_qct, glob as _glob_qct
    from datetime import datetime as _dtqct, timezone as _tzqct

    # ── Metadata for known jobs ──
    JOB_META = {
        "hermes-autonomous-loop": {"cat": "hermes_advisory", "llm": True, "model": "gemma3:12b", "writes": "hermes_research_intelligence", "telegram": False, "why": "Autonomous ticker challenger — stages research rows"},
        "hermes-advisory-cache-worker": {"cat": "hermes_advisory", "llm": True, "model": "gemma3:12b", "writes": "llm_intelligence_cache", "telegram": False, "why": "Promotes advisory cache from staged research"},
        "hermes-observation-check": {"cat": "hermes_advisory", "llm": False, "model": None, "writes": "observation report", "telegram": False, "why": "Checks Hermes research quality/drift"},
        "hermes-backlog-health-check": {"cat": "hermes_advisory", "llm": False, "model": None, "writes": "backlog health report", "telegram": False, "why": "Monitors research backlog staleness"},
        "hermes-embedding-promotion-review": {"cat": "hermes_advisory", "llm": False, "model": None, "writes": "promotion audit", "telegram": False, "why": "Reviews embeddings for promotion eligibility"},
        "hermes-librarian-backlog-loop": {"cat": "hermes_advisory", "llm": True, "model": "gemma3:12b", "writes": "hermes_research_intelligence", "telegram": False, "why": "Librarian researches backlog items"},
        "hermes-source-discovery-dryrun": {"cat": "hermes_research", "llm": True, "model": "gemma3:12b", "writes": "hermes_research_intelligence (dry-run)", "telegram": False, "why": "Discovers new research sources"},
        "hermes-momentum-catalyst-morning": {"cat": "market_morning", "llm": False, "model": None, "writes": "momentum catalyst JSONL", "telegram": False, "why": "SearXNG catalyst research for momentum candidates"},
        "hermes-shadow-scorer": {"cat": "hermes_research", "llm": False, "model": None, "writes": "shadow scores JSONL", "telegram": False, "why": "Shadow scoring — learning vs live comparison"},
        "high-llm-execution-worker": {"cat": "llm_queue", "llm": True, "model": "gemma3:12b/Gemma4 31B", "writes": "escalation results", "telegram": False, "why": "Executes high-priority LLM review jobs"},
        "tradeai-continuous": {"cat": "market_morning", "llm": False, "model": None, "writes": "trade_ai_scans", "telegram": False, "why": "Daily pipeline launcher — screener + enrichment + scoring"},
        "tradeai-reprice": {"cat": "market_hours", "llm": False, "model": None, "writes": "portfolio prices", "telegram": False, "why": "Market-hours portfolio repricing every 15 min"},
        "aegis-surveillance": {"cat": "portfolio", "llm": False, "model": None, "writes": "agent results", "telegram": True, "why": "Morning surveillance sweep"},
        "aegis-overnight": {"cat": "overnight", "llm": True, "model": "gemma3:12b", "writes": "agent results", "telegram": False, "why": "Overnight intelligence synthesis"},
        "portfolio-daily": {"cat": "portfolio", "llm": False, "model": None, "writes": "portfolio snapshots", "telegram": False, "why": "Daily portfolio pipeline"},
        "portfolio-backup": {"cat": "overnight", "llm": False, "model": None, "writes": "backup files", "telegram": False, "why": "Nightly portfolio backup"},
        "recovery-watch": {"cat": "portfolio", "llm": False, "model": None, "writes": "stopped_out_watch", "telegram": False, "why": "Check stopped-out positions for re-entry"},
        "db-retention": {"cat": "overnight", "llm": False, "model": None, "writes": "DB cleanup", "telegram": False, "why": "Weekly data retention / cleanup"},
        "trade-ai-news-monitor": {"cat": "market_hours", "llm": False, "model": None, "writes": "news_articles", "telegram": True, "why": "News monitoring and alert routing"},
    }

    # ── Get runtime status via helper ──
    runtime_status = {}
    try:
        _qenv = dict(os.environ)
        _qenv["DBUS_SESSION_BUS_ADDRESS"] = f"unix:path=/run/user/{os.getuid()}/bus"
        _rs = _sp_qct.run([str(PROJECT_ROOT / ".venv/bin/python"), str(PROJECT_ROOT / "scripts/queue_runtime_status.py"), "--json"],
                          capture_output=True, text=True, timeout=10, cwd=str(PROJECT_ROOT), env=_qenv)
        if _rs.returncode == 0:
            import json as _jrt
            runtime_status = _jrt.loads(_rs.stdout)
    except Exception:
        pass

    # ── Read timer unit files ──
    seen = set()
    timers = []
    for td in [str(Path.home() / ".config/systemd/user"), "/etc/systemd/system"]:
        for tf in _glob_qct.glob(f"{td}/*.timer"):
            name = Path(tf).stem  # without .timer
            if name in seen:
                continue
            seen.add(name)
            schedule = ""
            try:
                for line in Path(tf).read_text().splitlines():
                    if line.strip().startswith("OnCalendar="):
                        schedule = line.split("=", 1)[1].strip()
                        break
            except Exception:
                pass
            meta = JOB_META.get(name, {})
            rt = runtime_status.get(name, {})
            next_run = rt.get("next_run", "")
            last_trigger = rt.get("last_trigger", "")
            svc_result = rt.get("service_result", "unknown")
            svc_state = rt.get("service_state", "unknown")

            # Compute minutes until next run
            next_in_min = None
            if next_run:
                try:
                    from dateutil import parser as _dp
                    _nr = _dp.parse(next_run)
                    next_in_min = max(0, int((_nr - _dtqct.now(_nr.tzinfo or _tzqct.utc)).total_seconds() / 60))
                except Exception:
                    pass

            timers.append({
                "job_id": name,
                "display_name": name.replace("-", " ").replace("_", " ").title(),
                "category": meta.get("cat", "other"),
                "schedule": schedule or "see unit file",
                "source": "user" if ".config" in td else "system",
                "uses_llm": meta.get("llm", False),
                "model": meta.get("model"),
                "writes_to": meta.get("writes"),
                "sends_telegram": meta.get("telegram", False),
                "why_it_matters": meta.get("why", ""),
                "next_run": next_run,
                "next_run_in_min": next_in_min,
                "last_trigger": last_trigger,
                "last_result": svc_result,
                "service_state": svc_state,
                "status_icon": "🟢" if svc_result == "success" else "🔴" if svc_result == "failed" else "⚪",
            })

    # ── System services (24/7) ──
    services = []
    try:
        r = _sp_qct.run(["systemctl", "list-units", "--type=service", "--state=running", "--no-pager", "--plain"], capture_output=True, text=True, timeout=5)
        for line in r.stdout.strip().splitlines():
            if any(k in line for k in ["trade", "ollama", "portfolio", "hermes"]):
                svc = line.strip().split()[0]
                services.append({"name": svc, "status": "running", "category": "24x7_services"})
    except Exception:
        pass

    # ── Ollama ──
    ollama_models = []
    try:
        import urllib.request as _ur_qct, json as _j_qct
        resp = _ur_qct.urlopen("http://127.0.0.1:11434/api/ps", timeout=3)
        ollama_models = [m["name"] for m in _j_qct.loads(resp.read()).get("models", [])]
    except Exception:
        pass

    # ── Cron count ──
    cron_count = 0
    try:
        r = _sp_qct.run(["crontab", "-l"], capture_output=True, text=True, timeout=3)
        cron_count = sum(1 for l in r.stdout.splitlines() if l.strip() and not l.startswith("#") and "=" not in l.split()[0])
    except Exception:
        pass

    # ── Categorize ──
    categories = {}
    for t in timers:
        c = t["category"]
        categories.setdefault(c, []).append(t)
    for s in services:
        categories.setdefault("24x7_services", []).append(s)

    # ── LLM jobs (scheduled) ──
    llm_jobs = [t for t in timers if t.get("uses_llm")]
    telegram_jobs = [t for t in timers if t.get("sends_telegram")]

    # ── Real LLM queue from high_llm_job_queue ──
    real_queue = []
    queue_stats = {"pending": 0, "approved": 0, "running": 0, "completed": 0, "failed": 0, "rejected": 0, "blocked": 0}
    try:
        _qrows = _db_query("""
            SELECT id, job_type, source_system, process_type, status,
                   priority_score, preferred_model, fallback_model,
                   urgency, portfolio_impact, operator_value, evidence_gap_score,
                   quota_pool, expected_runtime_sec, advisory_only, not_execution,
                   error_message, retry_count,
                   created_at, scheduled_for, started_at, finished_at
            FROM high_llm_job_queue
            ORDER BY priority_score DESC NULLS LAST LIMIT 30
        """) or []
        for r in _qrows:
            st = r.get("status", "unknown")
            if st in ("queued_for_review", "dry_run_candidate", "pending"):
                queue_stats["pending"] += 1
            elif st == "approved":
                queue_stats["approved"] += 1
            elif st == "running":
                queue_stats["running"] += 1
            elif st == "completed":
                queue_stats["completed"] += 1
            elif st == "failed":
                queue_stats["failed"] += 1
            elif st == "rejected":
                queue_stats["rejected"] += 1
            else:
                queue_stats["blocked"] += 1
            real_queue.append({
                "queue_id": r["id"],
                "job_type": r.get("job_type"),
                "source": r.get("source_system"),
                "process_type": r.get("process_type"),
                "status": st,
                "priority_score": r.get("priority_score"),
                "model": r.get("preferred_model"),
                "fallback_model": r.get("fallback_model"),
                "urgency": r.get("urgency"),
                "portfolio_impact": r.get("portfolio_impact"),
                "operator_value": r.get("operator_value"),
                "evidence_gap": r.get("evidence_gap_score"),
                "pool": r.get("quota_pool"),
                "runtime_sec": r.get("expected_runtime_sec"),
                "advisory_only": r.get("advisory_only"),
                "not_execution": r.get("not_execution"),
                "error_message": r.get("error_message"),
                "retry_count": r.get("retry_count", 0),
                "created_at": _json_clean(r.get("created_at")),
                "scheduled_for": _json_clean(r.get("scheduled_for")),
                "started_at": _json_clean(r.get("started_at")),
                "finished_at": _json_clean(r.get("finished_at")),
            })
    except Exception:
        pass
    next_queued = next((q for q in real_queue if q["status"] in ("queued_for_review", "dry_run_candidate", "pending")), None)

    # ── Due next (sorted by next_run_in_min) ──
    due_next = sorted([t for t in timers if t.get("next_run_in_min") is not None], key=lambda t: t["next_run_in_min"])[:10]

    # ── Needs attention ──
    failed = [t for t in timers if t.get("last_result") == "failed"]
    stale = [t for t in timers if t.get("service_state") == "failed"]

    return {
        "timestamp": _dtqct.now(_tzqct.utc).isoformat(),
        "timers_total": len(timers),
        "cron_count": cron_count,
        "services_running": len(services),
        "ollama_loaded": ollama_models,
        "llm_jobs": len(llm_jobs),
        "telegram_capable_jobs": len(telegram_jobs),
        "failed_jobs": len(failed),
        "categories": {k: len(v) for k, v in categories.items()},
        "sections": {
            "24x7_services": [{"name": s["name"], "status": s["status"]} for s in services],
            "llm_scheduled": [{"job_id": j["job_id"], "model": j["model"], "schedule": j["schedule"], "why": j["why_it_matters"], "next_run": j.get("next_run"), "last_result": j.get("last_result")} for j in llm_jobs],
            "telegram_capable": [{"job_id": j["job_id"], "why": j["why_it_matters"]} for j in telegram_jobs],
            "due_next": [{"job_id": t["job_id"], "next_run": t["next_run"], "next_in_min": t["next_run_in_min"], "category": t["category"], "uses_llm": t["uses_llm"], "status_icon": t["status_icon"]} for t in due_next],
            "needs_attention": [{"job_id": t["job_id"], "reason": "last run failed", "last_result": t["last_result"]} for t in failed] + [{"job_id": t["job_id"], "reason": "service failed", "service_state": t["service_state"]} for t in stale],
            "real_llm_queue": {
                "source": "high_llm_job_queue",
                "source_status": "CONNECTED" if real_queue else "EMPTY",
                "total": len(real_queue),
                "stats": queue_stats,
                "next_job": next_queued,
                "items": real_queue,
            },
        },
        "all_jobs": timers,
    }


def _hermes_advisory_choices():
    """GET /api/v2/hermes/advisory-choices — advisory choice audit dashboard."""
    import json as _jac
    choices_dir = PROJECT_ROOT / "data" / "advisory" / "operator_choices"
    all_choices = []
    if choices_dir.exists():
        for f in sorted(choices_dir.glob("*.jsonl"), reverse=True)[:7]:
            for line in f.read_text().splitlines():
                if line.strip():
                    try: all_choices.append(_jac.loads(line))
                    except: pass
    counts = {}
    for c in all_choices:
        ch = c.get("operator_choice", "unknown")
        counts[ch] = counts.get(ch, 0) + 1
    return {
        "total": len(all_choices),
        "counts": counts,
        "recent": all_choices[:20],
    }


def _cron_compression_view():
    """GET /api/v2/system/cron-compression — grouped cron analysis with duplicate/overlap detection."""
    import re as _recron, subprocess as _spcron
    from collections import defaultdict as _ddcron
    try:
        _r = _spcron.run(["crontab", "-l"], capture_output=True, text=True, timeout=5)
        lines = [l.strip() for l in _r.stdout.strip().splitlines() if l.strip() and not l.strip().startswith('#')]
    except Exception:
        return {"error": "crontab not accessible"}

    entries = []
    env_vars = {}
    for line in lines:
        # Variable assignments
        if '=' in line and not any(c in line.split('=')[0] for c in ' */'):
            parts = line.split('=', 1)
            if all(c.isalpha() or c == '_' for c in parts[0]):
                env_vars[parts[0]] = parts[1]
                continue

        m = _recron.match(r'^([\S]+\s+[\S]+\s+[\S]+\s+[\S]+\s+[\S]+)\s+(.+)$', line)
        if not m:
            continue
        schedule, command = m.group(1), m.group(2)

        script_match = _recron.search(r'(?:python|python3|\$PY)\s+(?:scripts/)?(\S+\.py)', command)
        if script_match:
            script = script_match.group(1)
        else:
            script_match = _recron.search(r'(?:bash\s+)?(?:scripts/)?(\S+\.sh)', command)
            script = script_match.group(1) if script_match else command.split()[-1].split('/')[-1]

        log_match = _recron.search(r'>>\s*(?:\S*/)?(\S+\.log)', command)
        log = log_match.group(1) if log_match else None
        has_flock = 'flock' in command
        lock_match = _recron.search(r'/tmp/(\S+\.lock)', command)
        lock = lock_match.group(1) if lock_match else None

        dow = schedule.split()[4]
        hours = schedule.split()[1]
        is_weekday = dow in ('1-5',)
        is_weekend = dow in ('0,6', '6', '0')
        is_market = is_weekday and any(h in hours for h in ['9', '10', '11', '12', '13', '14', '15', '16'])

        entries.append({
            "schedule": schedule, "script": script, "log": log,
            "has_flock": has_flock, "lock_file": lock,
            "is_weekday": is_weekday, "is_weekend": is_weekend, "is_market_hours": is_market,
            "raw": command[:120],
        })

    groups = _ddcron(list)
    for e in entries:
        groups[e["script"]].append(e)

    duplicates = []
    for script, group in groups.items():
        if len(group) > 1:
            schedules = [g["schedule"] for g in group]
            duplicates.append({
                "script": script, "count": len(group), "schedules": schedules,
                "shared_lock": group[0]["lock_file"] if all(g["lock_file"] == group[0]["lock_file"] for g in group) else None,
            })

    lock_groups = _ddcron(list)
    for e in entries:
        if e["lock_file"]:
            lock_groups[e["lock_file"]].append(e["script"])
    overlaps = []
    for lock, scripts in lock_groups.items():
        unique = list(set(scripts))
        if len(unique) > 1:
            overlaps.append({"lock": lock, "scripts": unique})

    market_count = sum(1 for e in entries if e["is_market_hours"])
    overnight_count = sum(1 for e in entries if not e["is_market_hours"] and e["is_weekday"])
    weekend_count = sum(1 for e in entries if e["is_weekend"])
    always_count = len(entries) - market_count - overnight_count - weekend_count
    script_counts = sorted([(s, len(g)) for s, g in groups.items()], key=lambda x: -x[1])

    return {
        "total_crons": len(entries),
        "unique_scripts": len(groups),
        "env_vars": len(env_vars),
        "with_flock": sum(1 for e in entries if e["has_flock"]),
        "categories": {"market_hours": market_count, "overnight_weekday": overnight_count, "weekend": weekend_count, "always": always_count},
        "duplicates": sorted(duplicates, key=lambda d: -d["count"]),
        "lock_overlaps": overlaps,
        "top_scripts": [{"script": s, "entries": c} for s, c in script_counts[:15]],
        "groups": {
            script: [{"schedule": g["schedule"], "has_flock": g["has_flock"], "lock_file": g["lock_file"], "log": g["log"]}
                     for g in group]
            for script, group in sorted(groups.items(), key=lambda x: -len(x[1]))[:30]
        },
    }


def _inbox():
    """GET /api/v2/inbox — operator inbox: escalations + CIO human-review + pending proposals."""
    esc = _db_query("""SELECT symbol, from_agent, to_agent, reason, action_type, created_at
                       FROM agent_handoffs WHERE escalated=TRUE AND created_at > NOW() - INTERVAL '14 days'
                       ORDER BY created_at DESC LIMIT 60""") or []
    cio = _db_query("""SELECT symbol, action, action_class, rationale, priority, created_at
                       FROM cio_decisions WHERE human_review_required=TRUE AND created_at > NOW() - INTERVAL '14 days'
                       ORDER BY created_at DESC LIMIT 40""") or []
    props = _db_query("""SELECT symbol, strategy_id, status, created_at FROM paper_trade_proposals
                         WHERE status IN ('PENDING','APPROVED') ORDER BY created_at DESC LIMIT 30""") or []
    items = []
    for e in esc:
        items.append({"type": "escalation", "symbol": e.get("symbol"), "detail": e.get("reason") or e.get("action_type"),
                      "source": f"{e.get('from_agent')}→{e.get('to_agent')}", "at": _json_clean(e.get("created_at"))})
    for c in cio:
        items.append({"type": "cio_review", "symbol": c.get("symbol"), "detail": (c.get("action") or "") + " · " + (c.get("rationale") or "")[:80],
                      "source": f"CIO · {c.get('priority') or ''}", "at": _json_clean(c.get("created_at"))})
    for p in props:
        items.append({"type": "proposal", "symbol": p.get("symbol"), "detail": p.get("status"),
                      "source": p.get("strategy_id"), "at": _json_clean(p.get("created_at"))})
    items.sort(key=lambda x: x.get("at") or "", reverse=True)
    return {"count": len(items), "escalations": len(esc), "cio_review": len(cio), "proposals": len(props), "items": items}


def _weekly_learning():
    """GET /api/v2/weekly-learning — weekly trade-review learning + agent performance trend."""
    reviews = _db_query("""SELECT paper_trade_id, tier, model_used, LEFT(review_text, 600) as review, created_at
                           FROM paper_trade_multi_reviews ORDER BY created_at DESC LIMIT 20""") or []
    by_tier = {r["tier"]: 0 for r in reviews}
    for r in reviews:
        by_tier[r["tier"]] = by_tier.get(r["tier"], 0) + 1
    perf = _db_query("""SELECT agent, accuracy_pct, total_recommendations, avg_confidence, period_start, period_end
                        FROM agent_performance ORDER BY period_end DESC LIMIT 12""") or []
    return {
        "review_count": len(reviews),
        "by_tier": [{"tier": k, "count": v} for k, v in by_tier.items()],
        "reviews": [{k: _json_clean(v) for k, v in r.items()} for r in reviews],
        "agent_performance": [{k: _json_clean(v) for k, v in p.items()} for p in perf],
    }


def _system_siem_dashboard():
    """GET /api/v2/system/siem — SIEM-lite alert dashboard with live normalization."""
    import json as _jsiem
    from datetime import datetime as _dtsiem, timezone as _tzsiem, timedelta as _tdsiem

    cutoff = _dtsiem.now(_tzsiem.utc) - _tdsiem(days=14)

    # Source 1: alert_events (resolved alerts age out of the active SIEM view)
    ae_rows = _db_query("""
        SELECT id, alert_type, symbol, severity, source_script,
               LEFT(raw_text, 200) as raw_text, created_at, lifecycle_state
        FROM alert_events WHERE created_at > %s AND COALESCE(lifecycle_state,'active') <> 'resolved'
        ORDER BY created_at DESC LIMIT 200
    """, [cutoff]) or []

    # Source 2: system_health_events
    she_rows = _db_query("""
        SELECT id, event_type, component, severity, LEFT(message, 200) as message, created_at, lifecycle_state
        FROM system_health_events WHERE created_at > %s AND COALESCE(lifecycle_state,'active') <> 'resolved'
        ORDER BY created_at DESC LIMIT 200
    """, [cutoff]) or []

    # Source 3: notification_log (telegram)
    nl_rows = _db_query("""
        SELECT id, channel, notification_type, LEFT(subject, 100) as subject,
               LEFT(body_summary, 200) as body, created_at
        FROM notification_log WHERE created_at > %s AND channel LIKE '%%telegram%%'
        ORDER BY created_at DESC LIMIT 100
    """, [cutoff]) or []

    # Source 4: hermes_alerts (research-layer findings)
    ha_rows = _db_query("""
        SELECT id, hermes_agent_name, alert_type, severity, symbol,
               LEFT(COALESCE(title,'') || ' ' || COALESCE(description,''), 200) as msg, created_at
        FROM hermes_alerts WHERE created_at > %s ORDER BY created_at DESC LIMIT 100
    """, [cutoff]) or []

    # Source 5: open_trade_alerts
    ota_rows = _db_query("""
        SELECT id, symbol, alert_type, severity,
               LEFT(COALESCE(title,'') || ' ' || COALESCE(message,''), 200) as msg, created_at
        FROM open_trade_alerts WHERE created_at > %s ORDER BY created_at DESC LIMIT 100
    """, [cutoff]) or []

    # Classify events → (type, severity P0..P3). Order matters (first match wins).
    def _classify(text):
        t = (text or "").lower()
        if "stop" in t and ("trigger" in t or "hit" in t): return "STOP_TRIGGERED", "P1"
        if "connection already closed" in t or "interfaceerror" in t or "operationalerror" in t: return "DB_CONNECTION", "P1"
        if "output_invalid" in t or "locktimeout" in t or "retry_exhausted" in t or "python_exception" in t: return "PIPELINE_FAILURE", "P1"
        if "cookie" in t or ("finviz" in t and "expired" in t): return "FEED_HEALTH", "P1"
        if "503" in t or "service unavailable" in t or "saturat" in t or ("llm" in t and "timeout" in t): return "LLM_SATURATION", "P2"
        if "stale" in t and ("agent" in t or "maria" in t or "ingest" in t or "transcript" in t): return "STALENESS", "P2"
        if "llm" in t and ("escalat" in t or "tier" in t): return "LLM_ESCALATION", "P2"
        if "backlog" in t or "queued" in t: return "QUEUE_BACKLOG", "P2"
        if "data quality" in t or "data integrity" in t or "zero" in t: return "DATA_QUALITY", "P2"
        if "exit reason" in t and ("blank" in t or "''" in t): return "CLOSED_TRADE_REVIEW", "P2"
        if "escalation_deduped" in t or "reaped" in t or "adopted" in t: return "JOB_RECOVERY", "P3"
        return "SYSTEM_HEALTH", "P3"

    events = []
    for r in ae_rows:
        etype, esev = _classify(r.get("raw_text", "") + " " + (r.get("alert_type") or ""))
        events.append({
            "id": f"ae-{r['id']}", "timestamp": _json_clean(r["created_at"]),
            "source": "alert_events", "event_type": etype, "severity": esev,
            "symbol": r.get("symbol"), "component": r.get("source_script"),
            "message": r.get("raw_text", "")[:150], "lifecycle_state": r.get("lifecycle_state") or "active",
            "dedupe_key": f"{etype}:{r.get('symbol','sys')}:{r.get('source_script','?')}",
        })
    for r in she_rows:
        etype, esev = _classify((r.get("message") or "") + " " + (r.get("event_type") or ""))
        events.append({
            "id": f"she-{r['id']}", "timestamp": _json_clean(r["created_at"]),
            "source": "system_health_events", "event_type": etype, "severity": esev,
            "symbol": None, "component": r.get("component"),
            "message": r.get("message", "")[:150], "lifecycle_state": r.get("lifecycle_state") or "active",
            "dedupe_key": f"{etype}:sys:{r.get('component','?')}",
        })
    for r in nl_rows:
        text = (r.get("subject") or "") + " " + (r.get("body") or "")
        etype, esev = _classify(text)
        # notification_log is our OWN outbound delivery record — every alert worth a
        # P0/P1/P2 is detected upstream (alert_events / open_trade_alerts / system_health)
        # and written there first, then dispatched to telegram. Counting the telegram echo
        # at the source severity double-counts it (e.g. STOP_TRIGGERED showing 38 P1 events
        # that are really our own stop notifications). Demote echoes to P3 noise tier and tag
        # them so they group separately and never inflate the immediate/P1 view.
        esev = "P3"
        events.append({
            "id": f"nl-{r['id']}", "timestamp": _json_clean(r["created_at"]),
            "source": "notification_log", "event_type": etype, "severity": esev,
            "symbol": None, "component": "telegram", "echo": True,
            "message": text[:150],
            "dedupe_key": f"{etype}:echo:telegram",
        })

    for r in ha_rows:
        etype, esev = _classify((r.get("msg") or "") + " " + (r.get("alert_type") or ""))
        events.append({
            "id": f"ha-{r['id']}", "timestamp": _json_clean(r["created_at"]),
            "source": "hermes_alerts", "event_type": etype, "severity": esev,
            "symbol": r.get("symbol"), "component": r.get("hermes_agent_name") or "hermes",
            "message": (r.get("msg") or "")[:150],
            "dedupe_key": f"{etype}:{r.get('symbol','sys')}:{r.get('hermes_agent_name','hermes')}",
        })
    for r in ota_rows:
        etype, esev = _classify((r.get("msg") or "") + " " + (r.get("alert_type") or ""))
        events.append({
            "id": f"ota-{r['id']}", "timestamp": _json_clean(r["created_at"]),
            "source": "open_trade_alerts", "event_type": etype, "severity": esev,
            "symbol": r.get("symbol"), "component": "open_trades",
            "message": (r.get("msg") or "")[:150],
            "dedupe_key": f"{etype}:{r.get('symbol','sys')}:open_trades",
        })

    events.sort(key=lambda e: e.get("timestamp") or "", reverse=True)

    # Dedupe analysis
    dedupe = {}
    for e in events:
        dk = e["dedupe_key"]
        if dk not in dedupe:
            dedupe[dk] = {"count": 0, "severity": e["severity"], "event_type": e["event_type"],
                          "component": e.get("component"), "first": e["timestamp"], "last": e["timestamp"]}
        dedupe[dk]["count"] += 1
        # events are sorted newest-first, so track true earliest/latest explicitly
        # (ISO8601 strings share a fixed tz offset → lexical min/max is chronological).
        dedupe[dk]["first"] = min(dedupe[dk]["first"], e["timestamp"])
        dedupe[dk]["last"] = max(dedupe[dk]["last"], e["timestamp"])

    for e in events:
        g = dedupe[e["dedupe_key"]]
        e["repeat_count"] = g["count"]
        e["suppressed"] = g["count"] > 3

    # Severity summary
    sev = {"P0": 0, "P1": 0, "P2": 0, "P3": 0}
    for e in events:
        if not e["suppressed"]:
            sev[e["severity"]] = sev.get(e["severity"], 0) + 1

    # Type summary
    type_counts = {}
    for e in events:
        t = e["event_type"]
        type_counts[t] = type_counts.get(t, 0) + 1

    suppressed_count = sum(1 for e in events if e["suppressed"])
    immediate_count = sum(1 for e in events if not e["suppressed"] and e["severity"] in ("P0", "P1"))

    # Collapse events by dedupe_key — show latest per group with count
    collapsed = {}
    for e in events:
        dk = e["dedupe_key"]
        if dk not in collapsed:
            collapsed[dk] = e.copy()
        else:
            # Keep the most recent one
            if (e.get("timestamp") or "") > (collapsed[dk].get("timestamp") or ""):
                old_count = collapsed[dk]["repeat_count"]
                collapsed[dk] = e.copy()
                collapsed[dk]["repeat_count"] = old_count
    # Critical-first: severity rank (P0..P3), then most-recent.
    _rank = {"P0": 0, "P1": 1, "P2": 2, "P3": 3}
    for e in collapsed.values():
        g = dedupe[e["dedupe_key"]]
        e["first_seen"] = g["first"]; e["last_seen"] = g["last"]
    collapsed_list = sorted(collapsed.values(), key=lambda e: e.get("timestamp") or "", reverse=True)
    collapsed_list = sorted(collapsed_list, key=lambda e: _rank.get(e["severity"], 9))  # stable → critical-first

    # Correlation: cluster the deduped groups into incidents by (component, event_type) so related
    # errors read as one thing (e.g. all atm_auto_approver PIPELINE_FAILURE, or all LLM_SATURATION).
    corr = {}
    for k, v in dedupe.items():
        ck = f"{v.get('component') or '?'}|{v['event_type']}"
        c = corr.setdefault(ck, {"component": v.get("component"), "event_type": v["event_type"],
                                 "severity": v["severity"], "events": 0, "groups": 0,
                                 "first": v["first"], "last": v["last"]})
        c["events"] += v["count"]; c["groups"] += 1
        if _rank.get(v["severity"], 9) < _rank.get(c["severity"], 9):
            c["severity"] = v["severity"]
        c["first"] = min(c["first"], v["first"]); c["last"] = max(c["last"], v["last"])
    correlated = sorted(corr.values(),
                        key=lambda c: (_rank.get(c["severity"], 9), -c["events"]))[:20]

    return {
        "total_events": len(events),
        "unique_groups": len(collapsed),
        "suppressed": suppressed_count,
        "noise_reduction_pct": round(100 * suppressed_count / max(len(events), 1), 1),
        "immediate_alerts": immediate_count,
        "severity": sev,
        "type_counts": sorted([{"type": k, "count": v} for k, v in type_counts.items()], key=lambda x: -x["count"]),
        "top_dedupe_groups": sorted(
            [{"key": k, **v} for k, v in dedupe.items()],
            key=lambda x: -x["count"]
        )[:15],
        "recent_events": collapsed_list[:50],
        "correlated": correlated,
        "retention_days": 14,
        "period_days": 14,
    }


def _trade_integrity_audit():
    """GET /api/v2/trade-integrity-audit — latest dual (Trade AI + Hermes) audit per trade.

    Read-only. Returns the most recent audit row per trade with both verdicts, the active
    RED failures (excluding remediated historical phantoms), and Hermes review coverage.
    """
    rows = _db_query("""
        SELECT DISTINCT ON (paper_trade_id)
            paper_trade_id, symbol, account, broker, trade_state, trade_ai_verdict,
            trade_ai_checks, trade_ai_reasons, hermes_verdict, hermes_review_count,
            hermes_last_review_at, dual_status, remediated, audited_at
        FROM trade_integrity_audit
        ORDER BY paper_trade_id, audited_at DESC
    """) or []
    for r in rows:
        r["hermes_last_review_at"] = _json_clean(r.get("hermes_last_review_at"))
        r["audited_at"] = _json_clean(r.get("audited_at"))
    total = len(rows)
    def _ct(pred):
        return sum(1 for r in rows if pred(r))
    # Hermes coverage is measured over REVIEWABLE trades (closed only) — open positions can't be
    # reviewed, and cancelled orders are already excluded upstream by the audit.
    closed_total = _ct(lambda r: r["trade_state"] == "closed")
    closed_reviewed = _ct(lambda r: r["trade_state"] == "closed" and r["hermes_verdict"] == "REVIEWED")
    return {
        "trades": rows,
        "active_failures": [r for r in rows if r["dual_status"] == "RED"],
        "summary": {
            "total": total,
            "green": _ct(lambda r: r["dual_status"] == "GREEN"),
            "yellow": _ct(lambda r: r["dual_status"] == "YELLOW"),
            "red": _ct(lambda r: r["dual_status"] == "RED"),
            "remediated": _ct(lambda r: r.get("remediated")),
            "trade_ai_pass": _ct(lambda r: r["trade_ai_verdict"] == "PASS"),
            "trade_ai_fail": _ct(lambda r: r["trade_ai_verdict"] == "FAIL"),
            "hermes_reviewed": _ct(lambda r: r["hermes_verdict"] == "REVIEWED"),
            "hermes_unreviewed": _ct(lambda r: r["hermes_verdict"] == "UNREVIEWED"),
            "closed_total": closed_total,
            "closed_reviewed": closed_reviewed,
            "hermes_coverage_pct": round(100 * closed_reviewed / closed_total, 1) if closed_total else 0,
        },
        "last_audit": _json_clean(max((r["audited_at"] for r in rows), default=None)),
    }


