def _hermes_health():
    """GET /api/v2/hermes/health — Hermes gateway status + memory summary."""
    import urllib.request as _ur, json as _jh2
    status = "offline"
    try:
        resp = _ur.urlopen("http://localhost:18790/health", timeout=3)
        d = _jh2.loads(resp.read())
        status = d.get("status", "unknown")
    except Exception:
        pass

    # Read memory files (global Hermes home; sidecar retired 2026-06-06)
    mem_dir = Path.home() / ".hermes" / "memories"
    memories = []
    if mem_dir.exists():
        for f in sorted(mem_dir.iterdir()):
            if f.suffix == ".md":
                memories.append({"name": f.name, "size": f.stat().st_size,
                                 "modified": f.stat().st_mtime})

    # Read session count (global Hermes home)
    sess_dir = Path.home() / ".hermes" / "sessions"
    session_count = len(list(sess_dir.iterdir())) if sess_dir.exists() else 0

    # Hermes staging table counts
    hcounts = {}
    for tbl in ["hermes_research_intelligence", "hermes_validation_findings",
                "hermes_alerts", "hermes_memory_events"]:
        row = _db_query(f"SELECT COUNT(*) as cnt FROM {tbl}", fetch="one")
        hcounts[tbl] = row["cnt"] if row else 0

    # Research-fleet kill switch — canonical LIVE runtime path via the shared helper (Phase 214). The retired
    # sidecar .hermes/DISABLED path is ignored (audit-only). Touch data/runtime/HERMES_DISABLED to halt.
    kill_desc = {}
    try:
        import sys as _sysh
        _sysh.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from hermes_killswitch import describe_killswitch as _dk
        kill_desc = _dk()
        kill_active = bool(kill_desc.get("active"))
    except Exception:
        kill_file = Path(str(PROJECT_ROOT)) / "data" / "runtime" / "HERMES_DISABLED"
        kill_active = kill_file.exists()

    # Coordinator + embedding pipeline health (cron */15m; gateway optional)
    import subprocess as _sp_h
    loop_active = False
    try:
        r = _sp_h.run(["systemctl", "--user", "is-active", "hermes-autonomous-loop.timer"],
                       capture_output=True, text=True, timeout=5)
        loop_active = r.stdout.strip() == "active"
    except Exception:
        pass

    coord_row = _db_query(
        """SELECT created_at FROM hermes_memory_events
           WHERE hermes_agent_name='chief_hermes_coordinator' AND event_type='agent_state_change'
           ORDER BY created_at DESC LIMIT 1""",
        fetch="one",
    ) or {}
    coord_last = _json_clean(coord_row.get("created_at"))
    coord_active = False
    if coord_row.get("created_at"):
        try:
            from datetime import datetime, timezone
            ts = coord_row["created_at"]
            if hasattr(ts, "tzinfo") and ts.tzinfo:
                age_min = (datetime.now(timezone.utc) - ts.astimezone(timezone.utc)).total_seconds() / 60
            else:
                age_min = (datetime.now() - ts).total_seconds() / 60
            coord_active = age_min < 30
        except Exception:
            pass

    emb_stats = _db_query(
        """SELECT
             count(*) FILTER (WHERE embedding_status='pending') as pending,
             count(*) FILTER (WHERE embedding_status='completed') as completed,
             count(*) FILTER (WHERE embedding_status='failed') as failed
           FROM hermes_embedding_queue""",
        fetch="one",
    ) or {}
    promoted_n = (_db_query("SELECT count(*) as n FROM hermes_research_intelligence WHERE status='promoted'", fetch="one") or {}).get("n", 0)
    embedded_n = (_db_query("SELECT count(*) as n FROM content_embeddings WHERE source_type='hermes_research'", fetch="one") or {}).get("n", 0)

    return {
        "ok": True,
        "gateway_status": status,
        "memories": memories,
        "session_count": session_count,
        "staging_counts": hcounts,
        "kill_switch_active": kill_active,
        "kill_switch_path": "data/runtime/HERMES_DISABLED",
        "kill_switch": kill_desc,
        "autonomous_loop_active": coord_active or loop_active,
        "coordinator_active": coord_active,
        "coordinator_last_tick": coord_last,
        "embedding_queue": {
            "pending": int(emb_stats.get("pending") or 0),
            "completed": int(emb_stats.get("completed") or 0),
            "failed": int(emb_stats.get("failed") or 0),
        },
        "rag_pipeline": {
            "promoted": int(promoted_n or 0),
            "embedded": int(embedded_n or 0),
            "coverage_pct": round(int(embedded_n or 0) / max(int(promoted_n or 0), 1) * 100, 1),
        },
    }


def _atm_protection_coverage():
    """Phase 190F — ATM protection-coverage panel (read-only).

    Sources broker-verified protection metadata from
    hermes_v_open_position_protection_context (paper_trades, not brokerage JSON)."""
    rows = _db_query("SELECT * FROM hermes_v_open_position_protection_context ORDER BY paper_trade_id") or []
    LARGE_GAIN = 250.0
    defects = []
    protected_at_broker = db_tracked = untracked = no_stop = tp_missing = large_gain_no_pp = trailing_active = 0
    last_verif = None
    for r in rows:
        prot = r.get("protection_status")
        upnl = float(r.get("unrealized_pnl") or 0)
        tp = r.get("take_profit_price")
        if r.get("broker_stop_order_id"):
            protected_at_broker += 1; db_tracked += 1
        elif prot == "PROTECTED_UNRECORDED" or r.get("stop_loss") is not None:
            protected_at_broker += 1; untracked += 1
        else:
            no_stop += 1
        if tp is None:
            tp_missing += 1
        if upnl >= LARGE_GAIN and tp is None:
            large_gain_no_pp += 1
            defects.append({"symbol": r.get("symbol"), "defect": "large_gain_no_take_profit", "pnl": upnl})
        if r.get("trailing_active"):
            trailing_active += 1
        if prot == "NAKED":
            defects.append({"symbol": r.get("symbol"), "defect": "no_broker_stop"})
        elif untracked and not r.get("broker_stop_order_id"):
            defects.append({"symbol": r.get("symbol"), "defect": "broker_stop_db_untracked"})
        v = r.get("last_broker_protection_check_at") or r.get("stop_verified_at")
        if v and (last_verif is None or str(v) > str(last_verif)):
            last_verif = v
    return {
        "total_open_positions": len(rows),
        "protected_at_broker": protected_at_broker,
        "db_tracked_stops": db_tracked,
        "untracked_broker_stops": untracked,
        "no_broker_stop": no_stop,
        "take_profit_missing": tp_missing,
        "large_gain_no_profit_protection": large_gain_no_pp,
        "trailing_active": trailing_active,
        "last_protection_verification": str(last_verif) if last_verif else None,
        "defects_by_symbol": defects,
        "operator_action_required": bool(no_stop or untracked or large_gain_no_pp),
    }


def _atm_advisory_threshold_tuning():
    """Phase 198 — latest advisory threshold tuning run (read-only). Recommendation only;
    thresholds are advisory-model params (191D), NOT GO/WAIT, and are not auto-applied."""
    r = _db_query("""SELECT run_at, cases, giveback_cases, current_thresholds, current_performance,
                            recommended_thresholds, recommended_performance, full_sweep
                     FROM advisory_threshold_tuning ORDER BY run_at DESC LIMIT 1""", fetch="one")
    if not r:
        return {"available": False, "note": "No tuning run yet — run tune_advisory_thresholds.py"}
    out = {k: _json_clean(v) for k, v in r.items()}
    out["available"] = True
    out["note"] = ("Recommendation only — operator applies manually. Small/synthetic sample "
                   "(no live-advised trades closed yet); revisit as advised trades accumulate.")
    return out


def _atm_profit_protection_advisory():
    """Phase 191F — inline ATM profit-protection advisory (read-only, advisory-only).

    Latest advisory per open paper trade from atm_profit_protection_advisories:
    TradeAI action + reason, Hermes second opinion, and the supporting audit. Buttons
    in the UI are advisory-only until a separate operator-approved execution phase (192)."""
    rows = _db_query("""
        SELECT DISTINCT ON (paper_trade_id)
            paper_trade_id, symbol, created_at, data_state, tradeai_action, tradeai_reason,
            supporting_actions, hermes_opinion, hermes_reason, operator_action_required, audit_json
        FROM atm_profit_protection_advisories
        ORDER BY paper_trade_id, created_at DESC""") or []
    advisories = []
    for r in rows:
        a = r.get("audit_json") or {}
        if isinstance(a, str):
            try:
                a = json.loads(a)
            except Exception:
                a = {}
        advisories.append({
            "trade_id": r.get("paper_trade_id"), "symbol": r.get("symbol"),
            "as_of": str(r.get("created_at")), "data_state": r.get("data_state"),
            "tradeai": {
                "action": r.get("tradeai_action"), "reason": r.get("tradeai_reason"),
                "supporting": r.get("supporting_actions"),
                "unrealized_pnl": a.get("unrealized_pnl"), "unrealized_pct": a.get("unrealized_pct"),
                "current_broker_stop": a.get("current_broker_stop"),
                "stop_locks_profit": a.get("stop_locks_profit"),
                "profit_locked_usd": a.get("profit_locked_usd"),
                "giveback_to_stop_usd": a.get("giveback_to_stop_usd"),
                "take_profit_exists": a.get("take_profit_exists"),
                "trailing_threshold_met": a.get("trailing_threshold_met"),
            },
            "hermes": {"opinion": r.get("hermes_opinion"), "reason": r.get("hermes_reason")},
            "operator_action_required": r.get("operator_action_required"),
            "decision_support": [
                "Keep current stop", "Move to breakeven review", "Lock profit review",
                "Convert to trailing review", "Add take-profit review", "Needs more data",
            ],
        })
    return {"advisories": advisories,
            "action_required_count": sum(1 for x in advisories if x["operator_action_required"]),
            "note": "Advisory only — no stops moved, no orders placed. Execution gated to Phase 192."}


def _atm_advisory_outcomes():
    """Phase 193 — profit-protection advisory close-loop outcomes (read-only, learning).
    Frontend-neutral (v2 + v3). Summarizes operator accept/ignore + baseline give-back."""
    rows = _db_query("""SELECT * FROM protection_advisory_outcomes ORDER BY reconciled_at DESC, trade_id""") or []
    outcomes = [{k: _json_clean(v) for k, v in r.items()} for r in rows]
    closed = [o for o in outcomes if o.get("record_kind") == "final_closed"]
    baseline = [o for o in closed if not o.get("advisory_existed")]
    # give-back is only scored on trades with authoritative bar-based MFE (others are unknown)
    measurable = [o for o in baseline if o.get("mfe_source") == "bar_analysis"]
    measurable_gaveback = [o for o in measurable if o.get("gave_back_profit")]
    total_left = sum(float(o.get("profit_left_on_table_usd") or 0) for o in measurable)
    summary = {
        "total": len(outcomes),
        "closed": len(closed),
        "interim_open": len([o for o in outcomes if o.get("record_kind") == "interim_open"]),
        "operator_accepted": len([o for o in outcomes if o.get("operator_decision") == "accepted"]),
        "operator_ignored": len([o for o in outcomes if o.get("operator_decision") == "ignored"]),
        "baseline_no_advisory": len(baseline),
        "baseline_measurable_with_bar_mfe": len(measurable),
        "baseline_unmeasurable_no_mfe": len(baseline) - len(measurable),
        "baseline_gave_back_profit": len(measurable_gaveback),
        "baseline_gaveback_rate_pct_of_measurable": round(100 * len(measurable_gaveback) / len(measurable), 1) if measurable else None,
        "baseline_profit_left_on_table_usd": round(total_left, 2),
        "advisory_accuracy_confirmed": len([o for o in closed if o.get("advisory_accuracy") == "confirmed"]),
        "advisory_accuracy_contradicted": len([o for o in closed if o.get("advisory_accuracy") == "contradicted"]),
    }
    return {"summary": summary, "outcomes": outcomes,
            "note": "Learning telemetry. Give-back scored ONLY on trades with bar-based MFE; "
                    "others are honest unknowns. No execution."}


def _atm_profit_capture():
    """Phase 206 — canonical all-trades profit-capture analysis (read-only, advisory).

    Sources trade_profit_capture_analysis (all sources: alpaca_paper + schwab_import). Give-back
    is measured ONLY where bar-based MFE exists; others are honestly flagged DATA_INCOMPLETE.
    No execution, no order/stop/strategy mutation. Includes shadow rule-backtest recovery
    potential (evidence only)."""
    rows = _db_query("SELECT * FROM trade_profit_capture_analysis ORDER BY money_left_usd DESC NULLS LAST, id") or []
    trades = [{k: _json_clean(v) for k, v in r.items()} for r in rows]

    winners = [t for t in trades if t.get("winner")]
    measurable_win = [t for t in winners if t.get("measurable")]
    gaveback = [t for t in measurable_win if (t.get("money_left_usd") or 0) > 0]
    missed = [t for t in trades if t.get("protection_missed")]
    adv_existed = [t for t in winners if t.get("advisory_existed")]
    acted = [t for t in winners if t.get("operator_acted")]
    no_adv = [t for t in trades if t.get("failure_class") == "NO_ADVISORY_GENERATED"]

    def _breakdown(key):
        out = {}
        for t in trades:
            k = t.get(key) or "unknown"
            out[k] = out.get(k, 0) + 1
        return out

    def _money_breakdown(key):
        out = {}
        for t in gaveback:
            k = t.get(key) or "unknown"
            out[k] = round(out.get(k, 0) + (t.get("money_left_usd") or 0), 2)
        return out

    # rule-backtest potential recovery (latest run by recency, best net rule) — EVIDENCE ONLY.
    # Recovery is an UPPER BOUND (single-peak MFE; premature-exit cost unknown). Confidence and
    # graft verdict key off RELIABLE sample size, not raw n. See Phase 206b hardening.
    # Prefer the best rule that actually has reliable evidence (a real path-measured result), so the
    # UI surfaces the honest finding rather than a vacuous zero-sample rule. Falls back to any rule.
    bt = _db_query("""SELECT rule_name, avoided_giveback, premature_exit_cost, net_improvement,
                             recommendation_confidence, reliable_sample_size, raw_sample_size,
                             estimate_quality, premature_exit_cost_known, premature_exit_cost_warning,
                             graft_verdict
                      FROM profit_protection_rule_backtests
                      WHERE run_id = (SELECT run_id FROM profit_protection_rule_backtests
                                      ORDER BY created_at DESC LIMIT 1)
                      ORDER BY (reliable_sample_size > 0) DESC, net_improvement DESC NULLS LAST
                      LIMIT 1""", fetch="one")
    best_rule = {k: _json_clean(v) for k, v in bt.items()} if bt else None

    summary = {
        "winners_measured": len(measurable_win),
        "winners_with_giveback": len(gaveback),
        "money_left_on_table_usd": round(sum(t.get("money_left_usd") or 0 for t in gaveback), 2),
        "protection_missed": len(missed),
        "advisory_existed": len(adv_existed),
        "operator_acted": len(acted),
        "no_advisory_generated": len(no_adv),
        "rule_backtest_potential_recovery_usd": (best_rule or {}).get("avoided_giveback"),
        "rule_backtest_premature_cost_usd": (best_rule or {}).get("premature_exit_cost"),
        "rule_backtest_net_usd": (best_rule or {}).get("net_improvement"),
        "rule_backtest_best_rule": (best_rule or {}).get("rule_name"),
        "rule_backtest_reliable_n": (best_rule or {}).get("reliable_sample_size"),
        "rule_backtest_raw_n": (best_rule or {}).get("raw_sample_size"),
        "rule_backtest_estimate_quality": (best_rule or {}).get("estimate_quality"),
        "rule_backtest_premature_cost_known": (best_rule or {}).get("premature_exit_cost_known"),
        "rule_backtest_premature_warning": (best_rule or {}).get("premature_exit_cost_warning"),
        "rule_backtest_graft_verdict": (best_rule or {}).get("graft_verdict"),
        "total_closed": len(trades),
        "measurable_closed": len([t for t in trades if t.get("measurable")]),
    }
    breakdowns = {
        "by_source_system": _breakdown("source_system"),
        "by_strategy": _breakdown("strategy_id"),
        "by_failure_class": _breakdown("failure_class"),
        "by_account": _breakdown("execution_account"),
        "by_advisory_action": _breakdown("advisory_action"),
        "by_operator_decision": _breakdown("operator_decision"),
        "money_left_by_source_system": _money_breakdown("source_system"),
        "money_left_by_strategy": _money_breakdown("strategy_id"),
    }
    # per-row warnings (honest categories)
    for t in trades:
        w = []
        fc = t.get("failure_class")
        if fc == "NO_ADVISORY_GENERATED":
            w.append("Protection missed — protectable profit but no advisory generated")
        if fc == "ADVISORY_IGNORED":
            w.append("Advisory ignored — advisory existed but no operator action")
        if fc == "ADVISORY_TOO_LATE":
            w.append("Advisory late — came after most give-back occurred")
        if fc == "DATA_INCOMPLETE":
            w.append("Data incomplete — MFE/MAE or bars missing")
        t["warnings"] = w

    return {
        "summary": summary, "breakdowns": breakdowns, "trades": trades,
        "labels": {"mode": "Advisory only", "execution": "No broker/order changes",
                   "shadow": "Shadow recommendations do not modify GO/WAIT or strategy.",
                   "estimate": "Premature-exit cost is path-measured from real intrabar bars where available "
                               "(estimate_quality=path_measured); single-peak upper bound otherwise.",
                   "graft": "Best rule is shadow / insufficient evidence — DO_NOT_GRAFT."},
        "note": "Canonical all-trades profit-capture. Give-back scored only on bar-based MFE; "
                "others flagged DATA_INCOMPLETE (honest unknown). Read-only, advisory only."}


def _atm_adjustment_proposals_list():
    """Phase 192E — paper protection adjustment proposals (read-only). Frontend-neutral
    (Command Center v2 + v3). Latest PROPOSED candidates grouped by trade."""
    # ROOT-CAUSE FILTER: only surface proposals whose underlying trade is still OPEN. The proposals
    # table accumulates PROPOSED rows that outlive the position; without this JOIN, any closed/sold
    # position (e.g. MRVL/ANY/CMCSA/SNOW) with a <1-day-old proposal still appears. Joining
    # paper_trades.status='open' excludes EVERY closed position generically — not specific tickers.
    rows = _db_query("""
        SELECT p.id, p.trade_id, p.symbol, p.action, p.current_stop, p.proposed_stop,
               p.current_take_profit, p.proposed_take_profit, p.current_risk, p.proposed_risk,
               p.profit_locked_before, p.profit_locked_after, p.giveback_before, p.giveback_after,
               p.downside_protection_improvement, p.upside_limitation, p.tradeai_reason, p.hermes_reason,
               p.evidence_refs, p.quote_price, p.alpaca_supported, p.expected_api, p.status, p.created_at
        FROM paper_protection_adjustment_proposals p
        JOIN paper_trades t ON t.id = p.trade_id
        WHERE p.status = 'PROPOSED' AND p.created_at > now() - interval '1 day'
          AND t.status = 'open'
        ORDER BY p.symbol, p.id""") or []
    by_trade = {}
    for r in rows:
        key = r["trade_id"]
        by_trade.setdefault(key, {"trade_id": key, "symbol": r["symbol"], "candidates": []})
        by_trade[key]["candidates"].append({k: _json_clean(v) for k, v in r.items()})
    return {"trades": list(by_trade.values()), "proposal_count": len(rows),
            "paper_only": True, "requires_operator_approval": True,
            "no_live_execution": True,
            "note": "Advisory proposals. Execution only via guarded approve endpoint on explicit operator action."}


def _atm_adjustment_proposal_detail(pid):
    r = _db_query("""SELECT * FROM paper_protection_adjustment_proposals WHERE id = %s""",
                  (pid,), fetch="one")
    if not r:
        return None
    out = {k: _json_clean(v) for k, v in r.items()}
    out["paper_only"] = True
    out["operator_confirmation_required"] = True
    out["blocked_reasons"] = []
    return out


# ══ Hermes global-profile management (Command Center → System → Hermes) ════════════════════════
# Read/edit ONLY approved Hermes profile identity (SOUL.md) + read-only status. Never enables the
# retired sidecar gateway, never touches broker/trading, never reads .env/secrets.
HERMES_HOME = Path.home() / ".hermes"
HERMES_VENV = Path.home() / ".local" / "share" / "hermes-agent-venv"
HERMES_CLI = Path.home() / ".local" / "bin" / "hermes"
HERMES_PROFILES = {
    "default":    {"sub": "",                  "label": "Global Hermes Identity",            "purpose": "general"},
    "tradeai":    {"sub": "profiles/tradeai",    "label": "Trade AI Advisory Identity",        "purpose": "Trade AI advisory"},
    "tradeai12b": {"sub": "profiles/tradeai12b", "label": "Experimental 12B Trade AI Identity", "purpose": "12B advisory"},
    "dev":        {"sub": "profiles/dev",        "label": "Development / Codex Identity",       "purpose": "Codex/dev"},
    "serverops":  {"sub": "profiles/serverops",  "label": "ServerOps Identity",                "purpose": "server ops"},
}
HERMES_UNSAFE_PHRASES = ["execute trades", "place orders", "modify stops", "approve proposals",
                         "read raw secrets", "broker credentials", "use tools to execute actions",
                         "autonomous trading"]
HERMES_REQUIRED_TRADEAI = ["You do not execute trades.", "You do not place orders.",
                           "You do not modify stops.", "You do not create, approve, or promote trade proposals.",
                           "You do not read raw secrets"]


def _hermes_profile_dir(profile):
    sub = HERMES_PROFILES[profile]["sub"]
    return (HERMES_HOME / sub) if sub else HERMES_HOME


def _hermes_soul_path(profile):
    return _hermes_profile_dir(profile) / "SOUL.md"


def _hermes_soul_hash(profile):
    p = _hermes_soul_path(profile)
    if not p.exists():
        return None
    import hashlib as _hl
    return _hl.sha256(p.read_text(errors="ignore").encode()).hexdigest()[:16]


def _hermes_profile_model(profile):
    cfg = _hermes_profile_dir(profile) / "config.yaml"
    try:
        import yaml as _y
        d = _y.safe_load(cfg.read_text()) or {}
        return ((d.get("model") or {}).get("default")) or None
    except Exception:
        return None


def _hermes_run(cmd, timeout=8, env=None):
    """Run a command, return stdout (stripped) regardless of exit code; None on error/timeout."""
    import subprocess as _sp
    try:
        e = None
        if env:
            e = dict(os.environ); e.update(env)
        r = _sp.run(cmd, capture_output=True, text=True, timeout=timeout, env=e)
        return (r.stdout or "").strip() or (r.stderr or "").strip() or None
    except Exception:
        return None


def _hermes_profile_tools(profile):
    """Authoritative tool state from `hermes -p <profile> tools list` (line-anchored count of enabled rows).
    Uses the full CLI path + -p (the ~/.local/bin/<name> wrappers do `exec hermes ...` which needs PATH).
    Reported even when the model is unset, so disabled high-risk tools are visible (profile state wins)."""
    out = _hermes_run([str(HERMES_CLI), "-p", profile, "tools", "list"], timeout=12)
    if not out:
        return "unknown"
    import re as _re_t
    # Strict toolset-row format only: "  ✓ enabled  <toolset_id> ...". Names the enabled toolsets so the
    # operator sees exactly what's on (some, e.g. x_search, auto-enable when credentials exist in the env).
    enabled_ids, disabled = [], 0
    for ln in out.splitlines():
        m = _re_t.match(r"\s*✓ enabled\s\s+([a-z][a-z_]*)", ln)
        if m:
            enabled_ids.append(m.group(1))
        elif _re_t.match(r"\s*✗ disabled\s\s+[a-z]", ln):
            disabled += 1
    if not enabled_ids:
        return "disabled" if disabled else "unknown"
    return f"{len(enabled_ids)} enabled: {', '.join(enabled_ids)}"


def _hermes_svc(state):
    # systemctl --user needs the user runtime bus; the server may lack it, so inject XDG_RUNTIME_DIR.
    out = _hermes_run(["systemctl", "--user", state, "hermes-gateway.service"], timeout=6,
                      env={"XDG_RUNTIME_DIR": f"/run/user/{os.getuid()}"})
    return (out.splitlines()[0].strip() if out else "unknown")


def _hermes_profiles_status(query=None):
    """GET /api/v2/hermes/profiles-status — read-only global Hermes + per-profile status."""
    _vraw = _hermes_run([str(HERMES_CLI), "--version"], timeout=10)
    ver = (_vraw.splitlines()[0].strip() if _vraw else None)
    retired = sorted(str(p.name) for p in PROJECT_ROOT.joinpath("hermes_sidecar").glob(".hermes.RETIRED_*")) \
        if PROJECT_ROOT.joinpath("hermes_sidecar").exists() else []
    retired += sorted(str(p.name) for p in PROJECT_ROOT.joinpath("hermes_sidecar").glob("install.RETIRED_*")) \
        if PROJECT_ROOT.joinpath("hermes_sidecar").exists() else []
    rows = []
    for name, meta in HERMES_PROFILES.items():
        model = _hermes_profile_model(name)
        configured = model is not None
        rows.append({
            "profile": name, "label": meta["label"], "purpose": meta["purpose"],
            "model": model or "unset",
            "tools": _hermes_profile_tools(name),
            "status": ("active" if name in ("default", "tradeai") else
                       "experimental" if name == "tradeai12b" else "unconfigured") if configured else "unconfigured",
            "soul_exists": _hermes_soul_path(name).exists(),
            "soul_bytes": (_hermes_soul_path(name).stat().st_size if _hermes_soul_path(name).exists() else 0),
            "soul_hash": _hermes_soul_hash(name),
            "soul_mtime": (int(_hermes_soul_path(name).stat().st_mtime) if _hermes_soul_path(name).exists() else None),
        })
    return {
        "version": ver, "cli_path": "~/.local/bin/hermes", "venv_path": "~/.local/share/hermes-agent-venv",
        "home_path": "~/.hermes",
        "sidecar_retired_dirs": retired,
        "sidecar_status": "rename-retired (rollback/audit only)",
        "gateway_service_active": _hermes_svc("is-active"),
        "gateway_service_enabled": _hermes_svc("is-enabled"),
        "gateway_note": "retired sidecar gateway must remain disabled — do not enable",
        "tools_note": "Tool state reflects the SERVER runtime env. Safety-critical toolsets "
                      "(terminal/file/code_execution/browser/computer_use) are disabled on tradeai/tradeai12b. "
                      "Some read-only toolsets (e.g. x_search) auto-enable when credentials exist in the env.",
        "profiles": rows,
    }


def _hermes_soul_read(query=None):
    """GET /api/v2/hermes/soul?profile=NAME — read a profile SOUL.md (identity text only)."""
    profile = (query or {}).get("profile")
    if isinstance(profile, list):
        profile = profile[0] if profile else None
    if profile not in HERMES_PROFILES:
        return {"ok": False, "error": "unknown profile"}
    sp = _hermes_soul_path(profile)
    return {"ok": True, "profile": profile, "label": HERMES_PROFILES[profile]["label"],
            "path": str(sp).replace(str(Path.home()), "~"), "exists": sp.exists(),
            "content": (sp.read_text() if sp.exists() else "")}


def _hermes_validate_soul(profile, text):
    """Fail-closed safety check for SOUL edits. Returns list of errors (empty = ok)."""
    errs = []
    try:
        import re as _re_v
        low = (text or "").lower()
        negations = ("do not", "does not", "never", "cannot", "won't", "will not", "n't", "no ")
        for ph in HERMES_UNSAFE_PHRASES:
            for m in _re_v.finditer(_re_v.escape(ph), low):
                j = m.start()
                # sentence-scoped: from the last sentence/clause boundary up to the phrase
                seg_start = max(low.rfind(".", 0, j), low.rfind("\n", 0, j),
                                low.rfind(";", 0, j), low.rfind(":", 0, j))
                seg = low[seg_start + 1:j]
                if not any(neg in seg for neg in negations):
                    errs.append(f"unsafe phrase without negation: '{ph}'")
                    break
        if profile in ("tradeai", "tradeai12b"):
            for req in HERMES_REQUIRED_TRADEAI:
                if req not in (text or ""):
                    errs.append(f"missing required boundary: '{req}'")
    except Exception as e:
        errs.append(f"validation error (fail-closed): {e}")
    return errs


def _hermes_legacy_agents(query=None):
    """GET /api/v2/hermes/legacy-agents — READ-ONLY inventory of retired/legacy Hermes agents and
    artifacts (for the Command Center audit view). No enable/run/edit actions; secrets redacted;
    runtime-state contents not exposed; the retired gateway stays disabled. Backed by
    scripts/hermes_legacy_agent_inventory.py (retired dirs are immutable, so the cached JSON is used;
    regenerated only if absent)."""
    inv_path = PROJECT_ROOT / "data" / "hermes" / "legacy_agent_inventory_latest.json"
    report = None
    try:
        if not inv_path.exists():
            import hermes_legacy_agent_inventory as _inv
            report = _inv.main()
        else:
            report = json.loads(inv_path.read_text())
    except Exception as e:
        return {"ok": False, "error": str(e)[:200], "items": [], "counts": {}, "read_only": True}
    gw_active = _hermes_svc("is-active")
    gw_enabled = _hermes_svc("is-enabled")
    return {
        "ok": True,
        "read_only": True,
        "scanned_at": report.get("scanned_at"),
        "retired_dirs": report.get("retired_dirs", []),
        "counts": report.get("counts", {}),
        "total": report.get("total", 0),
        "items": [{k: _json_clean(v) for k, v in it.items()} for it in report.get("items", [])],
        "gateway_service_active": gw_active,
        "gateway_service_enabled": gw_enabled,
        "actions_available": [],  # no enable/run/edit for retired items — audit only
        "warning": report.get("warning") or
                   "Retired sidecar artifacts are shown for audit only. Do not enable the retired "
                   "gateway or execute retired wrappers.",
    }


HERMES_LOCAL_ONLY = ("default", "tradeai", "tradeai12b")  # must stay on local Ollama
HERMES_PROVIDERS = ["custom", "openai-codex", "xai-oauth", "nous"]  # custom = local Ollama


def _hermes_identity_meta_path(profile):
    return _hermes_profile_dir(profile) / "identity_meta.json"


def _hermes_identity_meta(profile):
    p = _hermes_identity_meta_path(profile)
    try:
        import json as _j
        return _j.loads(p.read_text()) if p.exists() else {}
    except Exception:
        return {}


def _hermes_available_models():
    out = _hermes_run(["ollama", "list"], timeout=8) or ""
    models = []
    for ln in out.splitlines()[1:]:
        nm = ln.split()[0] if ln.split() else ""
        if nm and "embed" not in nm.lower():
            models.append(nm)
    return models


# Curated model menus per provider (free/OAuth lanes). Exact cloud IDs resolve via `hermes model` after
# login; these are selectable defaults. custom (local Ollama) is populated live from `ollama list`.
HERMES_PROVIDER_MODELS = {
    "openai-codex": ["gpt-5-codex", "gpt-5", "gpt-5-mini", "o4-mini"],   # FREE ChatGPT-subscription OAuth
    "xai-oauth": ["grok-4", "grok-3", "grok-3-mini"],                    # FREE xAI OAuth proxy
    "nous": ["Hermes-4-405B", "Hermes-4-70B", "DeepHermes-3-Mistral-24B"],  # Nous Portal OAuth
}


def _hermes_identity_detail(query=None):
    """GET /api/v2/hermes/identity?profile=NAME — editable identity (model/provider/label/purpose/desc) +
    available models/providers + read-only context. Use ?profile=__all__ for the full identity list."""
    profile = (query or {}).get("profile")
    if isinstance(profile, list):
        profile = profile[0] if profile else None
    avail_models = _hermes_available_models()

    def one(name):
        cfg = _hermes_profile_dir(name) / "config.yaml"
        model = provider = base_url = None
        try:
            import yaml as _y
            m = (_y.safe_load(cfg.read_text()) or {}).get("model") or {}
            model, provider, base_url = m.get("default"), m.get("provider"), m.get("base_url")
        except Exception:
            pass
        meta = _hermes_identity_meta(name)
        local = name in HERMES_LOCAL_ONLY
        return {"profile": name,
                "label": meta.get("label") or HERMES_PROFILES[name]["label"],
                "purpose": meta.get("purpose") or HERMES_PROFILES[name]["purpose"],
                "description": meta.get("description", ""),
                "config_path": str(cfg).replace(str(Path.home()), "~"),
                "model": model or "", "provider": provider or "", "base_url": base_url or "",
                "tools": _hermes_profile_tools(name), "soul_hash": _hermes_soul_hash(name),
                "local_only": local,
                "available_models": avail_models,
                "available_providers": (["custom"] if local else HERMES_PROVIDERS),
                # provider -> selectable models (custom=live ollama; cloud/OAuth=curated free-lane menus).
                # local-only profiles only get custom (cloud is guard-blocked there).
                "model_options": ({"custom": avail_models} if local else
                                  {"custom": avail_models, **HERMES_PROVIDER_MODELS}),
                "policy_note": ("This profile must stay on local Ollama (provider=custom). Cloud providers, "
                                "gemma3:12b (unconstrained), and qwen3:14b are blocked." if local
                                else "dev/serverops may use free OAuth lanes: openai-codex (ChatGPT), "
                                     "xai-oauth (Grok), nous. Complete the OAuth login before use.")}

    if profile == "__all__":
        return {"ok": True, "identities": [one(n) for n in HERMES_PROFILES]}
    if profile not in HERMES_PROFILES:
        return {"ok": False, "error": "unknown profile"}
    d = one(profile)
    d["ok"] = True
    return d


def _hermes_validate_identity(profile, model, provider):
    """Hard guards for identity edits. Returns list of errors (empty = ok)."""
    errs = []
    m = (model or "").strip().lower()
    p = (provider or "").strip().lower()
    if m:
        if "qwen3:14b" in m or m == "qwen3":
            errs.append("qwen3:14b must not be reintroduced as a Hermes model")
        if m == "gemma3:12b" and profile in ("default", "tradeai"):
            errs.append("gemma3:12b (unconstrained) is not approved for default/tradeai — use gemma3:12b-ctx4k on tradeai12b")
    if p and profile in HERMES_LOCAL_ONLY and p not in ("custom",):
        errs.append(f"{profile} must stay on local Ollama (provider=custom); cloud providers are blocked here")
    return errs


# ===== OpenClaw ecosystem (read-only inventory + editable agent SOUL) =====
OPENCLAW_HOME = Path.home() / ".openclaw"


def _openclaw_load_config():
    import json as _j
    p = OPENCLAW_HOME / "openclaw.json"
    try:
        return _j.load(open(p)) if p.exists() else {}
    except Exception:
        return {}


def _openclaw_agent_soul_path(agent_id):
    return OPENCLAW_HOME / "agents" / str(agent_id) / "agent" / "SOUL.md"


def _openclaw_svc(action):
    import subprocess as _sp, os as _os
    e = dict(_os.environ); e["XDG_RUNTIME_DIR"] = f"/run/user/{_os.getuid()}"
    try:
        return _sp.run(["systemctl", "--user", action, "openclaw-gateway.service"],
                       capture_output=True, text=True, timeout=6, env=e).stdout.strip() or "unknown"
    except Exception:
        return "unknown"


def _openclaw_agent_ids():
    return [a.get("id") for a in ((_openclaw_load_config().get("agents") or {}).get("list") or []) if a.get("id")]


def _openclaw_status(query=None):
    """GET /api/v2/openclaw/status — read-only inventory of the OpenClaw ecosystem
    (agents + skills + channels + gateway). No control, no secrets."""
    cfg = _openclaw_load_config()
    agdef = cfg.get("agents") or {}
    defaults = agdef.get("defaults") or {}
    mp = (defaults.get("model") or {})
    model_primary = mp.get("primary")
    rows = []
    registered_ids = set()
    for a in (agdef.get("list") or []):
        aid = a.get("id")
        registered_ids.add(aid)
        ident = a.get("identity") or {}
        soul = _openclaw_agent_soul_path(aid)
        idf = OPENCLAW_HOME / "agents" / str(aid) / "agent" / "IDENTITY.md"
        am = a.get("model")
        am = (am.get("primary") if isinstance(am, dict) else am) or model_primary  # normalize to a string
        rows.append({"id": aid, "name": a.get("name") or aid,
                     "identity_name": ident.get("name"), "emoji": ident.get("emoji"),
                     "model": am,
                     "workspace": str(a.get("workspace") or "").replace(str(Path.home()), "~"),
                     "soul_exists": soul.exists(), "identity_md_exists": idf.exists(),
                     "skills": a.get("skills") or [], "registered": True})
    # unregistered agent dirs present on disk but not in openclaw.json (read-only, not editable)
    adir = OPENCLAW_HOME / "agents"
    if adir.exists():
        for d in sorted(p for p in adir.iterdir() if p.is_dir() and p.name not in registered_ids):
            soul = _openclaw_agent_soul_path(d.name)
            sk = sorted(s.stem for s in (d / "skills").glob("*.md")) if (d / "skills").is_dir() else []
            rows.append({"id": d.name, "name": d.name, "identity_name": None, "emoji": None,
                         "model": None,
                         "workspace": str(d).replace(str(Path.home()), "~"),
                         "soul_exists": soul.exists(), "identity_md_exists": False,
                         "skills": sk, "registered": False})
    skills = sorted([p.name for p in (OPENCLAW_HOME / "skills").glob("*") if p.is_dir()]) \
        if (OPENCLAW_HOME / "skills").exists() else []
    ch = cfg.get("channels") or {}
    channels = [{"name": k, "enabled": bool(v.get("enabled") if isinstance(v, dict) else v)}
                for k, v in (ch.items() if isinstance(ch, dict) else [])]
    return {"ok": True, "read_only": True,
            "version": (cfg.get("meta") or {}).get("version"),
            "home": str(OPENCLAW_HOME).replace(str(Path.home()), "~"),
            "gateway_active": _openclaw_svc("is-active"), "gateway_enabled": _openclaw_svc("is-enabled"),
            "model_primary": model_primary, "model_fallbacks": mp.get("fallbacks") or [],
            "models": list((defaults.get("models") or {}).keys()),
            "agents": rows, "skills_catalog": skills, "channels": channels,
            "warning": "Read-only inventory. OpenClaw gateway state is shown but not controlled here."}


def _agent_soul_validate(text):
    """Fail-closed safety check for agent SOUL edits (advisory personas). Returns errors list."""
    import re as _rv
    errs = []
    low = (text or "").lower()
    negations = ("do not", "does not", "never", "cannot", "won't", "will not", "n't", "no ", "without")
    unsafe = ("execute trade", "place order", "submit order", "bypass approval", "disable safety",
              "read .env", "read secrets", "enable live trading", "move stop", "without approval")
    for ph in unsafe:
        for m in _rv.finditer(_rv.escape(ph), low):
            j = m.start()
            seg_start = max(low.rfind(".", 0, j), low.rfind("\n", 0, j), low.rfind(";", 0, j), low.rfind(":", 0, j))
            if not any(neg in low[seg_start + 1:j] for neg in negations):
                errs.append(f"unsafe phrase without negation: '{ph}'"); break
    return errs


def _openclaw_agent_soul(query=None):
    """GET /api/v2/openclaw/agent-soul?agent=NAME — read an OpenClaw agent's SOUL.md (+IDENTITY.md)."""
    agent = (query or {}).get("agent")
    if isinstance(agent, list):
        agent = agent[0] if agent else None
    if agent not in _openclaw_agent_ids():
        return {"ok": False, "error": "unknown agent"}
    sp = _openclaw_agent_soul_path(agent)
    idf = OPENCLAW_HOME / "agents" / str(agent) / "agent" / "IDENTITY.md"
    return {"ok": True, "agent": agent, "path": str(sp).replace(str(Path.home()), "~"),
            "exists": sp.exists(), "content": (sp.read_text() if sp.exists() else ""),
            "identity_md": (idf.read_text() if idf.exists() else None)}


# TradeAI agent fleet (advisory personas share OpenClaw SOULs; algorithmic agents are config-only).
TRADEAI_ROLES = {
    "alex": "CIO / escalation arbiter", "cio_engine": "CIO decision engine",
    "maria": "Research analyst / catalyst", "maria_research": "Deep RAG research",
    "steph": "Income guardian / allocation", "risk_agent": "Risk / stops / portfolio heat",
    "tax_agent": "Tax / Roth / harvest", "aegis": "Surveillance / briefs",
    "iris": "Librarian / RAG coverage", "social_scalp": "Social mention scanner",
    "scalp_critic": "Scalp critic / validation",
}
# advisory personas that have an editable OpenClaw SOUL; map TradeAI name -> OpenClaw agent id
TRADEAI_SOUL_AGENT = {"alex": "alex", "aegis": "aegis", "steph": "steph", "maria": "maria",
                      "maria_research": "maria", "iris": "iris"}


def _tradeai_fleet(query=None):
    """GET /api/v2/tradeai/fleet — read-only TradeAI agent fleet (roles/model/calibration). Advisory
    personas expose an editable SOUL (shared with OpenClaw); algorithmic agents are read-only (their
    operational config in config/agents.yaml is safety-locked and never edited here)."""
    cal = {}
    try:
        cs = _agent_calibration()  # accuracy/trust per agent if available
        for a in (cs.get("agents") or cs.get("data", {}).get("agents") or []) if isinstance(cs, dict) else []:
            if isinstance(a, dict) and a.get("agent_name"):
                cal[a["agent_name"]] = a
    except Exception:
        pass
    oc_ids = set(_openclaw_agent_ids())
    rows = []
    for name, role in TRADEAI_ROLES.items():
        soul_agent = TRADEAI_SOUL_AGENT.get(name)
        editable = bool(soul_agent and soul_agent in oc_ids and _openclaw_agent_soul_path(soul_agent).exists())
        rows.append({"agent": name, "role": role, "runtime_model": "gemma3:12b",
                     "type": "advisory" if soul_agent else "algorithmic",
                     "soul_agent": soul_agent if editable else None, "soul_editable": editable,
                     "calibration": (cal.get(name) or {}).get("status") or (cal.get(name) or {}).get("recommendation")})
    return {"ok": True, "read_only_fleet": True, "runtime_model": "gemma3:12b",
            "agents": rows,
            "note": "Advisory personas (alex/aegis/steph/maria/iris) have editable SOULs (shared with "
                    "OpenClaw). Algorithmic agents (risk/tax/scalp/social) are config-driven; their "
                    "operational config (config/agents.yaml: thresholds/routing) is NOT editable here."}


