def _analyst_detail(query=None):
    """GET /api/v2/analyst-detail[?symbol=X][?map=1] — per-symbol analyst breakdown for the bulleted card
    view: rating distribution (strong_buy/buy/hold/sell, finnhub) + target range (mean/median/high/low,
    Yahoo) + counts + dates/sources. NOTE: sources aggregate — no individual firm names are available.
    Read-only/advisory."""
    q = query or {}
    sym = q.get("symbol")
    sym = (sym[0] if isinstance(sym, list) else sym or "").upper().strip()
    want_map = bool(q.get("map"))
    # latest target snapshot per symbol (Yahoo)
    tgt_rows = _db_query("""SELECT DISTINCT ON (upper(symbol)) upper(symbol) s, target_mean_price, target_median_price,
                              target_high_price, target_low_price, number_of_analyst_opinions, recommendation_key,
                              current_price, snapshot_date
                            FROM yahoo_analyst_targets_history
                            {} ORDER BY upper(symbol), snapshot_date DESC""".format(
                            "WHERE upper(symbol)=%s" if sym else ""), ((sym,) if sym else None)) or []
    # latest rating distribution per symbol (finnhub)
    dist_rows = _db_query("""SELECT DISTINCT ON (upper(symbol)) upper(symbol) s, payload
                             FROM analyst_data_history
                             {} ORDER BY upper(symbol), as_of DESC""".format(
                             "WHERE upper(symbol)=%s" if sym else ""), ((sym,) if sym else None)) or []
    dist = {}
    for r in dist_rows:
        p = r["payload"] if isinstance(r["payload"], dict) else {}
        dist[r["s"]] = p
    def _f(v):
        try:
            return round(float(v), 2)
        except Exception:
            return None
    out = {}
    for r in tgt_rows:
        s = r["s"]
        mean = _f(r["target_mean_price"]); cur = _f(r["current_price"])
        d = dist.get(s, {})
        out[s] = {
            "rec": r["recommendation_key"], "n": r["number_of_analyst_opinions"],
            "target_mean": mean, "target_median": _f(r["target_median_price"]),
            "target_high": _f(r["target_high_price"]), "target_low": _f(r["target_low_price"]),
            "current": cur, "upside": (round((mean - cur) / cur * 100, 1) if (mean and cur) else None),
            "as_of": str(r["snapshot_date"]) if r["snapshot_date"] else None,
            "dist": {k: d.get(k) for k in ("strong_buy", "buy", "hold", "sell", "strong_sell") if d.get(k) is not None},
            "dist_period": d.get("recommendation_period"), "dist_source": d.get("provider"),
        }
    if want_map or not sym:
        return {"ok": True, "advisory_only": True, "count": len(out), "map": out}
    return {"ok": True, "advisory_only": True, "symbol": sym, "detail": out.get(sym)}


def _pro_analyst_pills(query=None):
    """GET /api/v2/pro-analyst/pills [?symbol=AAPL] — advisory professional-analyst layer: per-symbol Yahoo
    consensus + targets + upgrade/downgrade events + internal-vs-Street divergence + coverage by tier.
    Read-only; never affects GO/WAIT or scoring."""
    import json as _jp
    try:
        d = _jp.loads((PROJECT_ROOT / "data" / "runtime" / "pro_analyst_pills_latest.json").read_text())
    except Exception:
        return {"note": "run scripts/build_pro_analyst_read_model.py", "pills": []}
    q = query or {}
    if q.get("map"):
        # compact symbol→pill map for per-page pills (one fetch covers all rows, incl. no-coverage)
        m = {p["symbol"]: {"rec": p.get("recommendation_key"), "n": p.get("number_of_analyst_opinions"),
                           "target": p.get("target_mean_price"), "upside": p.get("upside_to_mean_target_pct"),
                           "street": p.get("street_direction"), "internal": p.get("internal_direction"),
                           "divergence": p.get("divergence"), "stale": p.get("stale"),
                           "has": p.get("has_professional_coverage"), "event": p.get("latest_event_type")}
             for p in d.get("pills", [])}
        return {"updated_at": d.get("updated_at"), "count": len(m), "map": m}
    sym = q.get("symbol")
    if isinstance(sym, list):
        sym = sym[0] if sym else None
    if sym:
        p = next((x for x in d.get("pills", []) if x["symbol"] == sym.upper()), None)
        return {"updated_at": d.get("updated_at"), "symbol": sym.upper(), "pill": p,
                "found": p is not None, "note": d.get("note")}
    coverage_health = {}
    try:
        h = _jp.loads((PROJECT_ROOT / "data" / "runtime" / "pro_analyst_coverage_history.json").read_text()).get("snapshots", [])
        if h:
            latest = h[-1]
            coverage_health = {"status": latest.get("status"), "coverage_pct": latest.get("coverage_pct"),
                               "with_consensus": latest.get("with_consensus"), "stale": latest.get("stale"),
                               "notes": latest.get("notes", []),
                               "divergence_counts": latest.get("divergence_counts"), "comparable": latest.get("comparable"),
                               "divergent_symbols": latest.get("divergent_symbols"), "newly_divergent": latest.get("newly_divergent"),
                               "trend": [{"date": s["date"], "coverage_pct": s["coverage_pct"], "with_consensus": s["with_consensus"],
                                          "divergent": s.get("divergent"), "comparable": s.get("comparable")} for s in h[-14:]]}
    except Exception:
        pass
    return {"updated_at": d.get("updated_at"), "symbol_count": d.get("symbol_count"),
            "coverage_by_tier": d.get("coverage_by_tier"), "note": d.get("note"),
            "with_consensus": sum(1 for p in d.get("pills", []) if p.get("has_professional_coverage")),
            "coverage_health": coverage_health,
            "divergent": [p["symbol"] for p in d.get("pills", []) if p.get("divergence") == "divergent"],
            "pills": [p for p in d.get("pills", []) if p.get("has_professional_coverage")][:50]}


def _hermes_source_maturity(query=None):
    """GET /api/v2/hermes/source-maturity — read-only source maturity board (Gate 1-5): per-source tier,
    maturity_score, go-rate, outcome, + the operator vetting-action queue. Reads runtime JSONs."""
    import json as _jm
    try:
        mat = _jm.loads((PROJECT_ROOT / "data" / "runtime" / "source_maturity_latest.json").read_text())
    except Exception:
        return {"note": "run scripts/source_maturity.py", "sources": []}
    actions = []
    try:
        actions = _jm.loads((PROJECT_ROOT / "data" / "runtime" / "source_vetting_actions_latest.json").read_text()).get("actions", [])
    except Exception:
        pass
    srcs = mat.get("sources", [])
    # attribution-health trend (news<->trade overlap growing → loops strengthening)
    attribution = {}
    try:
        h = _jm.loads((PROJECT_ROOT / "data" / "runtime" / "source_attribution_history.json").read_text()).get("snapshots", [])
        if h:
            latest = h[-1]
            recent_transitions = []
            for s in reversed(h):
                for t in (s.get("tier_transitions") or []):
                    recent_transitions.append({"date": s["date"], **t})
                if len(recent_transitions) >= 10:
                    break
            attribution = {"status": latest.get("status"), "overlap_pct": latest.get("overlap_pct"),
                           "traded_with_news_7d": latest.get("traded_with_news_7d"), "traded_30d": latest.get("traded_30d"),
                           "total_attributions": latest.get("total_attributions"),
                           "sources_with_trades": latest.get("sources_with_trades"),
                           "healthy_overlap_streak_days": latest.get("healthy_overlap_streak_days"),
                           "notes": latest.get("notes", []),
                           "trend": [{"date": s["date"], "overlap_pct": s["overlap_pct"], "attributions": s["total_attributions"]} for s in h[-14:]],
                           "tier_trend": [{"date": s["date"], **(s.get("tier_counts") or {})} for s in h[-14:] if s.get("tier_counts")],
                           "recent_tier_transitions": recent_transitions[:10]}
    except Exception:
        pass
    return {"updated_at": mat.get("updated_at"), "tier_counts": mat.get("tier_counts"),
            "source_count": mat.get("source_count"), "attribution_health": attribution,
            "note": "Source maturity = precision(go-rate) + outcome(trade win-rate) + yield + health + credibility. "
                    "Trade-outcome is sparse until news/trade universe overlap grows; go-rate carries it for now. "
                    "Advisory; 'core' activation is operator-gated.",
            "operator_actions": actions,
            "top_sources": srcs[:25], "demoted": [s for s in srcs if s["tier"] == "demoted"][:15]}


def _hermes_catalyst_calibration(query=None):
    """GET /api/v2/hermes/catalyst-calibration — read-only catalyst-calibration multipliers + sharpening trend."""
    import json as _jc
    try:
        cal = _jc.loads((PROJECT_ROOT / "data" / "runtime" / "catalyst_calibration.json").read_text())
    except Exception:
        return {"note": "run scripts/catalyst_calibration.py", "by_type": {}}
    bt = cal.get("by_type", {})
    types = sorted([{"catalyst_type": t, **v} for t, v in bt.items()], key=lambda x: -x.get("samples", 0))
    trend, transitions = [], []
    try:
        h = _jc.loads((PROJECT_ROOT / "data" / "runtime" / "catalyst_calibration_history.json").read_text()).get("snapshots", [])
        trend = [{"date": s["date"], "credible_samples": s.get("credible_samples"), "trusted_type_count": s.get("trusted_type_count")} for s in h[-14:]]
        for s in reversed(h):
            for x in (s.get("newly_trusted") or []):
                transitions.append({"date": s["date"], "event": "newly_trusted", **x})
            for x in (s.get("multiplier_shifts") or []):
                transitions.append({"date": s["date"], "event": "shift", **x})
            if len(transitions) >= 10:
                break
    except Exception:
        pass
    return {"updated_at": cal.get("updated_at"), "total_settled": cal.get("total_settled_catalysts"),
            "credible_samples": cal.get("credible_samples"), "dropped_as_data_error": cal.get("dropped_as_data_error"),
            "min_samples": cal.get("min_samples"), "settle_days": cal.get("settle_days"),
            "trusted_type_count": sum(1 for v in bt.values() if v.get("trusted")),
            "note": "weight_multiplier (0.5-1.5) scales catalyst impact by realized 2-day move; trusted = samples>=min. "
                    "Sharpens as classifier-labeled catalysts settle on news-covered symbols.",
            "by_type": types[:20], "trend": trend, "recent_transitions": transitions[:10]}


def _watch_directives(query=None):
    """GET /api/v2/watch-directives — operator watch directives + recent hits + Hermes staging (read-only)."""
    directives = _db_query("""SELECT id, kind, label, status, priority, trade_ai_enabled, hermes_enabled,
                              last_serviced_at, created_at, spec, created_by, rationale
                              FROM watch_directives ORDER BY created_at DESC""") or []
    hits = _db_query("""SELECT h.directive_id, d.label, h.symbol, h.surfaced_by, h.divergence, h.promotion_status,
                        h.surfaced_at FROM watch_directive_hits h JOIN watch_directives d ON d.id=h.directive_id
                        ORDER BY h.surfaced_at DESC LIMIT 40""") or []
    # Per-directive surfaced symbols (fix 2026-06-19): trend/sector directives link items via hits, NOT
    # by setting directive_id on the item — so the Watchlist directive filter must match on these symbols.
    _hs = _db_query("""SELECT directive_id, array_agg(DISTINCT upper(symbol)) syms,
                              count(*) hit_count,
                              count(*) FILTER (WHERE promotion_status='STAGED_FOR_REVIEW') staged_count
                       FROM watch_directive_hits GROUP BY directive_id""") or []
    _hit_sym_map = {r["directive_id"]: (r["syms"] or []) for r in _hs}
    # Per-directive TOTAL counts (fix 2026-06-19): the chip count must come from here, NOT from the global
    # recent_hits feed below — that feed is LIMIT 40 (most-recent activity), so older/ticker-tag hits fall
    # out of the window and the chip wrongly shows "0 hits" for a directive that did surface symbols.
    _hit_cnt = {r["directive_id"]: (r["hit_count"], r["staged_count"]) for r in _hs}
    staging = _db_query("SELECT count(*) c, count(*) FILTER (WHERE NOT drained) undrained FROM hermes_directive_hits_staging", fetch="one") or {}
    promoted = _db_query("SELECT count(*) c FROM watchlist_items WHERE source='operator_directive'", fetch="one") or {}
    health = {}
    try:
        import json as _jw
        _h = _jw.loads((PROJECT_ROOT / "data" / "runtime" / "watch_directives_history.json").read_text()).get("snapshots", [])
        if _h:
            _l = _h[-1]
            health = {"status": _l.get("status"), "hits_24h": _l.get("hits_24h"),
                      "by_status_24h": _l.get("by_status_24h"), "by_surfaced_24h": _l.get("by_surfaced_24h"),
                      "promoted_total": _l.get("promoted_total"), "staging_undrained": _l.get("staging_undrained"),
                      "stale_directives": _l.get("stale_directives"), "notes": _l.get("notes", []),
                      "trend": [{"date": s["date"], "hits_7d": s.get("hits_7d"), "promoted_total": s.get("promoted_total")} for s in _h[-14:]]}
    except Exception:
        pass
    critique_summary = {}
    critique_snapshot_at = None
    try:
        import sys as _sysc2
        _sysc2.path.insert(0, str(PROJECT_ROOT / "scripts"))
        from research_critique_pipeline import load_critique_snapshot, extract_critique_fields
        _critique_snap = load_critique_snapshot()
        critique_summary = _critique_snap.get("summary") or {}
        critique_snapshot_at = _critique_snap.get("updated_at")
        _extract = extract_critique_fields
    except Exception:
        _extract = lambda _s: {}

    return {"note": "Operator-owned watch directives honored by Trade AI + Hermes (firewall: Hermes proposes via "
                    "staging only). Advisory; no GO/WAIT or scoring change.",
            "critique_summary": {k: _json_clean(v) for k, v in critique_summary.items()},
            "critique_snapshot_at": critique_snapshot_at,
            "directive_count": len(directives),
            # surface the spec context (gap_type/sleeve/symbol) + created_by so the Watchpool can label
            # rotate-gap directives instead of showing them as generic ticker directives (operator 2026-06-19)
            "directives": [{**{k: _json_clean(v) for k, v in r.items()},
                            "symbol": (r.get("spec") or {}).get("symbol"),
                            "gap_type": (r.get("spec") or {}).get("gap_type"),
                            "sleeve": (r.get("spec") or {}).get("sleeve"),
                            "critique": {k: _json_clean(v) for k, v in _extract(r.get("spec") or {}).items()},
                            "hit_symbols": _hit_sym_map.get(r["id"], []),
                            "hit_count": _hit_cnt.get(r["id"], (0, 0))[0],
                            "staged_count": _hit_cnt.get(r["id"], (0, 0))[1]} for r in directives],
            "recent_hits": [{k: _json_clean(v) for k, v in r.items()} for r in hits],
            "hermes_staging": {"total": staging.get("c"), "undrained": staging.get("undrained")},
            "promoted_to_watchlist": promoted.get("c"), "health": health}


def _retirement_planning_research(query=None):
    """GET /api/v2/retirement/planning-research — Hermes knowledge research on the operator's retirement /
    estate / tax / Medicare planning topics (research_type='topic_research'), grouped by theme. Read-only.
    Feeds the RetirementHub 'Planning Research' section. Advisory — consult professionals."""
    # Classify on the TOPIC NAME (concise + on-point) — NOT topic+summary, whose long
    # cross-references caused trading topics to leak in via bare "tax/income/dividend/nav".
    # Themes require retirement-SPECIFIC anchors; TRADING_EXCLUDE drops market/trading
    # research (sector rotation, options, swing/momentum, AI-datacenter, defense, etc.)
    # — those belong on Intelligence/Research, not the Retirement hub.
    THEMES = [("Roth & conversions", r"\broth\b|conversion|golden window|\brmd\b|backdoor|qualified charitable"),
              ("Medicare & IRMAA", r"medicare|irmaa|medigap|part [bd]\b"),
              ("Medicaid & asset protection", r"medicaid|\bmapt\b|asset protection|spend.?down|look.?back|estate recovery|special needs|supplemental needs"),
              ("Estate & trusts", r"estate|\btrust\b|probate|life estate|beneficiar|\bwill\b|inheritance"),
              ("SSDI & taxes", r"\bssdi\b|social security|disability|\bmagi\b|tax.?loss|tax-efficient|tax strateg|\bqcd\b|\bhsa\b|earnings test|substantial gainful"),
              ("Income & dividends (retirement)", r"dividend income|covered call|bond ladder|tips|fixed.?income|annuit|drawdown|income sleeve|monthly income|dividend aristocrat|income strateg|bucket strateg|\bcef\b|\bpty\b|\bnav\b")]
    TRADING_EXCLUDE = (r"swing|momentum|sector rotation|option|greeks|iron condor|earnings season|technical|breakout|scalp|"
                       r"reddit|chart|implied vol|theta|premium sell|datacenter|data center|semiconductor|ai chip|ai hardware|"
                       r"ai networking|ai datacenter|\bgpu\b|nvidia|defense|aerospace|materials sector|geopolitical|glp-1|"
                       r"weight.?loss|hot topics|controvers|collar|sentiment-driven|emerging sector|infrastructure buildout|"
                       r"hedging|catalyst|energy sector|utilities sector|consumer (defensive|staples)|healthcare rotation|trending|hype")
    rows = _db_query("""SELECT topic, summary, thesis, confidence_score, freshness_date, model_used,
                          research_type, created_at, status, evidence_json
                        FROM hermes_research_intelligence
                        WHERE research_type='topic_research'
                        ORDER BY created_at DESC LIMIT 400""") or []
    groups = {n: [] for n, _ in THEMES}
    import re as _re, json as _json
    seen = set()
    excluded = 0
    for r in rows:
        topic_name = (r.get("topic") or "")
        key = topic_name[:60]
        # drop market/trading research outright — it isn't retirement planning
        if _re.search(TRADING_EXCLUDE, topic_name, _re.I):
            excluded += 1
            continue
        # vetted sources this research grounded on (cataloged by the synthesizer; graded-good only)
        ev = r.get("evidence_json")
        ev = ev if isinstance(ev, dict) else (_json.loads(ev) if ev else {})
        srcs = [{"source": g.get("source"), "title": g.get("title"), "url": g.get("url")}
                for g in (ev.get("grounded_on") or [])][:6]
        for name, rx in THEMES:
            if _re.search(rx, topic_name, _re.I):
                if (name, key) in seen:
                    break
                seen.add((name, key))
                groups[name].append({"topic": r.get("topic"), "summary": (r.get("summary") or "")[:400],
                                     "thesis": (r.get("thesis") or "")[:300] or None,
                                     "confidence": _json_clean(r.get("confidence_score")),
                                     "status": r.get("status"), "model": r.get("model_used"),
                                     "sources": srcs, "source_count": len(srcs),
                                     "at": _json_clean(r.get("created_at"))})
                break
    out = [{"theme": n, "count": len(groups[n]), "items": groups[n][:8]} for n, _ in THEMES if groups[n]]
    return {"ok": True, "advisory_only": True, "as_of": datetime.now().astimezone().isoformat(),
            "themes": out, "total": sum(len(groups[n]) for n in groups),
            "excluded_non_retirement": excluded,
            "note": "Retirement/estate/tax/Medicare/SSDI planning research only (advisory; consult an "
                    "elder-law attorney + tax advisor). Trading/market research is filtered out to the "
                    "Intelligence/Research surfaces."}


def _data_source_health(query=None):
    """GET /api/v2/data-source-health — per-source freshness/yield monitor for EVERY ingest feed
    (news APIs, RSS, Finviz, FRED, YouTube, web-search). Each source: last update, recent volume, and a
    status vs its expected cadence (live/slow/stale/dead). This is the gap that let DuckDuckGo fail
    silently — job-level monitors saw topic_ingestion 'succeed' while a sub-source produced 0 for weeks.
    Read-only."""
    # (label, category, SQL → (last_ts, recent_count), expected-fresh hours, notes)
    # Age by INGEST time (created_at = when the feed last delivered to us), NOT the article's publish
    # date — several sources (DuckDuckGo, etc.) don't populate published_at, which would falsely read
    # as dead even while producing fresh rows.
    NEWS = ("SELECT max(created_at), count(*) FILTER (WHERE created_at>now()-interval '{w}') "
            "FROM news_articles WHERE source {op} %s")
    SPECS = [
        # news / RSS / API feeds (source LIKE/=)
        ("Yahoo RSS", "news", NEWS, "=", "yahoo_rss", 24),
        ("Google News RSS", "news", NEWS, "LIKE", "google_news%", 24),
        ("Google News (topic)", "news", NEWS, "=", "topic_google_news_rss", 48),
        ("Finnhub API", "news", NEWS, "=", "finnhub", 24),
        ("Finviz News", "news", NEWS, "=", "finviz_news", 24),
        ("Benzinga RSS", "news", NEWS, "=", "benzinga_rss", 48),
        ("Seeking Alpha", "news", NEWS, "=", "seeking_alpha", 72),
        ("YouTube (topic API)", "news", NEWS, "=", "topic_youtube_api", 72),
        ("DuckDuckGo (topic)", "websearch", NEWS, "=", "topic_duckduckgo", 168),
        ("Brave (topic)", "websearch", NEWS, "=", "topic_brave_news", 336),
        ("Hermes research", "research", NEWS, "=", "hermes", 48),
    ]
    out, now_iso = [], datetime.now().astimezone()
    for label, cat, tmpl, op, val, thr in SPECS:
        try:
            w = f"{max(thr*2, 48)} hours"
            row = _db_query(tmpl.format(w=w, op=op), (val,), fetch="one") or {}
            vals = list(row.values())
            last_ts = vals[0] if vals else None
            cnt = vals[1] if len(vals) > 1 else 0
            age_h = None
            if last_ts:
                try:
                    age_h = (now_iso - last_ts).total_seconds() / 3600.0
                except Exception:
                    age_h = None
            status = ("dead" if (age_h is None or age_h > thr * 4)
                      else "stale" if age_h > thr * 2
                      else "slow" if age_h > thr else "live")
            out.append({"source": label, "category": cat, "last_update": _json_clean(last_ts),
                        "age_hours": round(age_h, 1) if age_h is not None else None,
                        "recent_count": cnt or 0, "expected_fresh_h": thr, "status": status})
        except Exception as e:
            out.append({"source": label, "category": cat, "status": "error", "error": str(e)[:80]})
    # non-news feeds (own queries)
    def _feed(label, cat, sql, thr):
        try:
            r = _db_query(sql, fetch="one") or {}
            v = list(r.values()); last = v[0] if v else None; cnt = v[1] if len(v) > 1 else None
            age_h = (now_iso - last).total_seconds()/3600.0 if last else None
            status = ("dead" if (age_h is None or age_h > thr*4) else "stale" if age_h > thr*2
                      else "slow" if age_h > thr else "live")
            out.append({"source": label, "category": cat, "last_update": _json_clean(last),
                        "age_hours": round(age_h,1) if age_h is not None else None,
                        "recent_count": cnt, "expected_fresh_h": thr, "status": status})
        except Exception as e:
            out.append({"source": label, "category": cat, "status": "error", "error": str(e)[:80]})
    _feed("FRED macro", "macro", "SELECT max(fetched_at), count(*) FROM fred_economic_series", 72)
    _feed("Finviz screeners", "finviz", "SELECT max(last_run), count(*) FILTER (WHERE active) FROM finviz_screeners", 24)
    _feed("Finviz enrichment", "finviz", "SELECT max(last_enriched_at), count(*) FROM watchlist_items WHERE last_enriched_at IS NOT NULL", 48)
    _feed("Screener membership", "finviz", "SELECT max(last_seen_in_screener_at), count(*) FILTER (WHERE present_this_run) FROM screener_symbol_membership", 48)
    _feed("YouTube transcripts", "news", "SELECT max(ingested_at), count(*) FROM youtube_transcripts WHERE ingested_at>now()-interval '7 days'", 96)
    _feed("Catalyst events", "research", "SELECT max(created_at), count(*) FILTER (WHERE created_at>now()-interval '2 days') FROM catalyst_events", 24)
    _feed("Finviz sector/industry", "finviz", "SELECT max(created_at), count(*) FROM finviz_group_performance WHERE snapshot_date=(SELECT max(snapshot_date) FROM finviz_group_performance)", 30)
    _feed("SEC Form-4 insider", "research", "SELECT max(created_at), count(*) FILTER (WHERE filing_date>current_date-7) FROM sec_form4", 48)
    order = {"dead": 0, "error": 1, "stale": 2, "slow": 3, "live": 4}
    out.sort(key=lambda x: order.get(x.get("status"), 9))
    counts = {}
    for o in out:
        counts[o["status"]] = counts.get(o["status"], 0) + 1
    return {"ok": True, "as_of": now_iso.isoformat(), "sources": out, "summary": counts,
            "total": len(out),
            "note": "Per-source freshness vs expected cadence. status: live=within cadence, slow=1-2x late, "
                    "stale=2-4x late, dead=>4x late or no data. Catches silent sub-source failures."}


_FINVIZ_ENRICH_CACHE = {"mtime": 0, "data": {}}
def _finviz_enrichment(query=None):
    """GET /api/v2/finviz-enrichment?symbol=X — the ~60 Finviz fields already collected daily
    (ticker_enrichment_cache.json), grouped for display: technicals / performance / valuation /
    fundamentals / ownership. Read-only. mtime-cached so we don't re-read the 5k-ticker file each call."""
    q = query or {}
    sym = (q.get("symbol", [None])[0] if isinstance(q.get("symbol"), list) else q.get("symbol"))
    if not sym:
        return {"ok": False, "error": "symbol required"}
    sym = sym.upper().strip()
    try:
        p = PROJECT_ROOT / "data" / "state" / "ticker_enrichment_cache.json"
        mt = p.stat().st_mtime
        if mt != _FINVIZ_ENRICH_CACHE["mtime"]:
            _FINVIZ_ENRICH_CACHE["data"] = json.loads(p.read_text())
            _FINVIZ_ENRICH_CACHE["mtime"] = mt
    except Exception as e:
        return {"ok": False, "error": f"cache unavailable: {str(e)[:60]}"}
    d = _FINVIZ_ENRICH_CACHE["data"].get(sym) or {}
    if not d:
        return {"ok": True, "symbol": sym, "found": False, "groups": [], "note": "No Finviz enrichment cached."}
    GROUPS = [
        ("Technicals", [("RSI", "rsi"), ("RSI status", "rsi_status"), ("SMA20 %", "sma20_pct"),
                        ("SMA50 %", "sma50_pct"), ("SMA200 %", "sma200_pct"), ("ATR", "atr"),
                        ("Beta", "beta"), ("Volatility W %", "volatility_w_pct"), ("RVOL", "rvol"),
                        ("52w high %", "week52_high_pct"), ("52w low %", "week52_low_pct"),
                        ("Short float %", "short_float_pct"), ("Trend", "trend")]),
        ("Performance", [("Week %", "perf_week_pct"), ("Month %", "perf_month_pct"),
                         ("Quarter %", "perf_quarter_pct"), ("Half-yr %", "perf_halfyr_pct"),
                         ("YTD %", "perf_ytd_pct"), ("Year %", "perf_year_pct")]),
        ("Valuation", [("P/E", "pe"), ("Fwd P/E", "forward_pe"), ("PEG", "peg"), ("P/B", "pb"),
                       ("P/S", "ps"), ("P/FCF", "pfcf"), ("Mkt cap $B", "market_cap_b"),
                       ("Div yield %", "div_yield_pct")]),
        ("Fundamentals", [("Gross margin %", "gross_margin_pct"), ("Oper margin %", "oper_margin_pct"),
                          ("Profit margin %", "profit_margin_pct"), ("ROE %", "roe_pct"),
                          ("ROA %", "roa_pct"), ("ROIC %", "roic_pct"), ("EPS QoQ", "eps_qoq"),
                          ("EPS next Y", "eps_next_y"), ("Debt/Eq", "total_debt_equity")]),
        ("Ownership", [("Insider own %", "insider_own_pct"), ("Insider trans %", "insider_trans_pct"),
                       ("Inst own %", "inst_own_pct"), ("Inst trans %", "inst_trans_pct"),
                       ("Float M", "float_m"), ("Short ratio", "short_ratio")]),
    ]
    groups = []
    for gname, fields in GROUPS:
        items = [{"label": lbl, "value": _json_clean(d.get(key))} for lbl, key in fields if d.get(key) is not None]
        if items:
            groups.append({"group": gname, "items": items})
    return {"ok": True, "symbol": sym, "found": True, "company": d.get("company"),
            "sector": d.get("sector"), "industry": d.get("industry"),
            "cached_at": d.get("cached_at"), "groups": groups,
            "note": "Finviz enrichment (daily). Advisory."}


_FINVIZ_STRIP_CACHE_PATH = PROJECT_ROOT / "data" / "runtime" / "finviz_strip_map_cache.json"
_FINVIZ_STRIP_TTL_SEC = int(os.getenv("FINVIZ_STRIP_TTL_SEC", "600"))  # 10 min


def _finviz_strip_map(query=None):
    """GET /api/v2/finviz-strip-map — compact Finviz metrics for the whole watch universe in ONE call.

    Served from a pre-warmed disk TTL cache so the per-call universe queries (watchlist + proposals +
    symbol_profiles ANY(...)) never block the single-threaded server. `?fresh=1` forces recompute.
    """
    import time as _time
    _q = query or {}
    _fresh = str((_q.get("fresh", [""])[0] if isinstance(_q.get("fresh"), list) else _q.get("fresh")) or "").lower()
    if _fresh not in ("1", "true", "yes") and _FINVIZ_STRIP_CACHE_PATH.exists():
        try:
            _cached = json.loads(_FINVIZ_STRIP_CACHE_PATH.read_text())
            if _time.time() - float(_cached.get("_cached_at") or 0) < _FINVIZ_STRIP_TTL_SEC:
                _cached["cached"] = True
                return _cached
        except Exception:
            pass
    _out = _finviz_strip_map_compute()
    try:
        _out["_cached_at"] = _time.time()
        _FINVIZ_STRIP_CACHE_PATH.parent.mkdir(parents=True, exist_ok=True)
        _FINVIZ_STRIP_CACHE_PATH.write_text(json.dumps(_out, default=str))
    except Exception:
        pass
    return _out


def _finviz_strip_map_compute(query=None):
    """Heavy computation for the Finviz strip map (cached by _finviz_strip_map). Read-only."""
    try:
        p = PROJECT_ROOT / "data" / "state" / "ticker_enrichment_cache.json"
        mt = p.stat().st_mtime
        if mt != _FINVIZ_ENRICH_CACHE["mtime"]:
            _FINVIZ_ENRICH_CACHE["data"] = json.loads(p.read_text())
            _FINVIZ_ENRICH_CACHE["mtime"] = mt
    except Exception as e:
        return {"ok": False, "error": f"cache unavailable: {str(e)[:60]}", "map": {}}
    cache = _FINVIZ_ENRICH_CACHE["data"]
    # union of the surfaces that render Finviz strips: watchlist + open broker proposals + held positions
    syms = {r["symbol"] for r in (_db_query(
        "SELECT DISTINCT symbol FROM watchlist_items WHERE status<>'removed' AND symbol ~ '^[A-Z]{1,5}$'") or [])}
    syms |= {r["symbol"] for r in (_db_query(
        "SELECT DISTINCT symbol FROM paper_trade_proposals WHERE status IN ('PENDING','APPROVED') AND symbol ~ '^[A-Z]{1,5}$'") or [])}
    try:
        hj = _load_json(STATE_DIR / "holdings.json") or {}
        for h in hj.get("holdings", []):
            s = str(h.get("symbol", "")).upper()
            if s and not h.get("is_cash") and re.fullmatch(r"[A-Z]{1,5}", s):
                syms.add(s)
    except Exception:
        pass
    # Mutual funds aren't covered by Finviz (null strip) → fall back to symbol_profiles technicals computed
    # from yfinance NAV history (fund_technicals_enrich). Per-field fallback so a partial Finviz row still wins
    # where it has data. (operator 2026-06-21)
    _prof = {}
    try:
        for r in (_db_query("""SELECT upper(symbol) s, rsi14, perf_week_pct, perf_month_pct,
                                      ytd_return_pct, sma50_pct FROM symbol_profiles
                               WHERE upper(symbol) = ANY(%s)""", (sorted(syms),)) or []):
            _prof[r["s"]] = r
    except Exception:
        _prof = {}

    def _rsi_status(v):
        if v is None:
            return "unknown"
        return "oversold" if v <= 30 else "overbought" if v >= 70 else "neutral"

    out = {}
    for s in syms:
        d = cache.get(s) or {}
        pf = _prof.get(s) or {}
        rsi = d.get("rsi")
        rsi = rsi if rsi is not None else _json_clean(pf.get("rsi14"))
        pw = d.get("perf_week_pct"); pw = pw if pw is not None else _json_clean(pf.get("perf_week_pct"))
        pm = d.get("perf_month_pct"); pm = pm if pm is not None else _json_clean(pf.get("perf_month_pct"))
        pytd = d.get("perf_ytd_pct"); pytd = pytd if pytd is not None else _json_clean(pf.get("ytd_return_pct"))
        sma = d.get("sma50_pct"); sma = sma if sma is not None else _json_clean(pf.get("sma50_pct"))
        if rsi is None and pw is None and pm is None and pytd is None and sma is None:
            continue   # nothing for this symbol from either source
        out[s] = {"rsi": _json_clean(rsi),
                  "rsi_status": d.get("rsi_status") if d.get("rsi") is not None else _rsi_status(rsi),
                  "perf_week": _json_clean(pw), "perf_month": _json_clean(pm),
                  "perf_ytd": _json_clean(pytd), "sma50": _json_clean(sma),
                  "source": ("finviz" if d.get("rsi") is not None else "yfinance_nav")}
    return {"ok": True, "count": len(out), "map": out,
            "note": "Finviz inline-strip metrics (daily); mutual funds fall back to yfinance-NAV technicals."}


def _sector_performance(query=None):
    """GET /api/v2/sector-performance — latest Finviz sector + industry performance snapshot
    (leaders/laggards) for macro/rotation research. Read-only."""
    q = query or {}
    gtype = (q.get("type", ["sector"])[0] if isinstance(q.get("type"), list) else q.get("type")) or "sector"
    rows = _db_query("""SELECT name, change_pct, pe, dividend_yield, market_cap, stocks, snapshot_date
                        FROM finviz_group_performance
                        WHERE group_type=%s AND snapshot_date=(SELECT max(snapshot_date)
                              FROM finviz_group_performance WHERE group_type=%s)
                        ORDER BY change_pct DESC NULLS LAST""", (gtype, gtype)) or []
    items = [{"name": r.get("name"), "change_pct": _json_clean(r.get("change_pct")),
              "pe": _json_clean(r.get("pe")), "dividend_yield": _json_clean(r.get("dividend_yield")),
              "market_cap": _json_clean(r.get("market_cap")), "stocks": r.get("stocks"),
              "as_of": _json_clean(r.get("snapshot_date"))} for r in rows]
    return {"ok": True, "group_type": gtype, "count": len(items),
            "leaders": items[:5], "laggards": items[-5:][::-1], "items": items,
            "as_of": items[0]["as_of"] if items else None,
            "note": "Finviz group performance (advisory · macro/rotation lens)."}


def _insider_activity(query=None):
    """GET /api/v2/insider-activity[?symbol=X] — recent SEC Form-4 insider filings (authoritative) for a
    symbol, else across the held + active-watchlist universe. Read-only/advisory."""
    q = query or {}
    sym = (q.get("symbol", [None])[0] if isinstance(q.get("symbol"), list) else q.get("symbol"))
    if sym:
        rows = _db_query("""SELECT symbol, filer_name, filer_relation, transaction_type, shares, price,
                              total_value, ownership_after, filing_date, transaction_date, sec_url
                            FROM sec_form4 WHERE symbol=%s ORDER BY filing_date DESC NULLS LAST LIMIT 40""",
                         (sym.upper(),)) or []
    else:
        rows = _db_query("""SELECT s.symbol, s.filer_name, s.filer_relation, s.transaction_type, s.shares,
                              s.price, s.total_value, s.ownership_after, s.filing_date, s.transaction_date, s.sec_url
                            FROM sec_form4 s
                            WHERE s.filing_date > current_date - 30
                              AND (s.symbol IN (SELECT symbol FROM watchlist_items WHERE status<>'removed')
                                   OR s.symbol IN (SELECT symbol FROM watchlist_items WHERE source='portfolio'))
                            ORDER BY s.filing_date DESC NULLS LAST LIMIT 80""") or []
    items = [{k: _json_clean(v) for k, v in r.items()} for r in rows]
    return {"ok": True, "symbol": (sym or None), "count": len(items), "items": items,
            "note": "SEC Form-4 insider filings (authoritative). Advisory."}


def _watch_provenance(symbol):
    """GET /api/v2/watch/provenance/{symbol} — unified provenance contract for the shared pill row.
    origin + tier + freshness + directive link + Street consensus (Yahoo-authoritative) + divergence.
    Read-only. Uncovered symbol -> explicit nulls, never fabricated."""
    symbol = (symbol or "").upper().strip()
    if not symbol:
        return {"error": "symbol required"}
    item = _db_query("""SELECT wi.symbol, wi.origin_system, wi.origin_detail, wi.directive_id,
                          wi.in_directive_watch, wi.source_tier, wi.first_seen_at, wi.last_validated_at,
                          wi.seen_count, wi.provenance_reason, wi.source, d.label AS directive_label, d.kind AS directive_kind
                        FROM watchlist_items wi LEFT JOIN watch_directives d ON d.id = wi.directive_id
                        WHERE wi.symbol = %s ORDER BY wi.updated_at DESC NULLS LAST LIMIT 1""",
                     (symbol,), fetch="one") or {}
    pool = _db_query("""SELECT strategy_id, bucket, current_status, expires_at, origin_system, directive_id
                        FROM strategy_watchpool WHERE symbol = %s AND current_status = 'ACTIVE'
                        ORDER BY entered_at DESC""", (symbol,)) or []
    # Tier + divergence + Street consensus via the promotion engine's read-models (shared source of truth).
    tier, divergence, street = item.get("source_tier"), "unavailable", None
    try:
        import sys as _s
        _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import directive_promotion as _dp
        if item.get("origin_system"):
            tier = tier or _dp.get_source_tier(item.get("origin_system"))
        divergence = _dp.get_divergence_status(symbol)
        street = _dp.get_street_consensus(symbol)
    except Exception:
        pass
    return {"symbol": symbol,
            "origin_system": item.get("origin_system"), "origin_detail": item.get("origin_detail"),
            "source": item.get("source"),
            "directive": {"id": item.get("directive_id"), "label": item.get("directive_label"),
                          "kind": item.get("directive_kind")} if item.get("directive_id") else None,
            "in_directive_watch": item.get("in_directive_watch"),
            "source_tier": tier, "divergence": divergence,
            "first_seen_at": _json_clean(item.get("first_seen_at")),
            "last_validated_at": _json_clean(item.get("last_validated_at")),
            "seen_count": item.get("seen_count"), "reason": item.get("provenance_reason"),
            "watchpool": [{k: _json_clean(v) for k, v in r.items()} for r in pool],
            "street_consensus": street,
            "note": "Street consensus = Yahoo (authoritative). null = no professional coverage (not fabricated)."}


def _watch_directive_create(body):
    """POST /api/v2/watch/directives — create an operator watch directive (APP ROLE — the firewall:
    Hermes can never write this). kind ticker|sector|trend; spec is the resolution payload."""
    import json as _j
    kind = (body.get("kind") or "").strip().lower()
    label = (body.get("label") or "").strip()
    spec = body.get("spec") or {}
    if kind not in ("ticker", "sector", "trend"):
        return 400, {"ok": False, "error": "kind must be ticker|sector|trend"}
    if not label:
        return 400, {"ok": False, "error": "label required"}
    if kind == "ticker" and not (spec.get("symbol")):
        return 400, {"ok": False, "error": "ticker directive needs spec.symbol"}

    # ── KNOWLEDGE THEMES ARE RESEARCH TOPICS, NOT WATCH DIRECTIVES (operator 2026-06-21) ──────────────
    # A trend like "Roth conversion ladder" / "Medicaid Asset Protection Trust" / "IRMAA planning" can never
    # surface a tradeable ticker — creating a watch_directive for it just floods the watchlist with 0-hit
    # noise (it sat at "0 hits · 0 staged" forever). Route these to the KNOWLEDGE-research pipeline
    # (topic_monitor → Hermes/TradeAI research) ONLY; never create a ticker-discovery directive. Genuine
    # ticker-discovery trends ("AI datacenter", "Defense", "Energy") don't match and flow through normally.
    import re as _re
    if kind == "trend":
        _theme = _re.sub(r"^trend\s+", "", label or "", flags=_re.I).strip()
        _kws = [k for k in (spec.get("keywords") or []) if k]
        _planning = bool(_re.search(r"roth|irmaa|medicaid|medicare|ssdi|estate|trust|mapt|retire|tax|"
                                    r"conversion|dividend|covered call|income|cef|pty|nav|annuit",
                                    _theme + " " + " ".join(_kws), _re.I))
        if _planning and bool(body.get("hermes_enabled", True)):
            tid = "k_" + _re.sub(r"[^a-z0-9]+", "_", _theme.lower()).strip("_")[:46]
            queries = _kws[:8] if _kws else [_theme]
            ctx = ("Operator age 58 (59 Aug 2026), SSDI, NY, Medicare ~Dec 2026, Golden-Window Roth, MAPT "
                   "asset protection, ~$1.2M portfolio.")
            try:
                _db_query("""INSERT INTO topic_monitor (topic_id, display_name, search_queries, priority,
                               agent_owner, owner, enabled, max_age_days, min_articles, personal_context)
                             VALUES (%s,%s,%s::jsonb,2,'Steph','shared',true,30,3,%s)
                             ON CONFLICT (topic_id) DO NOTHING""",
                          (tid, _theme[:80], _j.dumps(queries), ctx), fetch="none")
            except Exception as e:
                return 200, {"ok": False, "error": "research-topic routing failed: " + str(e)[:160]}
            return 200, {"ok": True, "directive_id": None, "kind": "research_topic", "label": label,
                         "routed_to_research": True, "research_topic": {"topic_id": tid, "knowledge": True},
                         "note": "knowledge/planning theme → research pipeline only (no watchlist directive)"}

    # ── DEDUP TICKER DIRECTIVES (operator 2026-06-21) ────────────────────────────────────────────────
    # Don't stack a second active ticker directive for the same symbol — re-adds were creating duplicate
    # rows (CEG ×3, SOFI ×3, …) cluttering the Watch Directives list. Reuse the existing active directive
    # (it gets re-serviced below, so the symbol re-evaluates) instead of inserting a duplicate. The
    # existing label is preserved (don't clobber a named-list label with a generic re-add).
    reused = False
    did = None
    if kind == "ticker":
        _symU = (spec.get("symbol") or "").upper()
        _ex = _db_query("""SELECT id FROM watch_directives
                           WHERE kind='ticker' AND status='active' AND UPPER(spec->>'symbol')=%s
                           ORDER BY id LIMIT 1""", (_symU,), fetch="one")
        if _ex:
            did = _ex["id"]
            reused = True
    if did is None:
        row = _db_query("""INSERT INTO watch_directives (kind, label, spec, rationale, created_by, ttl_days, priority,
                              trade_ai_enabled, hermes_enabled)
                           VALUES (%s, %s, %s::jsonb, %s, %s, %s, %s, %s, %s) RETURNING id""",
                        (kind, label, _j.dumps(spec), body.get("rationale"),
                         body.get("created_by", "operator"), body.get("ttl_days"),
                         body.get("priority", "normal"),
                         bool(body.get("trade_ai_enabled", True)), bool(body.get("hermes_enabled", True))),
                        fetch="one")
        did = (row or {}).get("id")
    # ── SERVICE-AT-CREATION (operator caught 2026-06-12: CIFR added 22:47, servicer cron is
    # market-hours-only → ticker sat invisible until 09:00). Ticker directives now run through the
    # SAME real evaluation engine (directive_promotion.promote_directive_lead) synchronously, so the
    # symbol appears in the watchlist immediately, 24/7. Sector/trend directives still discover via
    # the cron (they are searches, not single symbols). Failure here never loses the directive —
    # the cron remains the safety net.
    serviced = None
    if kind == "ticker" and did:
        try:
            import sys as _sys
            _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
            import directive_promotion as _dp
            res = _dp.promote_directive_lead((spec.get("symbol") or "").upper(), did,
                                             f"directive:{label}", "operator", auto=True)
            serviced = {"status": res.get("status"), "detail": str(res)[:200]}
            _db_query("UPDATE watch_directives SET last_serviced_at=now(), updated_at=now() WHERE id=%s",
                      (did,), fetch="none")
        except Exception as e:
            serviced = {"status": "DEFERRED_TO_CRON", "detail": str(e)[:140]}
    # ── ROUTE TO BOTH (operator 2026-06-20: "make all route properly to trends and research both"): a
    # trend directive feeds TICKER DISCOVERY only — but knowledge themes (Roth/Medicaid/sector theses)
    # need the KNOWLEDGE-research pipeline too. Mirror every trend directive into topic_monitor (owner
    # 'shared' → researched by BOTH Hermes + TradeAI via the topic bridge). Idempotent; non-fatal.
    research_topic = None
    if kind == "trend" and did and bool(body.get("hermes_enabled", True)):
        try:
            import re as _re
            theme = _re.sub(r"^trend\s+", "", label or "", flags=_re.I).strip()
            tid = "d{}_{}".format(did, _re.sub(r"[^a-z0-9]+", "_", theme.lower()).strip("_")[:44])
            kws = [k for k in (spec.get("keywords") or []) if k]
            queries = kws[:8] if kws else [theme]
            planning = bool(_re.search(r"roth|irmaa|medicaid|medicare|ssdi|estate|trust|mapt|retire|tax|"
                                       r"conversion|dividend|covered call|income|cef|pty|nav|annuit", theme + " " + " ".join(kws), _re.I))
            ctx = ("Operator age 58 (59 Aug 2026), SSDI, NY, Medicare ~Dec 2026, Golden-Window Roth, MAPT "
                   "asset protection, ~$1.2M portfolio.") if planning else ""
            _db_query("""INSERT INTO topic_monitor (topic_id, display_name, search_queries, priority,
                           agent_owner, owner, enabled, max_age_days, min_articles, personal_context)
                         VALUES (%s,%s,%s::jsonb,%s,%s,'shared',true,30,3,%s) ON CONFLICT (topic_id) DO NOTHING""",
                      (tid, theme[:80], _j.dumps(queries), 2 if planning else 4,
                       "Steph" if planning else "Alex", ctx), fetch="none")
            research_topic = {"topic_id": tid, "planning": planning}
        except Exception as e:
            research_topic = {"error": str(e)[:120]}
    return 200, {"ok": True, "directive_id": did, "kind": kind, "label": label, "serviced": serviced,
                 "research_topic": research_topic, "reused": reused}


def _watch_directive_promote(body):
    """POST /api/v2/watch/directives/promote — operator one-tap promotion of a staged hit.
    Routes through the real engine with auto=True (operator override); scalp firewall + fail-closed
    still apply. Runs under the app role."""
    symbol = (body.get("symbol") or "").upper().strip()
    directive_id = body.get("directive_id")
    if not symbol or not directive_id:
        return 400, {"ok": False, "error": "symbol and directive_id required"}
    try:
        import sys as _s
        _s.path.insert(0, str(PROJECT_ROOT / "scripts"))
        import directive_promotion as _dp
        res = _dp.promote_directive_lead(symbol, int(directive_id),
                                         body.get("reason") or "operator one-tap promote",
                                         body.get("source_system") or "operator",
                                         auto=True, actor="operator")
        return 200, {"ok": True, "result": res}
    except Exception as e:
        return 500, {"ok": False, "error": str(e)[:200]}


def _watchpool_list(query=None):
    """GET /api/v2/watchpool — unified watchpool: strategy_watchpool rows with origin + directive link.
    Read-only. Powers the /v3/watchpool page (screener candidates + directive-sourced, same pill row)."""
    rows = _db_query("""SELECT sp.id, sp.strategy_id, sp.symbol, sp.screener_id, sp.bucket, sp.current_status,
                          sp.entered_at, sp.expires_at, sp.origin_system, sp.directive_id, d.label AS directive_label
                        FROM strategy_watchpool sp LEFT JOIN watch_directives d ON d.id = sp.directive_id
                        ORDER BY sp.entered_at DESC LIMIT 200""") or []
    by_status, by_origin = {}, {}
    for r in rows:
        st = r.get("current_status") or "?"
        by_status[st] = by_status.get(st, 0) + 1
        o = r.get("origin_system") or "screener"
        by_origin[o] = by_origin.get(o, 0) + 1
    return {"count": len(rows), "by_status": by_status, "by_origin": by_origin,
            "rows": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}


def _watch_sectors(query=None):
    """GET /api/v2/watch/sectors — Finviz sector list with DISTINCT constituent counts + sample
    symbols, for the Add-Watch sector dropdown + constituent preview. Read-only."""
    rows = _db_query("""SELECT sector, count(DISTINCT symbol) AS n,
                          (array_agg(DISTINCT symbol ORDER BY symbol))[1:10] AS sample
                        FROM incubator_universe WHERE sector IS NOT NULL AND sector <> ''
                        GROUP BY sector ORDER BY count(DISTINCT symbol) DESC""") or []
    return {"sectors": [{"sector": r["sector"], "count": r["n"], "sample": r.get("sample") or []} for r in rows]}


def _hermes_setup(rsi, trend):
    """Classify a trade setup (spec §8) from posture. Advisory — entry/invalidation/conviction."""
    r = float(rsi) if rsi is not None else None
    t = (trend or "").lower()
    if r is None or t in ("", "unknown"):
        return {"type": "no-trade / low-conviction", "entry": "insufficient signal", "invalidation": "—",
                "conviction": "low", "why": "awaiting enrichment / no clear posture"}
    if t == "bullish" and r < 45:
        return {"type": "pullback entry", "entry": "buy strength off the pullback", "invalidation": "loss of the recent higher-low",
                "conviction": "medium", "why": "uptrend with RSI cooled into a buy zone"}
    if t == "bullish" and r < 65:
        return {"type": "trend continuation", "entry": "join on continuation / minor pullback", "invalidation": "break below trend support",
                "conviction": "medium-high", "why": "uptrend intact, RSI constructive"}
    if t == "bullish":
        return {"type": "momentum continuation (extended)", "entry": "only on a controlled pullback", "invalidation": "momentum stall + RSI roll-over",
                "conviction": "medium", "why": "strong momentum but RSI extended — chase risk"}
    if t == "bearish" and r < 38:
        return {"type": "reversal / mean-reversion watch", "entry": "wait for a reversal trigger", "invalidation": "new lows",
                "conviction": "low-medium", "why": "downtrend but oversold — bounce possible, not confirmed"}
    if t == "bearish":
        return {"type": "no-trade (downtrend)", "entry": "stand aside / short bias only", "invalidation": "reclaim of trend",
                "conviction": "low", "why": "downtrend without an oversold edge"}
    return {"type": "range / mean-reversion", "entry": "fade the edges of the range", "invalidation": "range break",
            "conviction": "low", "why": "neutral trend — range conditions"}


def _hermes_risks(comp, divergence, advisory):
    out = []
    if (comp.get("_coverage") or 1) < 0.45:
        out.append("thin intelligence coverage — score from few factors")
    if divergence == "divergent":
        out.append("internal view diverges from Street (analyst) consensus")
    if advisory and "caution" in str(advisory).lower():
        out.append("RSI band historically weak (setup-advisory caution)")
    if comp.get("social_sentiment") and not comp.get("setup_quality"):
        out.append("attention-driven (social) without a qualified strategy setup")
    return out


def _hermes_competition(symbol, sector, industry):
    """H-3: peer group from same industry (fallback sector) + relative strength by Hermes score.
    Limited to peers with intelligence coverage; honest 'no peers' when none. Advisory."""
    key, val = ("industry", industry) if industry else ("sector", sector)
    if not val:
        return None
    peers = _db_query(f"""SELECT e.display_name AS symbol, wi.hermes_composite_score AS score,
                            e.change_pct, wi.trend
                          FROM intelligence_entities e
                          LEFT JOIN watchlist_items wi ON wi.symbol = e.display_name
                          WHERE e.{key} = %s AND e.display_name ~ '^[A-Z]{{1,5}}$' AND e.display_name <> %s
                          ORDER BY wi.hermes_composite_score DESC NULLS LAST LIMIT 12""", (val, symbol)) or []
    if not peers:
        return {"peer_group": val, "peer_count": 0, "peers": [], "vs_peers": "no peers with intelligence coverage"}
    scores = [float(p["score"]) for p in peers if p.get("score") is not None]
    me = _db_query("""SELECT hermes_composite_score FROM watchlist_items WHERE symbol=%s
                      ORDER BY hermes_composite_score DESC NULLS LAST LIMIT 1""", (symbol,), fetch="one") or {}
    my = me.get("hermes_composite_score")
    rel_rank, vs = None, "unknown"
    if my is not None and scores:
        my = float(my)
        rel_rank = f"#{sum(1 for s in scores if s > my) + 1} of {len(scores) + 1} in {val}"
        med = sorted(scores)[len(scores) // 2]
        vs = "leading peers" if my > med else "lagging peers"
    return {"peer_group": val, "peer_count": len(peers),
            "peers": [{"symbol": p["symbol"], "score": _json_clean(p.get("score")), "trend": p.get("trend")} for p in peers[:6]],
            "relative_rank": rel_rank, "vs_peers": vs}


def _hermes_intel(symbol):
    """GET /api/v2/hermes/intel/{symbol} — structured Hermes intelligence card (spec §9): composite
    score + rank + confidence, factor breakdown, analyst / sector / social views, trade-setup
    recommendation, catalysts, risks. Read-only; advisory."""
    symbol = (symbol or "").upper().strip()
    wi = _db_query("""SELECT symbol, hermes_composite_score, hermes_rank, hermes_score_components,
                        hermes_scored_at, rsi, trend, price, change_pct, setup_advisory,
                        origin_system, source_tier, directive_id
                      FROM watchlist_items WHERE symbol=%s AND status <> 'removed'
                      ORDER BY hermes_composite_score DESC NULLS LAST LIMIT 1""", (symbol,), fetch="one")
    if not wi:
        return {"symbol": symbol, "note": "not on the watchlist or not yet scored"}
    comp = wi.get("hermes_score_components") or {}
    ie = _db_query("""SELECT sector, industry, social_sentiment, social_score, catalyst, catalyst_verified, rvol
                      FROM intelligence_entities WHERE display_name=%s LIMIT 1""", (symbol,), fetch="one") or {}
    analyst, divergence = None, None
    try:
        import json as _j
        pills = {p["symbol"].upper(): p for p in _j.loads((PROJECT_ROOT / "data" / "runtime" / "pro_analyst_pills_latest.json").read_text()).get("pills", [])}
        p = pills.get(symbol)
        if p and p.get("has_professional_coverage"):
            divergence = p.get("divergence")
            analyst = {"recommendation": p.get("recommendation_key"), "rec_mean": p.get("recommendation_mean"),
                       "target_mean": p.get("target_mean_price"), "upside_pct": p.get("upside_to_mean_target_pct"),
                       "analysts": p.get("number_of_analyst_opinions"), "divergence": divergence,
                       "latest_event": p.get("latest_event_headline")}
    except Exception:
        pass
    factors = [{"factor": k, **v} for k, v in comp.items() if not k.startswith("_")]
    factors.sort(key=lambda f: -(f.get("score", 0) * f.get("weight", 0)))
    # H-6: external-LLM full theses (latest per lane) for the intel-card drawer
    ext_rows = _db_query("""SELECT DISTINCT ON (lane) lane, model, recommendation, evidence_json, dissent,
                              confidence, risk_flags, created_at
                            FROM hermes_external_research
                            WHERE symbol=%s AND status IN ('sent','ok','complete','success')
                            ORDER BY lane, created_at DESC""", (symbol,)) or []
    external_intel = [{"lane": e["lane"], "model": e.get("model"), "recommendation": e.get("recommendation"),
                       "evidence": e.get("evidence_json"), "dissent": e.get("dissent"),
                       "confidence": _json_clean(e.get("confidence")), "risk_flags": e.get("risk_flags"),
                       "at": _json_clean(e.get("created_at"))} for e in ext_rows]
    return {"symbol": symbol, "composite_score": _json_clean(wi.get("hermes_composite_score")),
            "external_intel": external_intel,
            "rank": wi.get("hermes_rank"), "confidence": comp.get("_confidence"), "coverage": comp.get("_coverage"),
            "raw_score": comp.get("_raw_score"), "scored_at": _json_clean(wi.get("hermes_scored_at")),
            "factors": factors, "analyst": analyst,
            "sector": {"sector": ie.get("sector"), "industry": ie.get("industry")} if ie.get("sector") else None,
            "competition": _hermes_competition(symbol, ie.get("sector"), ie.get("industry")),
            "social": {"sentiment": ie.get("social_sentiment"), "score": _json_clean(ie.get("social_score"))} if (ie.get("social_sentiment") or ie.get("social_score")) else None,
            "setup": _hermes_setup(wi.get("rsi"), wi.get("trend")),
            "catalysts": [str(ie["catalyst"])[:160]] if ie.get("catalyst") else [],
            "risks": _hermes_risks(comp, divergence, wi.get("setup_advisory")),
            "technical": {"rsi": _json_clean(wi.get("rsi")), "trend": wi.get("trend"),
                          "rvol": _json_clean(ie.get("rvol")), "price": _json_clean(wi.get("price")),
                          "change_pct": _json_clean(wi.get("change_pct"))},
            "provenance": {"origin": wi.get("origin_system"), "tier": wi.get("source_tier"),
                           "directive_id": wi.get("directive_id")},
            "note": "Advisory composite of news/social, analyst, sector, momentum, setup, R:R. Never gates execution."}


def _hermes_external_intel_map(query=None):
    """GET /api/v2/hermes/external-intel-map — per-symbol external-LLM curation (which lane curated it +
    when + verdict) from hermes_external_research (last 14d). Powers the watchlist 'curated by
    ChatGPT/Grok' badges + tooltip dates. Read-only; advisory."""
    rows = _db_query("""SELECT DISTINCT ON (symbol, lane) symbol, lane, model, created_at, recommendation, confidence
                        FROM hermes_external_research
                        WHERE status IN ('sent','ok','complete','success') AND symbol IS NOT NULL
                          AND created_at > now() - interval '14 days'
                        ORDER BY symbol, lane, created_at DESC""") or []
    out = {}
    for r in rows:
        out.setdefault(r["symbol"], []).append({
            "lane": r["lane"], "model": r.get("model"), "at": _json_clean(r["created_at"]),
            "recommendation": r.get("recommendation"), "confidence": _json_clean(r.get("confidence"))})
    return {"map": out, "symbols": len(out)}


def _hermes_subject_intel(query=None):
    """GET /api/v2/hermes/subject-intel?type=&key= — external-LLM full theses for ANY subject
    (proposal/position/closed_trade/sector/report), latest per lane. Powers the per-surface drawers."""
    q = query or {}
    ttype, key = q.get("type", ""), q.get("key", "")
    if not ttype or not key:
        return {"external_intel": []}
    rows = _db_query("""SELECT DISTINCT ON (lane) lane, model, recommendation, evidence_json, dissent,
                          confidence, risk_flags, created_at
                        FROM hermes_external_research
                        WHERE symbol=%s AND trigger_reason=%s AND status IN ('sent','ok','complete','success')
                        ORDER BY lane, created_at DESC""", (key, f"enh_{ttype}")) or []
    # Hermes composite (2026-06-11): the watchlist intelligence rank surfaces wherever decisions happen
    hermes = None
    try:
        h = _db_query("""SELECT hermes_composite_score, hermes_rank,
                                hermes_score_components->>'_regime' AS regime
                         FROM watchlist_items
                         WHERE symbol=%s AND hermes_rank IS NOT NULL
                         ORDER BY hermes_rank LIMIT 1""", (key,), fetch="one")
        if h:
            hermes = {"composite": _json_clean(h.get("hermes_composite_score")),
                      "rank": h.get("hermes_rank"), "regime": h.get("regime")}
    except Exception:
        pass
    return {"type": ttype, "key": key, "hermes": hermes, "external_intel": [
        {"lane": r["lane"], "model": r.get("model"), "recommendation": r.get("recommendation"),
         "evidence": r.get("evidence_json"), "dissent": r.get("dissent"),
         "confidence": _json_clean(r.get("confidence")), "risk_flags": r.get("risk_flags"),
         "at": _json_clean(r.get("created_at"))} for r in rows]}


def _hermes_subject_intel_map(query=None):
    """GET /api/v2/hermes/subject-intel-map?type= — per-key {lane, recommendation, at} for a subject type
    (last 14d). Powers the per-surface ✦ Grok / ✦ ChatGPT badges."""
    ttype = (query or {}).get("type", "")
    if not ttype:
        return {"map": {}, "keys": 0}
    rows = _db_query("""SELECT DISTINCT ON (symbol, lane) symbol, lane, model, recommendation, created_at
                        FROM hermes_external_research WHERE trigger_reason=%s
                          AND status IN ('sent','ok','complete','success') AND created_at > now()-interval '14 days'
                        ORDER BY symbol, lane, created_at DESC""", (f"enh_{ttype}",)) or []
    out = {}
    for r in rows:
        out.setdefault(r["symbol"], []).append({"lane": r["lane"], "model": r.get("model"),
            "recommendation": r.get("recommendation"), "at": _json_clean(r["created_at"])})
    return {"type": ttype, "map": out, "keys": len(out)}


def _discovery_run(body):
    """POST /api/v2/discovery/run {query, lane?} — discover relevant public companies for a query via the
    free Grok/ChatGPT OAuth lane (D-1). Returns structured {ticker, relevance_score, relationship_type,
    exposure_strength, reason, verified}."""
    import hermes_discovery as hd
    q = ((body or {}).get("query") or "").strip()
    if not q:
        return 400, {"ok": False, "error": "query required"}
    lane = (body or {}).get("lane", "grok")
    lane = lane if lane in ("grok", "chatgpt") else "grok"
    try:
        return 200, {"ok": True, "data": hd.run(q, lane=lane, apply=True)}
    except Exception as e:
        return 500, {"ok": False, "error": str(e)[:200]}


def _discovery_results(query=None):
    """GET /api/v2/discovery/results?query_id= — results for a query (or recent queries if omitted)."""
    qid = (query or {}).get("query_id")
    if qid:
        rows = _db_query("""SELECT ticker, company_name, relevance_score, relationship_type, exposure_strength,
                              reason, verified, added_to_watchlist FROM discovery_results
                            WHERE query_id=%s ORDER BY relevance_score DESC""", (int(qid),)) or []
        meta = _db_query("SELECT query, mode, lane, status, result_count, created_at FROM discovery_queries WHERE id=%s",
                         (int(qid),), fetch="one") or {}
        return {"query_id": int(qid), "meta": {**meta, "created_at": _json_clean(meta.get("created_at"))},
                "results": [{**r, "relevance_score": _json_clean(r["relevance_score"])} for r in rows]}
    qs = _db_query("""SELECT id, query, mode, status, result_count, created_at FROM discovery_queries
                      ORDER BY created_at DESC LIMIT 20""") or []
    return {"queries": [{**x, "created_at": _json_clean(x["created_at"])} for x in qs]}


def _discovery_add(body):
    """POST /api/v2/discovery/add-to-watchlist {query_id, tickers?[], top_n?} — add discovered names to the
    watchlist with discovery provenance; the enrichment sweep + Hermes scorer then take over (D-4)."""
    b = body or {}
    qid = b.get("query_id")
    if not qid:
        return 400, {"ok": False, "error": "query_id required"}
    rows = _db_query("SELECT ticker, relationship_type FROM discovery_results WHERE query_id=%s ORDER BY relevance_score DESC",
                     (int(qid),)) or []
    if b.get("tickers"):
        tset = {str(t).upper() for t in b["tickers"]}
        rows = [r for r in rows if r["ticker"] in tset]
    elif b.get("top_n"):
        rows = rows[:int(b["top_n"])]
    qry = (_db_query("SELECT query FROM discovery_queries WHERE id=%s", (int(qid),), fetch="one") or {}).get("query", "")
    prov = f"discovery: {qry}"[:200]
    added = []
    for r in rows:
        if _db_query("SELECT 1 FROM watchlist_items WHERE symbol=%s AND status<>'removed' LIMIT 1", (r["ticker"],), fetch="one"):
            _db_query("""UPDATE watchlist_items SET discovery_query_id=%s, discovery_relationship=%s,
                          provenance_reason=COALESCE(provenance_reason,%s), updated_at=NOW()
                         WHERE symbol=%s AND status<>'removed'""",
                      (int(qid), r["relationship_type"], prov, r["ticker"]), fetch="none")
        else:
            _db_query("""INSERT INTO watchlist_items (symbol, source, status, origin_system, asset_type,
                          discovery_query_id, discovery_relationship, provenance_reason)
                         VALUES (%s,'discovery','active','discovery','equity',%s,%s,%s)""",
                      (r["ticker"], int(qid), r["relationship_type"], prov), fetch="none")
        added.append(r["ticker"])
    if added:
        _db_query("UPDATE discovery_results SET added_to_watchlist=TRUE WHERE query_id=%s AND ticker = ANY(%s)",
                  (int(qid), added), fetch="none")
        # kick off enrichment + scoring now so the names get composite scores within a couple minutes
        try:
            import subprocess
            subprocess.Popen(["nohup", "bash", "-c",
                f"cd {PROJECT_ROOT} && {sys.executable} scripts/watchlist_enrichment_sweep.py --once --limit 40 "
                f">> logs/discovery_enrich.log 2>&1 && {sys.executable} scripts/hermes_watchlist_scorer.py --once "
                f">> logs/discovery_enrich.log 2>&1"],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, stdin=subprocess.DEVNULL, start_new_session=True)
        except Exception:
            pass
    return 200, {"ok": True, "added": added, "count": len(added),
                 "note": "Added to the watchlist — enrichment + Hermes scoring kicked off (scores appear shortly)."}


def _trade_chart(query=None):
    """GET /api/v2/trade-chart?symbol=&entry_date=&exit_date=&entry_price=&exit_price= — OHLCV + VWAP/MACD/RSI
    + entry/exit markers for a per-trade replay chart. Source hierarchy: Alpaca -> Schwab -> Finviz image."""
