def _finviz_chart(query=None):
    """GET /api/v2/finviz-chart?symbol=&p= — proxy the Finviz Elite chart IMAGE (attaches the Elite cookie
    server-side; the browser can't). Returns the PNG bytes. Tier-3 fallback when Alpaca/Schwab have no bars."""
    import os as _os, urllib.request
    q = query or {}
    g = (lambda k: (q.get(k) or [None])[0] if isinstance(q.get(k), list) else q.get(k))
    sym = (g("symbol") or "").upper()[:8]
    p = g("p") or "d"
    if not sym.isalnum():
        return 400, {"ok": False, "error": "bad symbol"}
    import base64 as _b64
    ck = _os.environ.get("FINVIZ_COOKIE", "").strip().strip('"\'')
    ua = _os.environ.get("FINVIZ_USER_AGENT", "Mozilla/5.0").strip().strip('"\'')
    url = f"https://elite.finviz.com/chart.ashx?t={sym}&ty=c&ta=1&p={p}&s=l"
    try:
        req = urllib.request.Request(url, headers={"Cookie": ck, "User-Agent": ua})
        with urllib.request.urlopen(req, timeout=12) as r:
            data = r.read()
        if data[:8].startswith(b"\x89PNG") or data[:3] == b"\xff\xd8\xff":  # PNG or JPEG
            mime = "image/png" if data[:8].startswith(b"\x89PNG") else "image/jpeg"
            # base64 data URI — the server JSON-serializes, so we can't stream raw bytes
            return {"ok": True, "symbol": sym, "image": f"data:{mime};base64," + _b64.b64encode(data).decode()}
        return 502, {"ok": False, "error": "finviz returned non-image (cookie expired — refresh FINVIZ_COOKIE in System > secrets)"}
    except Exception as e:
        return 502, {"ok": False, "error": str(e)[:120]}


def _upload_csv(body):
    """POST /api/v2/upload-csv {dest, filename, content} — save an operator CSV to a whitelisted import dir.

    For remote (Tailscale) operators who can't drop files on the box. Whitelisted dirs only; filename is
    sanitized to a basename (no traversal); .csv/.txt only; size-capped. Read-only data intake, no exec."""
    import os as _os, re as _re
    b = body or {}
    dest = (b.get("dest") or "").strip()
    fn = (b.get("filename") or "").strip()
    content = b.get("content") or ""
    ALLOWED = {"schwab_history", "schwab_gainloss", "tos_watchlists"}
    if dest not in ALLOWED:
        return 400, {"ok": False, "error": f"dest must be one of {sorted(ALLOWED)}"}
    fn = _re.sub(r"[^A-Za-z0-9._-]", "_", _os.path.basename(fn))
    if not fn or not _re.search(r"\.(csv|txt)$", fn, _re.I):
        return 400, {"ok": False, "error": "filename must end in .csv or .txt"}
    if not isinstance(content, str) or len(content) > 12_000_000:
        return 400, {"ok": False, "error": "content missing or too large (>12MB)"}
    base = (PROJECT_ROOT / "imports" / dest).resolve()
    base.mkdir(parents=True, exist_ok=True)
    path = (base / fn).resolve()
    if _os.path.commonpath([str(base), str(path)]) != str(base):
        return 400, {"ok": False, "error": "invalid path"}
    path.write_text(content)
    return 200, {"ok": True, "saved": f"imports/{dest}/{fn}", "bytes": len(content),
                 "rows": content.count(chr(10))}


def _execution_hypotheses(query=None):
    """GET /api/v2/backtesting/execution-hypotheses?strategy=&symbol= — evidence-only rule-variant aggregates."""
    q = query or {}
    g = (lambda k: (q.get(k) or [None])[0] if isinstance(q.get(k), list) else q.get(k))
    where, params = ["applicable"], []
    if g("strategy"):
        where.append("strategy_id=%s"); params.append(g("strategy"))
    if g("symbol"):
        where.append("symbol=%s"); params.append(g("symbol").upper())
    agg = _db_query(f"""SELECT hypothesis, count(*) AS sample,
                          round(100.0*count(*) FILTER(WHERE improved)/count(*)) AS improved_pct,
                          round(avg(delta_ps),4) AS avg_delta_ps, (count(*) < 5) AS do_not_graft
                        FROM trade_execution_hypothesis_results WHERE {' AND '.join(where)}
                        GROUP BY hypothesis ORDER BY avg(delta_ps) DESC""", tuple(params)) or []
    return {"aggregate": [_json_clean(r) for r in agg], "note": "Evidence only — never auto-applied to live strategy configs."}


def _execution_quality(query=None):
    """GET /api/v2/journal/execution-quality?source=&symbol=&limit= — computed execution grades + Grok review."""
    q = query or {}
    g = (lambda k: (q.get(k) or [None])[0] if isinstance(q.get(k), list) else q.get(k))
    where, params = ["path_status='OK'"], []
    if g("source"):
        where.append("source=%s"); params.append(g("source"))
    if g("symbol"):
        where.append("symbol=%s"); params.append(g("symbol").upper())
    limit = min(int(g("limit") or 200), 500)
    rows = _db_query(f"""SELECT trade_key, source, symbol, account, entry_time, exit_time, strategy_id, outcome_grade, execution_grade,
                          entry_timing_grade, exit_timing_grade, capture_ratio, entry_volume_ratio,
                          entry_above_vwap, mfe_after_exit_pct, missed_opportunity_grade, computed_summary,
                          strategy_rule_violations, grok_execution_label, grok_what_to_do_next_time,
                          grok_strategy_backtest_hypotheses, normalized_tags,
                          entry_price, exit_price, mfe_after_entry, mae_after_entry, post_exit_high,
                          runner_type, post_exit_gave_back_ratio
                         FROM v_trade_execution_quality_latest WHERE {' AND '.join(where)}
                         ORDER BY exit_time DESC LIMIT {limit}""", tuple(params)) or []
    return {"trades": [_json_clean(r) for r in rows], "count": len(rows)}


def _daily_coaching(query=None):
    """GET /api/v2/journal/daily-execution-coaching[/latest] — latest coaching run + ranked items + Grok digest.
    Read-only/advisory: no live-strategy/trading state. Hypotheses surface as shadow-research candidates only."""
    run = _db_query("SELECT * FROM daily_execution_coaching_runs ORDER BY id DESC LIMIT 1")
    if not run:
        return {"run": None, "items": [], "digest": None, "advisory": True}
    run = run[0]
    items = _db_query("SELECT rank, severity, item_type, symbol, strategy_family, source, sample_size, "
                      "avg_capture_ratio, avg_missed_pct, avg_delta_ps, lesson, operator_action, status, trade_keys_json "
                      "FROM daily_execution_coaching_items WHERE run_id=%s ORDER BY rank", (run["id"],)) or []
    digest = _db_query("SELECT digest_json, review_status, created_at FROM daily_execution_grok_digests "
                       "WHERE run_id=%s ORDER BY id DESC LIMIT 1", (run["id"],))
    return {"run": _json_clean(run), "items": [_json_clean(i) for i in items],
            "digest": _json_clean(digest[0]) if digest else None, "advisory": True}


def _tos_watchlists_list(query=None):
    """GET /api/v2/tos-watchlists — ToS-imported watchlists with members (active + removed dates) + events."""
    wls = _db_query("""SELECT id, name, display_name, strategy_match, notes, symbol_count, last_imported_at,
                         created_at FROM tos_watchlists ORDER BY COALESCE(display_name, name)""") or []
    out = []
    for w in wls:
        mems = _db_query("""SELECT symbol, added_at, removed_at, notes FROM tos_watchlist_members
                            WHERE watchlist_id=%s ORDER BY (removed_at IS NOT NULL), symbol""", (w["id"],)) or []
        out.append({**w, "last_imported_at": _json_clean(w["last_imported_at"]), "created_at": _json_clean(w["created_at"]),
                    "active": [{"symbol": m["symbol"], "added_at": _json_clean(m["added_at"]), "notes": m["notes"]}
                               for m in mems if not m["removed_at"]],
                    "removed": [{"symbol": m["symbol"], "added_at": _json_clean(m["added_at"]),
                                 "removed_at": _json_clean(m["removed_at"])} for m in mems if m["removed_at"]]})
    return {"watchlists": out, "count": len(out),
            "note": "ToS (thinkorswim) watchlists — Schwab Trader API has no watchlist endpoint, so these import from imports/tos_watchlists/. Add/remove dates tracked."}


def _tos_watchlist_manage(body):
    """POST /api/v2/tos-watchlists/manage {watchlist_id, action: rename|strategy|notes|member_note, value, symbol?}."""
    b = body or {}
    wid, action, value = b.get("watchlist_id"), (b.get("action") or "").lower(), b.get("value")
    if not wid or action not in ("rename", "strategy", "notes", "member_note"):
        return 400, {"ok": False, "error": "watchlist_id + action(rename|strategy|notes|member_note) required"}
    col = {"rename": "display_name", "strategy": "strategy_match", "notes": "notes"}.get(action)
    if col:
        _db_query(f"UPDATE tos_watchlists SET {col}=%s, updated_at=NOW() WHERE id=%s", (value, int(wid)), fetch="none")
        return 200, {"ok": True, "watchlist_id": wid, "action": action, "value": value}
    # member_note: per-symbol note
    _db_query("UPDATE tos_watchlist_members SET notes=%s WHERE watchlist_id=%s AND symbol=%s",
              (value, int(wid), b.get("symbol")), fetch="none")
    return 200, {"ok": True, "watchlist_id": wid, "action": "member_note", "symbol": b.get("symbol")}


def _schwab_round_trips(query=None):
    """GET /api/v2/journal/schwab-round-trips — real-account round-trips (5-min agg + FIFO from the
    API-authoritative ledger). Read-only."""
    rows = _db_query("""SELECT account, symbol, entry_time, exit_time, hold_minutes, qty, entry_price,
                          exit_price, gross_pnl, fees, net_pnl, pnl_pct, classification,
                          strategy_tag, entry_grade, exit_grade, lesson, review_lane, basis_status, basis_source,
                          canary
                        FROM schwab_round_trips ORDER BY exit_time DESC LIMIT 600""") or []
    trips = [{**r, "entry_time": _json_clean(r["entry_time"]), "exit_time": _json_clean(r["exit_time"]),
              **{k: _json_clean(r[k]) for k in ("qty", "entry_price", "exit_price", "gross_pnl", "fees", "net_pnl", "pnl_pct")}}
             for r in rows]
    # ACTIVE trading stats EXCLUDE long-term trims (pre-window lots) + basis_unknown — they aren't trading.
    # Stage 2a: canary test orders also EXCLUDED from every aggregate (listed with a canary badge only).
    active = [t for t in trips if not t.get("basis_status") and not t.get("canary")]
    canary_trips = [t for t in trips if t.get("canary")]
    lt = [t for t in trips if t.get("basis_status") == "long_term_trim"]
    unk = [t for t in trips if t.get("basis_status") == "basis_unknown"]
    wins = sum(1 for t in active if (t["net_pnl"] or 0) > 0)
    by_acct = {}
    for t in active:
        a = by_acct.setdefault(t["account"], {"count": 0, "net": 0.0})
        a["count"] += 1; a["net"] = round(a["net"] + (t["net_pnl"] or 0), 2)
    return {"round_trips": trips, "count": len(active), "wins": wins, "losses": len(active) - wins,
            "win_rate": round(wins / len(active) * 100, 1) if active else 0,
            "net_pnl": round(sum(t["net_pnl"] or 0 for t in active), 2), "by_account": by_acct,
            "long_term_trims": {"count": len(lt), "realized": round(sum(t["net_pnl"] or 0 for t in lt), 2)},
            "basis_unknown": {"count": len(unk), "symbols": sorted(set(t["symbol"] for t in unk))},
            "canary": {"count": len(canary_trips), "symbols": sorted(set(t["symbol"] for t in canary_trips)),
                       "note": "Stage 2a test orders — excluded from ALL stats/aggregates above"},
            "note": "Active trading stats exclude long-term trims (pre-window lots, e.g. V at ~$10.75 IPO basis), basis_unknown sells (no opening lot in the data — flagged, never fabricated as losses), and Stage-2a canary test orders. Real-account, separate from the paper-only live-trading gate."}


def _broker_orders_approval_status(query=None):
    """GET /api/v2/broker-orders/approval-status?intent_id= — 2FA lifecycle for the UI."""
    q = query or {}
