def _schwab_stream_book(query=None):
    """GET /api/v2/schwab/stream/book?symbol=X — latest Level-2 snapshot + book-pressure (advisory evidence)."""
    q = query or {}
    sym = (((q.get("symbol") or [None])[0] if isinstance(q.get("symbol"), list) else q.get("symbol")) or "").upper()
    if not sym:
        # all symbols, latest each
        rows = _db_query("""SELECT DISTINCT ON (symbol) symbol, venue, bid_depth, ask_depth, imbalance,
                                   best_bid, best_ask, captured_at
                            FROM schwab_stream_book ORDER BY symbol, captured_at DESC""") or []
        return {"books": [_json_clean(r) for r in rows], "advisory": True}
    row = _db_query("""SELECT symbol, venue, bid_depth, ask_depth, imbalance, best_bid, best_ask,
                              bid_levels, ask_levels, captured_at
                       FROM schwab_stream_book WHERE symbol=%s ORDER BY captured_at DESC LIMIT 1""",
                    (sym,), fetch="one")
    if not row:
        return {"status": "no_data", "symbol": sym}
    # trailing pressure: avg imbalance over the last 15 minutes
    trail = _db_query("""SELECT round(avg(imbalance),4) avg_imb, count(*) n FROM schwab_stream_book
                         WHERE symbol=%s AND captured_at > NOW()-INTERVAL '15 minutes'""", (sym,), fetch="one") or {}
    out = _json_clean(dict(row))
    out["pressure_15m"] = {"avg_imbalance": _json_clean(trail.get("avg_imb")), "samples": trail.get("n", 0),
                           "read": ("bid-heavy (buyers stacked)" if (trail.get("avg_imb") or 0) > 0.2
                                    else "ask-heavy (sellers stacked)" if (trail.get("avg_imb") or 0) < -0.2 else "balanced")}
    out["advisory"] = True
    return out


def _schwab_status(query=None):
    """GET /api/v2/system/schwab-status — Schwab read-only integration monitor: Gate-A token health,
    account-hash links, capability checks, recent sync. Read-only; never exposes token material."""
    import datetime as _dt
    toks = _db_query("""SELECT account_key, refresh_expires_at, next_reauth_due_at, access_expires_at,
                          degraded, last_error, rotation_count, updated_at
                        FROM broker_oauth_tokens WHERE broker='schwab' ORDER BY account_key""") or []
    links = {r["account_key"]: r for r in (_db_query(
        "SELECT account_key, masked_last4, verified, last_verified_at FROM schwab_account_links") or [])}
    sync = _db_query("""SELECT account_key, status, reason, position_count, total_value, wrote_holdings, created_at
                        FROM schwab_sync_history ORDER BY created_at DESC LIMIT 10""") or []
    now = _dt.datetime.now(_dt.timezone.utc)
    tokens = []
    for t in toks:
        rexp = t.get("refresh_expires_at")
        days = round((rexp - now).total_seconds() / 86400, 1) if rexp else None
        if t.get("degraded"):
            state = "degraded"
        elif days is None:
            state = "no_token"
        elif days <= 0:
            state = "expired"
        elif days <= 1:
            state = "reauth_due_day6"
        elif days <= 2:
            state = "reauth_due_day5"
        else:
            state = "ok"
        lk = links.get(t["account_key"], {})
        tokens.append({"account_key": t["account_key"], "state": state, "days_remaining": days,
                       "refresh_expires_at": _json_clean(t.get("refresh_expires_at")),
                       "next_reauth_due_at": _json_clean(t.get("next_reauth_due_at")),
                       "access_expires_at": _json_clean(t.get("access_expires_at")),
                       "degraded": t.get("degraded"), "last_error": t.get("last_error"),
                       "rotation_count": t.get("rotation_count"), "updated_at": _json_clean(t.get("updated_at")),
                       "account_linked": bool(lk.get("verified")), "masked_last4": lk.get("masked_last4")})
    caps = _db_query("""SELECT capability_name, status FROM broker_capability_checks
                        WHERE broker ILIKE '%schwab%' ORDER BY capability_name""") or []
    return {"tokens": tokens,
            "account_links": [{"account_key": k, "masked_last4": v.get("masked_last4"), "verified": v.get("verified"),
                               "last_verified_at": _json_clean(v.get("last_verified_at"))} for k, v in links.items()],
            "capabilities": [{"name": c.get("capability_name"), "status": c.get("status")} for c in caps],
            "recent_sync": [{**s, "created_at": _json_clean(s.get("created_at")),
                             "total_value": _json_clean(s.get("total_value"))} for s in sync],
            "write_locked": True, "api_write_enabled": False,
            "note": "Read-only Schwab integration. Writes fenced (NotProvenWrite); api_write_enabled=false; MANUAL_REVIEW."}


_SCHWAB_PROBE_CACHE = {"ts": 0.0, "result": None}


def _schwab_token_health(query=None):
    """GET /api/v2/brokers/schwab/token-health — is the Schwab OAuth refresh token actually usable RIGHT
    NOW? Combines the DB freshness health with a CACHED ground-truth live probe (the freshness timestamp
    can read 'valid' while Schwab has revoked the token server-side). Lets the protective-stop card warn
    're-auth needed' BEFORE an order attempt. ?probe=1 forces a fresh probe (else 5-min cache). Read-only;
    never exposes token material."""
    import time as _t
    q = query or {}
    force = str((q.get("probe") or [""])[0] if isinstance(q.get("probe"), list) else q.get("probe") or "").lower() in ("1", "true", "yes")
    import sys as _sys
    _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
    import schwab_token_manager as tm
    key = tm.canonical_token_key("schwab", "live")
    # canonical_token_key() filters out degraded rows — but a degraded token IS the login that needs
    # re-auth, so fall back to the most recent schwab token row (degraded included) for a precise message.
    if not key:
        _row = _db_query("""SELECT account_key FROM broker_oauth_tokens WHERE broker='schwab'
                            AND environment='live' AND refresh_token_enc IS NOT NULL
                            ORDER BY updated_at DESC LIMIT 1""") or []
        key = _row[0]["account_key"] if _row else None
    h = tm.health(key, "schwab", "live") if key else {"has_token": False, "degraded": True, "refresh_valid": False,
                                                       "last_error": "no token on file — manual OAuth login required"}
    # cached live probe (5 min) — only worth probing when a token exists
    probe = _SCHWAB_PROBE_CACHE["result"]
    if key and h.get("has_token") and (force or probe is None or (_t.time() - _SCHWAB_PROBE_CACHE["ts"] > 300)):
        probe = tm.live_probe(key, "schwab", "live")
        _SCHWAB_PROBE_CACHE.update(ts=_t.time(), result=probe)
        if probe.get("needs_reauth"):
            h = tm.health(key, "schwab", "live")   # re-read: live_probe may have just marked it degraded
    needs_reauth = bool((not h.get("has_token")) or h.get("degraded") or (not h.get("refresh_valid"))
                        or (probe and probe.get("needs_reauth")))
    return {"ok": not needs_reauth, "broker": "schwab", "token_key": key,
            "needs_reauth": needs_reauth, "degraded": bool(h.get("degraded")),
            "has_token": bool(h.get("has_token")), "refresh_valid": bool(h.get("refresh_valid")),
            "access_fresh": bool(h.get("access_fresh")), "days_to_reauth": h.get("days_to_reauth"),
            "refresh_expires_at": h.get("refresh_expires_at"), "next_reauth_due_at": h.get("next_reauth_due_at"),
            "last_error": h.get("last_error"),
            "live_probe": ({"probed": probe.get("probed"), "live_ok": probe.get("live_ok"),
                            "needs_reauth": probe.get("needs_reauth"), "error": probe.get("error")} if probe else None),
            "reauth_command": f"python3 scripts/schwab_token_manager.py reauth-url {key or 'schwab_taxable'}",
            "message": ("Schwab login expired/revoked — re-authenticate before placing live orders."
                        if needs_reauth else "Schwab token healthy.")}


