def _hermes_llm_auth_status(query=None):
    """GET /api/v2/hermes/llm-auth-status — read-only OAuth/auth status per LLM lane + guided login commands.
    Credentials are never entered or stored here; OAuth (Google SSO) is completed by the operator in a browser."""
    auth_out = (_hermes_run([str(HERMES_CLI), "auth", "list"], timeout=10) or "").lower()
    proxy_out = (_hermes_run([str(HERMES_CLI), "proxy", "status"], timeout=10,
                             env={"XDG_RUNTIME_DIR": f"/run/user/{os.getuid()}"}) or "").lower()
    def proxy_authed(name):
        # authed when the provider line shows 'ready' or 'logged in' (and not 'not logged in')
        for ln in proxy_out.splitlines():
            if name in ln and ("ready" in ln or ("logged in" in ln and "not logged in" not in ln)):
                return True
        return False
    # proxy server running? (xai/nous OAuth lanes need the local proxy listening on :8645)
    proxy_running = False
    try:
        import socket as _sk
        with _sk.create_connection(("127.0.0.1", 8645), timeout=2):
            proxy_running = True
    except Exception:
        proxy_running = False
    anth = bool(os.environ.get("ANTHROPIC_API_KEY")) or any(l.startswith("anthropic_api_key=") for l in
                ((PROJECT_ROOT / ".env").read_text().splitlines() if (PROJECT_ROOT / ".env").exists() else []))
    lanes = [
        {"lane": "ChatGPT (Codex)", "provider": "openai-codex", "kind": "OAuth (free, ChatGPT subscription)",
         "authed": ("openai-codex" in auth_out or "codex" in auth_out),
         "note": "authed; interactive `hermes -p dev chat` works. Headless researcher one-shot (hermes -z) "
                 "returns no final response in Hermes v0.16.0 — automated lane pending a Hermes fix.",
         "login_command": "hermes auth add openai-codex --type oauth"},
        {"lane": "Grok (xAI)", "provider": "xai-oauth", "kind": "OAuth proxy (free)",
         "authed": proxy_authed("xai"),
         "login_command": "hermes auth add xai-oauth --type oauth ; hermes proxy start --provider xai"},
        {"lane": "Nous Portal", "provider": "nous", "kind": "OAuth",
         "authed": proxy_authed("nous"), "login_command": "hermes auth add nous --type oauth"},
        {"lane": "Claude (Anthropic)", "provider": "anthropic", "kind": "API key (+credits)",
         "authed": anth, "login_command": "set ANTHROPIC_API_KEY in env + add Anthropic credits"},
        {"lane": "Local (Ollama)", "provider": "custom", "kind": "local (always free)",
         "authed": True, "login_command": "(none — local gemma3 via Ollama)"},
    ]
    # merge the capability cache (interactive vs headless automation status; reason; retest) — read-only
    cap_lanes = {}
    try:
        cap_lanes = json.loads((PROJECT_ROOT / "data" / "runtime" / "hermes_llm_capabilities.json").read_text()).get("lanes", {})
    except Exception:
        cap_lanes = {}
    prov2cap = {"openai-codex": "chatgpt", "xai-oauth": "grok", "nous": "nous", "anthropic": "claude", "custom": "local"}
    # mark which authed lanes also need the proxy up to actually work + attach capability cache
    for l in lanes:
        if l["provider"] in ("xai-oauth", "nous"):
            l["proxy_required"] = True
            l["usable"] = bool(l["authed"] and proxy_running)
        else:
            l["proxy_required"] = False
            l["usable"] = l["authed"]
        cap = cap_lanes.get(prov2cap.get(l["provider"], ""), {})
        if cap:
            l["interactive_status"] = cap.get("interactive_status")
            l["headless_status"] = cap.get("headless_status")
            l["reason_code"] = cap.get("reason_code")
            l["next_retest"] = cap.get("next_retest_not_before") or cap.get("next_retest_condition")
            if cap.get("guidance"):
                l["guidance"] = cap["guidance"]
    xai_ready = next((l["authed"] for l in lanes if l["provider"] == "xai-oauth"), False)
    return {"generated_note": "read-only LLM auth/OAuth + proxy status — no credentials entered or stored here",
            "google_sso_note": "External OAuth logins (ChatGPT/Codex, xAI, Nous) authenticate in your browser; "
                               "use Google SSO at the provider's prompt. This app never sees or stores your credentials.",
            "proxy": {"running": proxy_running, "url": "http://127.0.0.1:8645/v1",
                      "needed_by": [l["lane"] for l in lanes if l["proxy_required"] and l["authed"]],
                      "start_command": "hermes proxy start --provider xai",
                      "warning": ("xAI OAuth is ready but the proxy is DOWN — start it to use Grok."
                                  if (xai_ready and not proxy_running) else None)},
            "any_external_oauth_active": any(l["authed"] for l in lanes if l["provider"] in ("openai-codex", "xai-oauth", "nous")),
            "lanes": lanes}


