def _rec_intel_ticker(query=None):
    """GET /api/v2/rec-intel/ticker?symbol=X — full lineage for one ticker: every source that introduced it,
    earliest + most-recent source, executed flag, and any rotation edges. Read-only."""
    try:
        q = query or {}
        sym = q.get("symbol")
        sym = (sym[0] if isinstance(sym, list) else sym or "").upper().strip()
        if not sym:
            return {"ok": False, "error": "symbol required"}
        from db_adapter import _get_conn
        cur = _get_conn().cursor()
        cur.execute("""SELECT source_type, source_ref_table, source_ref_id, source_detail, rationale, account,
                         first_seen_at, last_seen_at, occurrences, executed
                       FROM rec_ticker_attribution WHERE symbol=%s ORDER BY first_seen_at""", (sym,))
        cols = ["source_type", "source_ref_table", "source_ref_id", "source_detail", "rationale", "account",
                "first_seen_at", "last_seen_at", "occurrences", "executed"]
        rows = [{c: _json_clean(v) for c, v in zip(cols, r)} for r in cur.fetchall()]
        if not rows:
            return {"ok": True, "symbol": sym, "found": False, "sources": []}
        earliest = min(rows, key=lambda r: str(r["first_seen_at"]))
        latest = max(rows, key=lambda r: str(r["last_seen_at"]))
        cur.execute("""SELECT from_symbol, to_symbol, executed, occurred_at, source_type FROM rec_rotation_links
                       WHERE from_symbol=%s OR to_symbol=%s ORDER BY occurred_at""", (sym, sym))
        rot = [{"from": r[0], "to": r[1], "executed": r[2], "at": str(r[3]), "via": r[4]} for r in cur.fetchall()]
        return {"ok": True, "symbol": sym, "found": True, "advisory_only": True,
                "source_count": len({r["source_type"] for r in rows}),
                "earliest_source": earliest["source_type"], "earliest_at": str(earliest["first_seen_at"]),
                "latest_source": latest["source_type"], "latest_at": str(latest["last_seen_at"]),
                "executed": any(r["executed"] for r in rows), "sources": rows, "rotation_links": rot}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


def _rotation_summary(force=False):
    """GET /api/v2/rotation/summary — advisory-only rotation engine output. The engine subprocess is heavy
    (~50s), so the REQUEST PATH never runs it: it serves a disk-persisted cache (data/runtime/
    rotation_summary_cache.json) that the warm cron (warm_caches.py, force=True) refreshes. Stale is served
    (flagged) rather than blocking the single-threaded server — which previously let one cold request hang
    long enough for the health-probe watchdog to kill+restart-loop the server. Never calls a broker."""
    import time as _t, json as _j, subprocess as _sp, sys
    import datetime as _dt
    _disk = PROJECT_ROOT / "data" / "runtime" / "rotation_summary_cache.json"
    _now = _t.time()
    if not force:
        # 1) in-memory fresh
        if _ROTATION_SUMMARY_CACHE["data"] and (_now - _ROTATION_SUMMARY_CACHE["ts"] < 300):
            return _ROTATION_SUMMARY_CACHE["data"]
        # 2) disk cache — serve it (fresh OR stale) without a 52s recompute in the request path
        try:
            if _disk.exists():
                _d = _j.loads(_disk.read_text())
                _age = _now - (_d.get("_cached_ts") or 0)
                _d["cached_at"] = _d.get("_cached_at")
                _d["cache_age_sec"] = round(_age)
                _d["stale"] = _age > 900
                _ROTATION_SUMMARY_CACHE.update(ts=_now - min(_age, 299), data=_d)
                return _d
        except Exception:
            pass
        # 3) no disk cache at all (first ever run) — fall through and compute once to bootstrap
    root = PROJECT_ROOT
    try:
        # Build the stop-risk map from the latest Aegis nightly thesis and hand it to the engine so
        # trim_score reflects deterministic stop deterioration (triggered/danger/warning), not just
        # concentration/valuation. Best-effort; engine ignores --stops if the file is absent/empty.
        _stops_arg = []
        try:
            from db_adapter import _get_conn as _gcs
            _cs = _gcs().cursor()
            _cs.execute("""SELECT symbol, thesis_status FROM aegis_portfolio_briefs
                           WHERE run_id=(SELECT run_id FROM aegis_portfolio_briefs ORDER BY observed_at DESC LIMIT 1)
                             AND thesis_status IS NOT NULL""")
            _SEVMAP = {"triggered": 4, "danger": 4, "broken": 4, "warning": 3, "weakening": 2}
            _stops = {}
            for _s, _st in _cs.fetchall():
                _stl = (_st or "").lower()
                if _stl in _SEVMAP:
                    _stops[(_s or "").upper()] = {"status": _stl, "severity": _SEVMAP[_stl]}
            if _stops:
                _sf = root / "data" / "runtime" / "rotation_stops_latest.json"
                _sf.write_text(_j.dumps(_stops))
                _stops_arg = ["--stops", str(_sf)]
        except Exception:
            _stops_arg = []
        r = _sp.run([sys.executable, str(root / "scripts" / "rotation_intelligence_engine.py"),
                     "--input", str(root / "data" / "portfolios" / "state" / "holdings.json"),
                     "--cards", str(root / "data" / "runtime" / "symbol_cards_latest.json"),
                     "--min-pair-score", "35", *_stops_arg],
                    capture_output=True, text=True, timeout=90, cwd=str(root))
        eng = _j.loads(r.stdout)
        dq = eng.get("data_quality", {}) or {}
        # Count held tickers with no analyst upside number (parallel to "missing sector"). ETFs/funds have
        # no analyst coverage by nature, so they count too. Best-effort; None if files can't be read.
        missing_analyst, _held, _cmap = None, set(), {}
        try:
            import re as _re
            _hold = _j.loads((root / "data" / "portfolios" / "state" / "holdings.json").read_text()).get("holdings", [])
            _cf = _j.loads((root / "data" / "runtime" / "symbol_cards_latest.json").read_text())
            _cmap = (_cf.get("data") or {}).get("cards") or _cf.get("cards") or {}
            _held = {(h.get("symbol") or "").upper() for h in _hold
                     if h.get("symbol") and not h.get("is_cash")
                     and _re.fullmatch(r"[A-Z]{1,5}", (h.get("symbol") or "").upper())}
            missing_analyst = sum(1 for t in _held if (_cmap.get(t) or {}).get("analyst", {}).get("upside_pct") is None)
        except Exception:
            missing_analyst = None
        # Clean the per-symbol candidates: drop worthless/delisted rows (≈$0 value, e.g. delisted CUSIPs),
        # and backfill a missing sector from symbol_profiles (same source as the unified card layer).
        cands = [c for c in (eng.get("top_candidates", []) or []) if float(c.get("current_value") or 0) >= 1]
        _need = [(c.get("symbol") or "").upper() for c in cands if not c.get("sector")]
        if _need:
            try:
                from db_adapter import _get_conn as _gc
                _cur = _gc().cursor()
                _cur.execute("SELECT upper(symbol), sector FROM symbol_profiles WHERE upper(symbol) = ANY(%s) AND sector IS NOT NULL", (_need,))
                _secmap = {row[0]: row[1] for row in _cur.fetchall()}
                for c in cands:
                    if not c.get("sector"):
                        c["sector"] = _secmap.get((c.get("symbol") or "").upper())
            except Exception:
                pass
        # ── Holdings DEGRADATION signals from the Aegis nightly briefs (thesis health) — advisory. Drives the
        # "what to rotate OUT" side from REAL deterioration (thesis weakening/danger/triggered, technical drift,
        # near 52wk-low), not just concentration. Read-only DB; no broker, no order. ──
        import re as _re0
        _degrade = {}
        try:
            from db_adapter import _get_conn as _gc4
            _c4 = _gc4().cursor()
            _SEV = {"triggered": 4, "danger": 4, "warning": 3, "weakening": 2, "broken": 4}
            # signal provenance — accuracy matters: triggered/danger/warning come from DETERMINISTIC stop-
            # distance math (aegis_surveillance, conf 0.90-0.95); weakening/broken come from the local LLM
            # (gemma3 thesis read, conf ~0.55). Label each so the operator knows hard vs soft.
            _STOP = {"triggered", "danger", "warning"}
            _c4.execute("""SELECT symbol, thesis_status, escalation_reason, technical_drift, what_changed, needs_steph_review
                           FROM aegis_portfolio_briefs
                           WHERE run_id=(SELECT run_id FROM aegis_portfolio_briefs ORDER BY observed_at DESC LIMIT 1)
                             AND thesis_status IS NOT NULL""")
            for _s, _st, _er, _td, _wc, _ns in _c4.fetchall():
                _stl = (_st or "").lower()
                if _stl in _SEV:
                    _src = "stop_distance" if _stl in _STOP else "llm_gemma3"
                    _degrade[(_s or "").upper()] = {
                        "thesis_status": _stl, "severity": _SEV[_stl],
                        "signal_source": _src,
                        "deterministic": _src == "stop_distance",
                        "escalation_reason": _er or None, "technical_drift": _td or None,
                        "what_changed": (_wc or "")[:160] or None, "needs_review": bool(_ns)}
        except Exception:
            _degrade = {}
        # supplementary (separate try so a bad row can't wipe the thesis map): near 52-wk low + poor analyst
        # recom from the nightly snapshot. analyst_recom is a TEXT column → parse defensively.
        def _f(_v):
            try:
                return float(_v)
            except (TypeError, ValueError):
                return None
        try:
            _c4.execute("""SELECT symbol, analyst_recom, pct_from_52wk_high
                           FROM aegis_symbol_snapshot_nightly
                           WHERE run_id=(SELECT run_id FROM aegis_symbol_snapshot_nightly ORDER BY observed_at DESC LIMIT 1)""")
            for _s, _ar, _p52 in _c4.fetchall():
                _su = (_s or "").upper()
                _flags = {}
                _p52f, _arf = _f(_p52), _f(_ar)
                if _p52f is not None and _p52f <= -40:
                    _flags["near_52wk_low_pct"] = round(_p52f, 1)
                if _arf is not None and _arf >= 3.0:  # finviz scale: 1=strong buy … 5=strong sell
                    _flags["analyst_recom"] = round(_arf, 2)
                if _flags:
                    _e = _degrade.get(_su) or {"thesis_status": "weakening", "severity": 1,
                                               "signal_source": "snapshot_data", "deterministic": True,
                                               "escalation_reason": None, "technical_drift": None,
                                               "what_changed": None, "needs_review": False}
                    _e.update(_flags)
                    _degrade[_su] = _e
        except Exception:
            pass
        # attach degradation to each held review candidate
        for _c in cands:
            _dg = _degrade.get((_c.get("symbol") or "").upper())
            if _dg:
                _c["degradation"] = _dg
        # Research rotate-in candidates (NOT held) + advisory rebalance ideas. Advisory only — these are
        # NOT model-supported signals; they suggest WHAT to review (no dollar amounts, no broker action).
        research_candidates, research_ideas = [], []
        try:
            import re as _re
            from db_adapter import _get_conn as _gc2
            _c2 = _gc2().cursor()
            # Join the CIO holistic view (watchlist_final_synthesis.recommendation) + analyst coverage depth
            # so rotate-in candidates RESPECT the system's own buy/avoid decision and flag thin coverage —
            # a name the CIO says AVOID must not be surfaced as a buy, and a +79% upside from 1 analyst is not
            # the same as from 9.
            _c2.execute("""SELECT w.symbol, w.hermes_rank, w.score, p.sector, p.instrument_type,
                                  fs.recommendation AS cio_view, an.nop AS analyst_opinions
                           FROM watchlist_items w
                           LEFT JOIN symbol_profiles p ON upper(p.symbol)=upper(w.symbol)
                           LEFT JOIN LATERAL (SELECT recommendation FROM watchlist_final_synthesis f
                                              WHERE upper(f.symbol)=upper(w.symbol) ORDER BY created_at DESC LIMIT 1) fs ON true
                           LEFT JOIN LATERAL (SELECT number_of_analyst_opinions nop FROM yahoo_analyst_targets_history y
                                              WHERE upper(y.symbol)=upper(w.symbol) ORDER BY created_at DESC LIMIT 1) an ON true
                           WHERE w.status IN ('active','researched') AND w.symbol ~ '^[A-Z]{1,5}$'
                           ORDER BY w.hermes_rank ASC NULLS LAST LIMIT 120""")
            _CIO_BUY = {"BUY", "ADD", "ADD_ON_PULLBACK"}
            _CIO_AVOID = {"AVOID", "IGNORE", "REBALANCE_TRIM"}
            _seen = set()
            for _sym, _rank, _score, _sec, _itype, _cio, _nop in _c2.fetchall():
                _su = (_sym or "").upper()
                if _su in _held or _su in _seen:
                    continue
                _seen.add(_su)
                _card = _cmap.get(_su) or {}
                _an = _card.get("analyst") or {}
                _cv = (_cio or "").upper()
                _nopi = int(_nop) if _nop is not None else None
                research_candidates.append({
                    "symbol": _sym, "hermes_rank": _rank,
                    "score": float(_score) if _score is not None else None,
                    "sector": _sec or _card.get("sector"),
                    "instrument_type": _itype or "stock",
                    "analyst_rating": _an.get("rating"), "analyst_upside_pct": _an.get("upside_pct"),
                    "analyst_opinions": _nopi,
                    "thin_coverage": (_nopi is None or _nopi < 3) and _itype not in ("etf", "fund", "inverse_etf"),
                    "cio_view": _cv or None,
                    "cio_endorsed": _cv in _CIO_BUY,
                    "cio_avoid": _cv in _CIO_AVOID,
                    "description": (_card.get("description") or "")[:140] or None,
                })
                if len(research_candidates) >= 18:
                    break
            # advisory pairs: most rotate-worthy held → top research add (no amounts, ROTATE_REVIEW).
            # trim source must be a real ticker (exclude 401k fund codes / proxy codes — they can't rotate
            # into an individual research name). Rotate-OUT pool prioritizes REAL deterioration (Aegis thesis
            # weakening/danger/triggered) FIRST, then concentration-trim names.
            _real = lambda c: bool(_re.fullmatch(r"[A-Z]{1,5}", (c.get("symbol") or "").upper())
                                   and "401k" not in (c.get("account_type") or "").lower())
            _deg_trims = sorted([c for c in cands if _real(c) and c.get("degradation")],
                                key=lambda c: (-(c.get("degradation") or {}).get("severity", 0),
                                               -(c.get("trim_score") or 0)))
            _conc_trims = sorted([c for c in cands if _real(c) and not c.get("degradation")
                                  and (c.get("trim_score") or 0) >= 9],
                                 key=lambda c: -(c.get("trim_score") or 0))
            _trims = (_deg_trims + _conc_trims)[:4]
            # Rotate-in targets must be names the CIO would actually BUY (not AVOID/IGNORE) — the CIO endorses
            # DIFFERENT names than raw momentum, so search ALL non-held watchlist names for CIO-endorsed ones
            # (not just the top-hermes_rank display window), preferring real analyst coverage. If none qualify,
            # we suggest NO rotate-in (honest) rather than an avoided/hype name.
            _endorsed = []
            try:
                _c3 = _gc2().cursor()
                _c3.execute("""SELECT w.symbol, w.hermes_rank, p.sector, an.nop, fs.recommendation
                               FROM watchlist_items w
                               LEFT JOIN symbol_profiles p ON upper(p.symbol)=upper(w.symbol)
                               JOIN LATERAL (SELECT recommendation FROM watchlist_final_synthesis f
                                             WHERE upper(f.symbol)=upper(w.symbol) ORDER BY created_at DESC LIMIT 1) fs ON true
                               LEFT JOIN LATERAL (SELECT number_of_analyst_opinions nop FROM yahoo_analyst_targets_history y
                                                  WHERE upper(y.symbol)=upper(w.symbol) ORDER BY created_at DESC LIMIT 1) an ON true
                               WHERE w.status IN ('active','researched') AND w.symbol ~ '^[A-Z]{1,5}$'
                                 AND fs.recommendation IN ('BUY','ADD','ADD_ON_PULLBACK')
                               ORDER BY (an.nop IS NULL OR an.nop < 3), w.hermes_rank ASC NULLS LAST LIMIT 8""")
                for _es, _er, _esec, _enop, _ecio in _c3.fetchall():
                    _eu = (_es or "").upper()
                    if _eu in _held:
                        continue
                    _ecard = _cmap.get(_eu) or {}
                    _ean = _ecard.get("analyst") or {}
                    _ec = next((a for a in research_candidates if a.get("symbol") == _es), None) or {
                        "symbol": _es, "hermes_rank": _er, "sector": _esec or _ecard.get("sector"),
                        "instrument_type": _ecard.get("instrument_type") or "stock",
                        "analyst_upside_pct": _ean.get("upside_pct"), "analyst_rating": _ean.get("rating"),
                        "analyst_opinions": int(_enop) if _enop is not None else None,
                        "cio_endorsed": True, "cio_view": (_ecio or "").upper() or None, "cio_avoid": False,
                        "thin_coverage": _enop is None or int(_enop) < 3,
                        "description": (_ecard.get("description") or "")[:140] or None}
                    if _ec not in research_candidates:
                        research_candidates.append(_ec)  # ensure endorsed targets are visible too
                    _endorsed.append(_ec)
            except Exception:
                _endorsed = [a for a in research_candidates if a.get("cio_endorsed")]
            for _tt in _trims:
                for _aa in _endorsed[:2]:
                    _up = _aa.get("analyst_upside_pct")
                    _conc = (_tt.get("evidence") or {}).get("concentration_pct")
                    _dg = _tt.get("degradation") or {}
                    _why = (f"thesis {_dg['thesis_status']}"
                            f"{' — '+_dg['escalation_reason'] if _dg.get('escalation_reason') else ''}"
                            if _dg else f"trim signal {_tt.get('trim_score')}"
                            f"{', conc '+str(_conc)+'%' if _conc is not None else ''}")
                    research_ideas.append({
                        "action_class": "ROTATE_REVIEW",
                        "from_symbol": _tt.get("symbol"), "to_symbol": _aa.get("symbol"),
                        "from_account": _tt.get("account_type"), "score": round(float(_tt.get("trim_score") or 0), 1),
                        "review_amount": None,
                        "from_degradation": _dg or None,
                        "to_cio_view": _aa.get("cio_view"), "to_analyst_opinions": _aa.get("analyst_opinions"),
                        "rationale": (f"Advisory: review rotating from {_tt.get('symbol')} "
                                      f"({_tt.get('sector') or '?'}, {_why}) into research "
                                      f"candidate {_aa.get('symbol')} (Hermes #{_aa.get('hermes_rank')}, "
                                      f"CIO {_aa.get('cio_view') or 'n/a'}"
                                      f"{', '+str(_up)+'% upside from '+str(_aa.get('analyst_opinions'))+' analysts' if _up is not None else ''}). "
                                      "Not a model-supported signal — confirm sizing, tax, and account fit separately."),
                    })
                    if len(research_ideas) >= 6:
                        break
                if len(research_ideas) >= 6:
                    break
        except Exception:
            research_candidates, research_ideas = [], []
        # Sleeve overweight/underweight from the portfolio look-through vs operator comfort targets (advisory).
        # Overweight excess seeds an advisory trim RANGE (operator-confirmed, never auto-placed).
        sector_overweights, sector_underweights, pf_total = [], [], 0.0
        _band = {"low_frac": 0.05, "high_frac": 0.15}
        try:
            _lt = _j.loads((root / "data" / "portfolios" / "state" / "lookthrough_themes.json").read_text())
            pf_total = float(_lt.get("portfolio_total") or 0)
            _tg = _j.loads((root / "config" / "rotation_sector_targets.json").read_text())
            _dflt = float(_tg.get("default_comfort_pct") or 18)
            _band = _tg.get("trim_band") or _band
            _tmap = _tg.get("themes") or {}
            for _name, _tv in (_lt.get("themes") or {}).items():
                _pct = float(_tv.get("pct") or 0)
                _cfg = _tmap.get(_name) or {}
                _target = float(_cfg.get("target", _dflt))
                _floor = float(_cfg.get("floor", 0))
                if _pct - _target > 1.0:
                    _ex = round(_pct - _target, 2)
                    sector_overweights.append({
                        "theme": _name, "pct": round(_pct, 2), "target": _target,
                        "excess_pct": _ex, "excess_dollars": round(_ex / 100 * pf_total),
                        "top_holdings": [s.get("symbol") for s in (_tv.get("by_stock") or [])[:5]]})
                elif _floor and _pct < _floor - 0.5:
                    sector_underweights.append({"theme": _name, "pct": round(_pct, 2), "floor": _floor,
                                                "gap_pct": round(_floor - _pct, 2)})
            sector_overweights.sort(key=lambda x: -x["excess_dollars"])
        except Exception:
            pass
        # advisory trim RANGE per rebalance idea (5-15% of the trim position, operator-confirmed)
        _lo_f, _hi_f = float(_band.get("low_frac", 0.05)), float(_band.get("high_frac", 0.15))
        for _idea in research_ideas:
            _fv = next((float(c.get("current_value") or 0) for c in cands if c.get("symbol") == _idea.get("from_symbol")), 0.0)
            if _fv:
                # Context-aware review size: a 5-15% trim only makes sense for a concentration/valuation
                # flag. When the rotate-out reason is a BROKEN STOP, the action is reduce/exit, not a token
                # trim — so size it to a meaningful reduction (up to the full position), with a plain basis.
                _dg = _idea.get("from_degradation") or {}
                _sev = _dg.get("severity") or 0
                if _sev >= 3:  # triggered / danger / warning — stop hit
                    _idea["review_amount_range"] = {"low": round(_fv * 0.5), "high": round(_fv),
                        "basis": "stop hit — review reducing or closing this position (not a 5-15% trim)",
                        "action": "reduce_or_close"}
                elif _dg:  # weakening — thesis softening
                    _idea["review_amount_range"] = {"low": round(_fv * 0.25), "high": round(_fv * 0.5),
                        "basis": "thesis weakening — review reducing this position", "action": "reduce"}
                else:  # concentration / valuation trim
                    _idea["review_amount_range"] = {"low": round(_fv * _lo_f), "high": round(_fv * _hi_f),
                        "basis": "5-15% of the position — advisory, operator-confirmed, not auto-placed",
                        "action": "trim"}
        # ── Live prices + advisory review QUANTITIES (shares). Read-only: latest market_quotes (DB) + the
        # holdings snapshot. No broker, no order, no live HTTP from this request. Quantities are review
        # RANGES derived from the advisory $ range — operator confirms; nothing is sized or placed. ──
        import re as _re3
        _price, _hmap = {}, {}
        try:
            _hold_rows = _j.loads((root / "data" / "portfolios" / "state" / "holdings.json").read_text()).get("holdings", [])
            _syms = set()
            for _c in cands:
                _syms.add((_c.get("symbol") or "").upper())
            for _rc in research_candidates:
                _syms.add((_rc.get("symbol") or "").upper())
            for _id in research_ideas:
                _syms.add((_id.get("from_symbol") or "").upper())
                _syms.add((_id.get("to_symbol") or "").upper())
            _syms = [s for s in _syms if _re3.fullmatch(r"[A-Z]{1,5}", s or "")]
            if _syms:
                from db_adapter import _get_conn as _gc3
                _c3 = _gc3().cursor()
                _c3.execute("""SELECT DISTINCT ON (symbol) symbol, price, day_change_pct
                               FROM market_quotes WHERE symbol = ANY(%s)
                               ORDER BY symbol, fetched_at DESC""", (_syms,))
                for _s, _p, _dc in _c3.fetchall():
                    if _p is not None:
                        _price[_s.upper()] = {"price": round(float(_p), 2),
                                              "day_change_pct": round(float(_dc), 2) if _dc is not None else None}
            # holdings fallback (covers ETFs/funds market_quotes may lack) + held share counts
            for _h in _hold_rows:
                _hs = (_h.get("symbol") or "").upper()
                if _hs and not _h.get("is_cash") and float(_h.get("price") or 0) > 0:
                    _hmap.setdefault(_hs, _h)
                    _price.setdefault(_hs, {"price": round(float(_h.get("price")), 2),
                                            "day_change_pct": _h.get("day_change_pct")})
        except Exception:
            _price, _hmap = {}, {}

        def _shares_range(_al, _ah, _pp):
            if not _pp or _pp <= 0:
                return None
            return {"low": int(float(_al) // _pp), "high": max(1, round(float(_ah) / _pp))}

        # Review Candidates: live price, day change, est. share count
        for _c in cands:
            _pe = _price.get((_c.get("symbol") or "").upper())
            if _pe:
                _c["price"] = _pe["price"]
                _c["day_change_pct"] = _pe.get("day_change_pct")
                _cv = float(_c.get("current_value") or 0)
                if _cv and _pe["price"]:
                    _c["est_shares"] = round(_cv / _pe["price"], 2)
        # Research rotate-in candidates: live price + day change
        for _rc in research_candidates:
            _pe = _price.get((_rc.get("symbol") or "").upper())
            if _pe:
                _rc["price"] = _pe["price"]
                _rc["day_change_pct"] = _pe.get("day_change_pct")
        # Rebalance ideas: from/to price + advisory sell/buy SHARE ranges (review only)
        for _idea in research_ideas:
            _fp = _price.get((_idea.get("from_symbol") or "").upper())
            _tp = _price.get((_idea.get("to_symbol") or "").upper())
            _rng = _idea.get("review_amount_range") or {}
            if _fp:
                _idea["from_price"] = _fp["price"]
                _fh = _hmap.get((_idea.get("from_symbol") or "").upper())
                if _fh:
                    _idea["from_shares_held"] = _fh.get("shares")
                if _rng.get("low") is not None:
                    _idea["sell_shares_range"] = _shares_range(_rng["low"], _rng["high"], _fp["price"])
            if _tp:
                _idea["to_price"] = _tp["price"]
                if _rng.get("low") is not None:
                    _idea["buy_shares_range"] = _shares_range(_rng["low"], _rng["high"], _tp["price"])
        # Deteriorating holdings — held names Aegis flags as weakening/warning/danger/triggered. Advisory
        # rotate-OUT review list (sorted by severity then value); also fed to the weekly digest/alert.
        degraded_holdings = []
        for _c in cands:
            _dg = _c.get("degradation")
            if not _dg:
                continue
            degraded_holdings.append({
                "symbol": _c.get("symbol"), "thesis_status": _dg.get("thesis_status"),
                "severity": _dg.get("severity"),
                "signal_source": _dg.get("signal_source"), "deterministic": _dg.get("deterministic"),
                "escalation_reason": _dg.get("escalation_reason"),
                "technical_drift": _dg.get("technical_drift"), "what_changed": _dg.get("what_changed"),
                "near_52wk_low_pct": _dg.get("near_52wk_low_pct"), "analyst_recom": _dg.get("analyst_recom"),
                "needs_review": _dg.get("needs_review"),
                "sector": _c.get("sector"), "account_type": _c.get("account_type") or _c.get("account_key"),
                "current_value": _c.get("current_value"), "price": _c.get("price"),
                "day_change_pct": _c.get("day_change_pct"), "est_shares": _c.get("est_shares"),
            })
        degraded_holdings.sort(key=lambda x: (-(x.get("severity") or 0), -float(x.get("current_value") or 0)))
        # ── ETF / Fund sleeve instruments (long for UNDERWEIGHT sleeves, inverse/short hedge for OVERWEIGHT).
        # Makes ETFs first-class rotate-in / hedge candidates, not just individual stocks. Advisory only. ──
        etf_candidates = []
        try:
            _uni = _j.loads((root / "config" / "etf_fund_universe.json").read_text()).get("instruments", [])
            _long_by, _short_by = {}, {}
            for _it in _uni:
                (_short_by if _it.get("direction") == "short" else _long_by).setdefault(_it.get("sleeve"), []).append(_it)
            _eprice = {}
            try:
                from db_adapter import _get_conn as _gce
                _ce = _gce().cursor()
                _ce.execute("""SELECT DISTINCT ON (symbol) symbol, price, day_change_pct FROM market_quotes
                               WHERE symbol = ANY(%s) ORDER BY symbol, fetched_at DESC""",
                            ([i["symbol"] for i in _uni],))
                for _s, _p, _dc in _ce.fetchall():
                    _eprice[_s.upper()] = {"price": round(float(_p), 2) if _p is not None else None,
                                           "day_change_pct": round(float(_dc), 2) if _dc is not None else None}
            except Exception:
                pass
            _heldset = {(h.get("symbol") or "").upper() for h in _hold_rows} if "_hold_rows" in dir() else set()
            for _uw in sector_underweights:
                for _it in (_long_by.get(_uw["theme"]) or [])[:2]:
                    _pe = _eprice.get(_it["symbol"].upper(), {})
                    etf_candidates.append({"symbol": _it["symbol"], "name": _it.get("name"),
                        "instrument_type": _it["type"], "direction": "long", "sleeve": _uw["theme"],
                        "held": _it["symbol"].upper() in _heldset,
                        "rationale": f"Underweight {_uw['theme']} ({_uw['pct']}% vs {_uw.get('floor')}% floor) — "
                                     f"{_it['symbol']} ({_it.get('name')}) is direct LONG exposure to the sleeve.",
                        "price": _pe.get("price"), "day_change_pct": _pe.get("day_change_pct")})
            for _ow in sector_overweights[:3]:
                for _it in (_short_by.get(_ow["theme"]) or [])[:1]:
                    _pe = _eprice.get(_it["symbol"].upper(), {})
                    etf_candidates.append({"symbol": _it["symbol"], "name": _it.get("name"),
                        "instrument_type": _it["type"], "direction": "short", "sleeve": _ow["theme"],
                        "held": False, "leverage": _it.get("leverage"),
                        "rationale": f"Overweight {_ow['theme']} (+{_ow.get('excess_pct')}% over target ≈ "
                                     f"${_ow.get('excess_dollars'):,}) — {_it['symbol']} ({_it.get('name')}) is an "
                                     f"advisory INVERSE/SHORT hedge. Review only; not a model signal.",
                        "price": _pe.get("price"), "day_change_pct": _pe.get("day_change_pct")})
        except Exception:
            etf_candidates = []
        # ── Entry-plan attach (operator 2026-06-18: "rotation buys are blind — no target entry prices").
        # Latest watchlist_entry_plans row per BUY-SIDE symbol → advisory entry zone/limit/stop/target/R:R/
        # urgency/tag. Replaces the blind live price with a disciplined target entry. Advisory only. ──
        try:
            _buy_syms = set()
            for _rc in research_candidates:
                _buy_syms.add((_rc.get("symbol") or "").upper())
            for _idea in research_ideas:
                _buy_syms.add((_idea.get("to_symbol") or "").upper())
            for _e in etf_candidates:
                if _e.get("direction") == "long":
                    _buy_syms.add((_e.get("symbol") or "").upper())
            _buy_syms.discard("")
            _plans = {}
            if _buy_syms:
                from db_adapter import _get_conn as _gcp
                _cp = _gcp().cursor()
                _cp.execute("""SELECT DISTINCT ON (symbol) symbol, setup_type, entry_zone_low, entry_zone_high,
                                  limit_price, stop_price, target_price, risk_reward, urgency, proposal_tag, created_at
                               FROM watchlist_entry_plans WHERE upper(symbol) = ANY(%s)
                               ORDER BY symbol, created_at DESC""", (list(_buy_syms),))
                for _r in _cp.fetchall():
                    _plans[(_r[0] or "").upper()] = {
                        "setup_type": _r[1],
                        "entry_zone_low": float(_r[2]) if _r[2] is not None else None,
                        "entry_zone_high": float(_r[3]) if _r[3] is not None else None,
                        "limit_price": float(_r[4]) if _r[4] is not None else None,
                        "stop_price": float(_r[5]) if _r[5] is not None else None,
                        "target_price": float(_r[6]) if _r[6] is not None else None,
                        "risk_reward": float(_r[7]) if _r[7] is not None else None,
                        "urgency": _r[8], "proposal_tag": _r[9],
                        "planned_at": _r[10].isoformat() if _r[10] else None}
            for _o in research_candidates:
                _o["entry_plan"] = _plans.get((_o.get("symbol") or "").upper())
            for _o in research_ideas:
                _o["entry_plan"] = _plans.get((_o.get("to_symbol") or "").upper())
            for _o in etf_candidates:
                if _o.get("direction") == "long":
                    _o["entry_plan"] = _plans.get((_o.get("symbol") or "").upper())
        except Exception:
            pass
        # ── FEE-DRIVEN rotation ideas (operator 2026-06-21: "should be autonomous in reports and rotation") ──
        # Turn fee-efficiency findings into advisory rotate-out→cheaper-alternative pairs (e.g. FCNTX→SCHD).
        # Review-only, never an order; the same advisory footing as the rest of the engine. Cheap (no subprocess).
        _fee_swaps, _fee_total = [], None
        try:
            import sys as _sysf
            _sysf.path.insert(0, str(PROJECT_ROOT / "scripts"))
            import fee_efficiency_analyzer as _fae
            _fee = _fae.analyze()
            _fee_total = _fee.get("total_annual_fee_usd")
            for _ff in (_fee.get("findings") or []):
                _alt = (_ff.get("cheaper_alternatives_beating_it") or [None])[0]
                _fee_swaps.append({
                    "kind": "fee_swap", "review_only": True,
                    "out_symbol": _ff.get("symbol"), "account": _ff.get("account"),
                    "in_symbol": (_alt.get("symbol") if _alt else None),
                    "instrument_type": _ff.get("instrument_type"), "market_value": _ff.get("market_value"),
                    "expense_ratio_pct": _ff.get("expense_ratio_pct"), "annual_fee_usd": _ff.get("annual_fee_usd"),
                    "excess_fee_vs_index_usd": _ff.get("excess_fee_vs_index_usd"),
                    "ytd_return_pct": _ff.get("ytd_return_pct"),
                    "alt_expense_ratio_pct": (_alt.get("expense_ratio_pct") if _alt else None),
                    "alt_ytd_return_pct": (_alt.get("ytd_return_pct") if _alt else None),
                    "tax_free_to_switch": _ff.get("tax_free_to_switch"), "severity": _ff.get("severity"),
                    "recommendation": _ff.get("recommendation"),
                })
            _fee_swaps.sort(key=lambda x: (x.get("excess_fee_vs_index_usd") or 0), reverse=True)
        except Exception:
            _fee_swaps, _fee_total = [], None
        out = {
            "ok": bool(eng.get("ok", True)), "advisory_only": True,
            "portfolio_total": round(pf_total),
            "fee_swaps": _fee_swaps,
            "total_annual_fee_usd": _fee_total,
            "sector_overweights": sector_overweights,
            "sector_underweights": sector_underweights,
            "degraded_holdings": degraded_holdings,
            "etf_candidates": etf_candidates,
            "summary": eng.get("summary", {}) or {},
            "data_quality": dq,
            "missing_sector": max(0, int(dq.get("holding_rows", 0) or 0) - int(dq.get("rows_with_sector", 0) or 0)),
            "missing_analyst_upside": missing_analyst,
            "top_rotation_ideas": eng.get("top_rotation_ideas", []) or [],
            # real from→to rotation pairs only (engine currently produces none → empty-state in UI)
            "top_pairs": eng.get("top_pairs", []) or [],
            # per-symbol review/watch candidates (symbol + recommendation + add/trim scores), NOT pairs
            "top_candidates": cands,
            # research rotate-in (not held) — advisory rebalance suggestions, no model-supported signal
            "research_candidates": research_candidates,
            "research_rotation_ideas": research_ideas,
            "generated_at": eng.get("generated_at"),
        }
        out["_cached_ts"] = _t.time()
        out["_cached_at"] = _dt.datetime.now().isoformat(timespec="seconds")
        out["cached_at"] = out["_cached_at"]
        out["cache_age_sec"] = 0
        out["stale"] = False
        _ROTATION_SUMMARY_CACHE.update(ts=_t.time(), data=out)
        try:
            _disk.write_text(_j.dumps(out, default=str))
        except Exception:
            pass
        return out
    except Exception as e:
        return {"ok": False, "advisory_only": True, "error": str(e)[:200],
                "summary": {}, "data_quality": {}, "top_rotation_ideas": [], "top_pairs": []}


def _small_cap_rotation_bridge_status():
    """GET /api/v2/rotation/small-cap-bridge — autopilot state + latest screening audit."""
    import json as _j
    from pathlib import Path as _P
    out = {"ok": True, "advisory_only": True, "autonomous": True}
    for key, path in (
        ("autopilot", PROJECT_ROOT / "data" / "runtime" / "rotation_autopilot_latest.json"),
        ("state", PROJECT_ROOT / "data" / "runtime" / "rotation_autopilot_state.json"),
        ("bridge", PROJECT_ROOT / "data" / "runtime" / "small_cap_rotation_bridge_latest.json"),
    ):
        try:
            if path.exists():
                out[key] = _j.loads(path.read_text())
        except Exception:
            pass
    if out.get("bridge") or out.get("autopilot"):
        return out
    try:
        import market_rotation_signals as mrs
        rot = mrs.detect_small_cap_rotation()
        out["rotation"] = rot
        out["coverage"] = mrs.coverage_gap(rot)
        out["note"] = "autopilot has not run a bridge cycle yet"
        return out
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}


