        if base_path == "/api/v2/broker-proposals/route":
            # STEP 1 — Schwab armed: operator trade review applied, OTOCO bracket + per-order 2FA.
            # Ungated: preview spec only. Fidelity → record-only. Audited via queue_router.
            try:
                b = body or {}
                pid = int(b.get("proposal_id"))
                actor = str(b.get("operator") or "operator")[:60]
                trade = {}
                for k in ("account", "shares", "entry", "stop", "target"):
                    if b.get(k) is not None:
                        trade[k] = b.get(k)
                if trade:
                    trade["operator"] = actor
                import queue_router as _qr
                res = _qr.route_proposal(pid, actor=actor, trade=trade or None)
                http = 200 if (res.get("ok") or res.get("gated") or res.get("mode") == "awaiting_approval") else 400
                return http, {"ok": bool(res.get("ok")), "data": res}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)[:160]}

        if base_path == "/api/v2/broker-proposals/route/confirm":
            # STEP 2 — CONFIRM 2FA then submit Schwab OTOCO bracket. Spec rebuilt server-side from intent.
            try:
                b = body or {}
                intent_id = str(b.get("intent_id") or "").strip()
                channel = str(b.get("channel") or "").strip().lower()
                code = b.get("code")
                if not intent_id or channel not in ("web", "telegram"):
                    return 400, {"ok": False, "error": "intent_id and channel ('web' or 'telegram') required"}
                from brokers import approval_service, broker_entry_pilot as _bep
                intent = _bep.load_intent(intent_id)
                if intent is None:
                    return 404, {"ok": False, "error": "no queue-entry intent for that id (expired?)"}
                cr = approval_service.confirm(intent_id, channel, str(code) if code is not None else None)
                if not cr.get("ok"):
                    return 200, {"ok": False, "stage": "confirm", "error": cr.get("reason")}
                if not cr.get("fully_approved"):
                    return 200, {"ok": True, "stage": "confirm", "fully_approved": False,
                                 "note": "channel confirmed; waiting on the rest"}
                from brokers import intent_submit_router as _isr
                sub = _isr.submit_fully_approved(intent_id)
                if sub.get("stage") == "submit" and not sub.get("ok"):
                    return 200, {"ok": False, "stage": "submit", "error": sub.get("error"),
                                 "result": sub.get("result")}
                res = sub.get("result") or {}
                inner = res.get("result") if isinstance(res.get("result"), dict) else res
                return 200, {"ok": bool(sub.get("ok")), "stage": "submit",
                             "result": res, "broker_order_id": sub.get("broker_order_id") or inner.get("broker_order_id"),
                             "status": sub.get("status") or inner.get("status"),
                             "account": sub.get("account"), "proposal_id": sub.get("proposal_id") or res.get("proposal_id"),
                             "summary": _bep.order_summary(intent)}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)[:200]}

        if base_path == "/api/v2/paper-trades/scale":
            # Mid-trade scale-IN / scale-OUT of an OPEN position (operator 2026-06-19). Broker-routed via
            # paper_scale: alpaca_paper = live paper (delta order + stop reconcile); schwab_* = gated 2FA
            # (prepared, places NOTHING); fidelity_* = record-only manual trade. confirm=false returns a
            # PREVIEW (what would happen); confirm=true executes. Both directions require confirm (operator
            # decision). Scale-in capped at percent-of-equity headroom. Audited in queue_decision_audit.
            try:
                b = body or {}
                acct = str(b.get("account") or "").strip()
                sym = str(b.get("symbol") or "").strip().upper()
                delta = b.get("delta_shares")
                confirm = bool(b.get("confirm"))
                actor = str(b.get("operator") or "operator")[:60]
                if not (acct and sym and delta is not None):
                    return 400, {"ok": False, "error": "account, symbol and delta_shares are required"}
                try:
                    delta = int(delta)
                except (TypeError, ValueError):
                    return 400, {"ok": False, "error": "delta_shares must be an integer"}
                import paper_scale as _ps
                res = _ps.scale_position(acct, sym, delta, actor=actor, channel="web", confirm=confirm)
                # preview / gated are not errors — return 200 so the UI can render them
                http = 200 if (res.get("ok") or res.get("preview") or res.get("gated")) else 400
                return http, {"ok": bool(res.get("ok")), "data": res}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)[:160]}

        if base_path == "/api/v2/holdings/protective-stop":
            # Stage 2c STEP 1 — REQUEST a protective SELL stop / stop-limit / trailing on a real holding.
            # Two routes (chosen by the account, never by the client):
            #   • Schwab account with api_write_enabled + protective_stop_policy armed → builds the marked
            #     intent, runs the protective gate, and on pass REQUESTS per-order 2FA (Telegram + email
            #     code + web typed-ticker; EITHER confirms). Returns {mode:"awaiting_approval", intent_id}.
            #     The actual live submit happens at STEP 2 (/protective-stop/confirm).
            #   • Any account without an API (IRAs / Fidelity-401k) OR policy not armed → ticket mode:
            #     returns the exact broker ticket to place manually in thinkorswim.
            # Nothing here can place an order on its own — STEP 1 only messages; STEP 2 needs the 2FA. (2026-06-15)
            try:
                b = body or {}
                sym = str(b.get("symbol") or "").strip().upper()
                acct = str(b.get("account") or "").strip()
                qty = b.get("qty")
                kind = str(b.get("order_kind") or "STOP").upper()
                stop_price = b.get("stop_price")
                limit_price = b.get("limit_price")
                trail_pct = b.get("trail_pct")
                advised_stop = b.get("advised_stop")
                replace_order_id = b.get("replace_order_id")   # MODIFY: cancel this existing stop, then place the new one (one 2FA)
                if not (sym and acct and qty):
                    return 400, {"ok": False, "error": "symbol, account and qty are required"}
                is_fidelity = acct.startswith("fidelity_") and acct != "fidelity_401k"
                if is_fidelity:
                    from brokers import snaptrade_protective_stop_pilot as _psp
                else:
                    from brokers import protective_stop_pilot as _psp
                ot = _psp.normalize_kind(kind)
                if not ot:
                    return 400, {"ok": False, "error": f"unknown order_kind {kind!r}"}
                # FRACTIONAL-SHARE GUARD (operator 2026-06-21): Schwab rejects STOP/STOP_LIMIT/TRAILING orders
                # on fractional quantities ("As of May 21, 2025, fractional orders ... must use Market/Limit").
                # MARKET sell-all keeps the FULL qty (fractional OK — DAY TIF). Stops floor to whole shares.
                qty_note = None
                if acct.startswith("schwab") and ot != "MARKET":
                    try:
                        _qf = float(qty); _qi = int(_qf)   # floor (positive long qty)
                        if _qi != _qf:
                            if _qi < 1:
                                return 200, {"ok": False, "mode": "blocked",
                                             "error": f"{sym} is {_qf:g} share (under 1 whole share) — Schwab does not "
                                                      "accept fractional STOP orders. Use Sell all @ Market instead.",
                                             "account": acct}
                            qty_note = (f"Schwab rejects fractional STOP orders — protecting {_qi} whole "
                                        f"share{'s' if _qi > 1 else ''}; the {_qf - _qi:.4f} fractional remainder "
                                        "isn't stop-eligible at Schwab.")
                            qty = _qi
                    except Exception:
                        pass
                elif acct.startswith("schwab") and ot == "MARKET":
                    held_qty, _ = _protective_holding_truth(acct, sym)
                    if held_qty is not None:
                        try:
                            _hq = float(held_qty)
                            if _hq > 0:
                                qty = _hq
                                qty_note = f"Sell-all uses server-held qty {_hq:g} sh."
                        except Exception:
                            pass
                summ = _psp.order_summary(sym, qty, kind, stop_price=stop_price,
                                          limit_price=limit_price, trail_pct=trail_pct,
                                          account_key=acct)
                ticket = summ["ticket"]
                # server truth for the gate-critical fields (never trust the client for held qty / price)
                held_qty, current_price = _protective_holding_truth(acct, sym)
                if current_price is None:
                    current_price = b.get("current_price")
                is_schwab = acct.startswith("schwab")
                api_write = _protective_account_api_write(acct)
                fidelity_live = False
                if is_fidelity:
                    try:
                        from brokers.execution_guard import _fidelity_monitored_unlocked
                        fidelity_live = _fidelity_monitored_unlocked()
                    except Exception:
                        fidelity_live = False
                schwab_live_route = bool(is_schwab and api_write)
                fidelity_monitored_route = bool(is_fidelity and fidelity_live)
                try:
                    from alert_event_writer import save_alert_event
                    save_alert_event(alert_type="strategic_alert", severity="info",
                                     source_script="protective_stop", symbol=sym,
                                     raw_text=f"[protective-stop:request] {('SCHWAB_LIVE' if schwab_live_route else 'MONITORED' if fidelity_monitored_route else 'TICKET')} · {acct} · {ticket}",
                                     parsed_payload={"kind": "protective_stop", "phase": "request", "symbol": sym,
                                                     "account": acct, "order_kind": ot, "qty": qty,
                                                     "stop_price": stop_price, "trail_pct": trail_pct,
                                                     "mode": ("schwab_live" if schwab_live_route else
                                                              "monitored" if fidelity_monitored_route else "ticket")})
                except Exception:
                    pass
                # Fidelity/SnapTrade: monitor-only — arm DB level directly (no broker, no 2FA).
                if fidelity_monitored_route:
                    from brokers.snaptrade_protective_stop_policy import evaluate as _feval
                    ok, reasons = _feval(
                        account_key=acct, instruction="SELL", order_type=ot,
                        stop_price=float(stop_price) if stop_price is not None else None,
                        advised_stop=float(advised_stop) if advised_stop is not None else None,
                        current_price=float(current_price) if current_price is not None else None,
                        qty=float(qty) if qty is not None else None,
                        held_qty=float(held_qty) if held_qty is not None else None, symbol=sym)
                    if not ok:
                        return 200, {"ok": False, "mode": "blocked", "error": "; ".join(reasons),
                                     "ticket": ticket, "account": acct}
                    import fidelity_monitored_stop as _fms
                    res = _fms.arm(sym, acct, stop_price, qty, order_type=ot, trail_pct=trail_pct,
                                   limit_price=limit_price,
                                   note="armed via Open Trades (monitor-only, no execution)")
                    if not res.get("ok"):
                        return 200, {"ok": False, "mode": "blocked", "error": res.get("error"),
                                     "ticket": ticket, "account": acct}
                    return 200, {"ok": True, "mode": "monitored_armed", "route": "fidelity_monitored",
                                 "result": res, "order": summ, "account": acct, "qty_note": qty_note,
                                 "note": "Monitored stop armed — software watch only. On breach you get an "
                                         "alert + Fidelity Active Trader ticket; nothing executes automatically."}
                if schwab_live_route:
                    intent = _psp.build_intent(acct, sym, qty, kind, stop_price=stop_price,
                                               limit_price=limit_price, trail_pct=trail_pct,
                                               advised_stop=advised_stop, current_price=current_price,
                                               held_qty=held_qty, replace_order_id=replace_order_id)
                    # dry gate check FIRST — fail before messaging if the protective envelope blocks or the
                    # pilot is disarmed. The ONLY reason we proceed past here is the expected "2FA missing"
                    # denial (gate + standing locks all green, only the per-order approval remains).
                    from brokers.execution_guard import authorize
                    d = authorize(intent, "submit")
                    _r = (d.reason or "").lower()
                    if (not d.allowed) and ("two-factor" not in _r):
                        err = d.reason
                        if "execution disabled" in _r or "fail-closed default" in _r:
                            err = ("Protective stops are not enabled (standing authorization off). "
                                   "Ticket mode is available now.")
                        return 200, {"ok": False, "mode": "blocked", "error": err,
                                     "ticket": ticket, "account": acct}
                    req = _psp.request_2fa(intent)
                    if not req.get("ok"):
                        return 200, {"ok": False, "mode": "blocked",
                                     "error": req.get("reason") or "could not request approval",
                                     "holder_intent_ids": req.get("holder_intent_ids"),
                                     "ticket": ticket, "account": acct}
                    return 200, {"ok": True, "mode": "awaiting_approval", "intent_id": intent.intent_id,
                                 "order": summ, "account": acct, "channels": req.get("channels"),
                                 "ttl_min": req.get("ttl_min"), "qty_note": qty_note,
                                 "route": "schwab_live",
                                 "note": ((qty_note + " ") if qty_note else "")
                                         + "Code sent to Telegram + email. Approve from EITHER — enter the code "
                                         "below, tap Approve in Telegram, or type the ticker. Then it submits LIVE at Schwab."}
                _platform = summ.get("platform") or ("thinkorswim" if is_schwab else "Fidelity Active Trader Pro")
                return 200, {"ok": True, "mode": "ticket", "ticket": ticket, "detail": ticket,
                             "order": summ, "account": acct,
                             "manual": f"Place this exact order in {_platform}. "
                                       + ("(Run snaptrade_pilot_arm.py --approve to enable monitored stop route.)"
                                          if is_fidelity and not fidelity_live else
                                          "(This account has no trading API — ticket only.)" if not is_schwab
                                          else "(Account write not enabled — ticket only.)")}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)[:200]}

        if base_path == "/api/v2/holdings/protective-stop/confirm":
            # Stage 2c STEP 2 — CONFIRM the per-order 2FA and, once satisfied, SUBMIT the live protective
            # stop through the proven transport (schwab_transport.place_order, kind='protective_stop', so it
            # never touches the canary 5-order budget). EITHER channel confirms: web (type the ticker) or
            # telegram/email (the one-time code). The order_spec is rebuilt server-side from the persisted
            # intent — the client cannot alter it between request and submit. (2026-06-15)
            try:
                b = body or {}
                intent_id = str(b.get("intent_id") or "").strip()
                channel = str(b.get("channel") or "").strip().lower()
                code = b.get("code")
                if not intent_id or channel not in ("web", "telegram"):
                    return 400, {"ok": False, "error": "intent_id and channel ('web' or 'telegram') required"}
                from brokers import approval_service
                from brokers.execution_guard import FIDELITY_PROTECTIVE_MARKER
                intent = None
                for _mod in ("brokers.snaptrade_protective_stop_pilot", "brokers.protective_stop_pilot"):
                    try:
                        _psp = __import__(_mod, fromlist=["load_intent"])
                        intent = _psp.load_intent(intent_id)
                        if intent:
                            break
                    except Exception:
                        pass
                if intent is None:
                    return 404, {"ok": False, "error": "no protective-stop intent for that id (expired?)"}
                cr = approval_service.confirm(intent_id, channel, str(code) if code is not None else None)
                if not cr.get("ok"):
                    return 200, {"ok": False, "stage": "confirm", "error": cr.get("reason")}
                if not cr.get("fully_approved"):
                    return 200, {"ok": True, "stage": "confirm", "fully_approved": False,
                                 "note": "channel confirmed; waiting on the rest"}
                acct = intent.account_key
                _ev = (getattr(getattr(intent, "meta", None), "signal_evidence", None) or {})
                _replace_id = _ev.get("replace_order_id")
                _replace_stop_id = _ev.get("replace_stop_id")
                replace_result = None
                is_fidelity_intent = getattr(getattr(intent, "meta", None), "strategy_id", None) == FIDELITY_PROTECTIVE_MARKER
                if _replace_stop_id and is_fidelity_intent:
                    try:
                        import fidelity_monitored_stop as _fms
                        replace_result = _fms.cancel(stop_id=int(_replace_stop_id))
                    except Exception as ce:
                        return 200, {"ok": False, "stage": "modify_cancel",
                                     "error": f"could not cancel monitored stop #{_replace_stop_id}: {str(ce)[:160]}"}
                elif _replace_id and not is_fidelity_intent:
                    try:
                        import sys as _sys
                        _sys.path.insert(0, str(Path(__file__).resolve().parent))
                        import schwab_transport as _st
                        replace_result = _st.cancel_order(acct, str(_replace_id))
                    except Exception as ce:
                        return 200, {"ok": False, "stage": "modify_cancel",
                                     "error": f"could not cancel the existing stop #{_replace_id}: {str(ce)[:160]} — "
                                              "new stop NOT placed (avoiding a double stop). Try again or cancel in ToS."}
                from brokers import intent_submit_router as _isr
                sub = _isr.submit_fully_approved(intent_id)
                if sub.get("stage") == "submit" and not sub.get("ok"):
                    return 200, {"ok": False, "stage": "submit", "error": sub.get("error"),
                                 "result": sub.get("result"), "modify_cancel_result": replace_result}
                res = sub.get("result") or {}
                return 200, {"ok": bool(sub.get("ok")), "stage": "submit",
                             "result": res, "broker_order_id": sub.get("broker_order_id"),
                             "status": sub.get("status"), "account": acct,
                             "replaced_order_id": _replace_id, "modify_cancel_result": replace_result,
                             "monitored_stop_id": res.get("id")}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)[:200]}

        if base_path == "/api/v2/holdings/protective-stop/cancel":
            # Stage 2c — cancel a LIVE protective stop from the Open Trades card (the "remove" control).
            # Cancel is the SAFE direction (no 2FA; guard grants cancel under an armed pilot). Only orders
            # this pilot placed (a schwab_pilot_orders row) can be cancelled here; a stop placed manually in
            # thinkorswim must be cancelled in ToS (cancel_order refuses non-pilot orders). (2026-06-15)
            try:
                b = body or {}
                acct = str(b.get("account") or "").strip()
                oid = str(b.get("broker_order_id") or "").strip()
                if not (acct and oid):
                    return 400, {"ok": False, "error": "account and broker_order_id are required"}
                if acct.startswith("fidelity_"):
                    import fidelity_monitored_stop as _fms
                    try:
                        res = _fms.cancel(symbol=str(b.get("symbol") or ""), account=acct)
                        return 200, {"ok": bool(res.get("canceled")), "status": "canceled",
                                     "result": res, "account": acct,
                                     "note": "monitored stop canceled (software watch only — cancel broker order in Active Trader if placed manually)"}
                    except Exception as ce:
                        return 200, {"ok": False, "error": str(ce)[:200]}
                import sys as _sys
                _sys.path.insert(0, str(Path(__file__).resolve().parent))
                import schwab_transport as _st
                try:
                    res = _st.cancel_order(acct, oid)
                except Exception as ce:
                    return 200, {"ok": False, "error": str(ce)[:200],
                                 "hint": "if this stop was placed manually in thinkorswim, cancel it there"}
                try:
                    from alert_event_writer import save_alert_event
                    save_alert_event(alert_type="strategic_alert", severity="info",
                                     source_script="protective_stop", symbol=str(b.get("symbol") or ""),
                                     raw_text=f"[protective-stop:cancel] {acct} · {oid} · {res.get('status')}",
                                     parsed_payload={"kind": "protective_stop", "phase": "cancel",
                                                     "account": acct, "broker_order_id": oid, "result": res})
                except Exception:
                    pass
                # bust the broker-stop cache so the card refreshes immediately
                try:
                    import open_trades_intelligence as _oti
                    _oti._BSTOP_CACHE["ts"] = 0.0
                except Exception:
                    pass
                return 200, {"ok": res.get("status") in ("cancel_requested", "canceled", "cancelled"),
                             "status": res.get("status"), "result": res, "account": acct, "broker_order_id": oid}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)[:200]}

        if base_path == "/api/v2/holdings/stop-snooze":
            # Operator acknowledgement of a triggered/at-risk stop → a GRACE PERIOD (default 7 days). Writes
            # the existing stop_snooze table (the stop monitor at portfolio_stops honors snoozed_until), so the
            # stop ALERT is suppressed for the window. Internal advisory state only — NO broker write, no order
            # change; the protective stop itself is untouched. (operator 2026-06-21)
            try:
                b = body or {}
                sym = str(b.get("symbol") or "").strip().upper()
                if not sym:
                    return 400, {"ok": False, "error": "symbol required"}
                days = b.get("days")
                try:
                    days = float(days) if days is not None else 7.0
                except (TypeError, ValueError):
                    days = 7.0
                days = max(0.0, min(31.0, days))   # cap the grace window at a month
                row = _db_query(
                    """INSERT INTO stop_snooze (symbol, snoozed_until, snoozed_by, created_at)
                       VALUES (%s, NOW() + make_interval(mins => %s), %s, NOW())
                       RETURNING snoozed_until""",
                    (sym, int(days * 24 * 60), b.get("snoozed_by", "operator")), fetch="one")
                until = (row or {}).get("snoozed_until")
                try:
                    from alert_event_writer import save_alert_event
                    save_alert_event(alert_type="strategic_alert", severity="info",
                                     source_script="stop_snooze", symbol=sym,
                                     raw_text=f"[stop-snooze] {sym} acknowledged — {days:g}d grace until {until}",
                                     parsed_payload={"kind": "stop_snooze", "symbol": sym, "days": days,
                                                     "snoozed_until": str(until), "by": b.get("snoozed_by", "operator")})
                except Exception:
                    pass
                return 200, {"ok": True, "symbol": sym, "days": days, "snoozed_until": str(until),
                             "note": "operator acknowledgement — stop alert snoozed; protective stop unchanged (no broker write)"}
            except Exception as e:
                return 500, {"ok": False, "error": str(e)[:200]}

