    # ── ADMIN WRITE SURFACE (Tier-2/3) — every write routes through admin_write_guard ──
    # ACCESS -> CONFIRM (two-step) -> APPLY -> AUDIT. NO Tier-1 (live-execution) control here.
    if method == "POST" and base_path in ("/api/v2/admin/alert/ack", "/api/v2/admin/alert/resolve"):
        try:
            from admin_write_guard import admin_write
            b = body or {}
            source = b.get("source", "alert_events")
            if source not in ("alert_events", "system_health_events"):   # allowlist — no SQL injection
                return 400, {"ok": False, "error": "invalid source"}
            aid = b.get("alert_id")
            if not aid:
                return 400, {"ok": False, "error": "alert_id required"}
            cur_state = _db_query(f"SELECT id, severity, lifecycle_state FROM {source} WHERE id=%s",
                                  (aid,), fetch="one")
            if not cur_state:
                return 404, {"ok": False, "error": "alert not found"}
            operator = (b.get("operator") or "operator")[:60]
            is_ack = base_path.endswith("/ack")
            new_state = "acknowledged" if is_ack else "resolved"
            tcol = "acknowledged" if is_ack else "resolved"

            def _apply():
                _db_write(
                    f"UPDATE {source} SET lifecycle_state=%s, {tcol}_at=NOW(), {tcol}_by=%s WHERE id=%s",
                    (new_state, operator, aid))

            code, resp = admin_write(
                action=f"alert.{new_state}", target=f"{source}:{aid}",
                old_value={"lifecycle_state": cur_state.get("lifecycle_state"), "severity": cur_state.get("severity")},
                new_value={"lifecycle_state": new_state, f"{tcol}_by": operator},
                apply_fn=_apply, operator=operator,
                confirmed=bool(b.get("confirm")), token=b.get("token"))
            return code, resp
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # cron retry — NON-TRADING jobs ONLY (allowlist; trading/unknown jobs excluded by construction)
    if method == "POST" and base_path == "/api/v2/admin/cron/retry":
        try:
            from admin_write_guard import admin_write, cron_retry_allowed
            b = body or {}
            job = (b.get("job") or "").strip()
            if not job:
                return 400, {"ok": False, "error": "job required"}
            if not cron_retry_allowed(job):
                return 403, {"ok": False,
                             "error": f"'{job}' is not on the non-trading retry allowlist (excluded)"}
            operator = (b.get("operator") or "operator")[:60]
            import subprocess as _sp
            def _apply():
                _sp.Popen([str(PROJECT_ROOT / ".venv/bin/python"),
                           str(PROJECT_ROOT / "scripts" / f"{job}.py")],
                          cwd=str(PROJECT_ROOT),
                          stdout=open(PROJECT_ROOT / "logs" / f"{job}.log", "a"), stderr=_sp.STDOUT)
            return admin_write(action="cron.retry", target=f"cron:{job}",
                               old_value={"status": "manual-rerun-requested"},
                               new_value={"action": "launched", "job": job},
                               apply_fn=_apply, operator=operator,
                               confirmed=bool(b.get("confirm")), token=b.get("token"))
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # risk config edit (atm_config.yaml; paper-system limits — NOT a live-account control)
    if method == "POST" and base_path == "/api/v2/admin/risk-config":
        try:
            from admin_write_guard import (admin_write, RISK_CONFIG_FIELDS, ATM_CONFIG_PATH,
                                           read_yaml_value, write_yaml_value)
            b = body or {}
            field = b.get("field")
            if field not in RISK_CONFIG_FIELDS:
                return 400, {"ok": False, "error": f"field not editable: {field}"}
            if "value" not in b:
                return 400, {"ok": False, "error": "value required"}
            new_val = b.get("value")
            kp = RISK_CONFIG_FIELDS[field]
            old_val = read_yaml_value(ATM_CONFIG_PATH, kp)
            operator = (b.get("operator") or "operator")[:60]

            def _apply():
                import shutil, time as _t
                shutil.copy(str(ATM_CONFIG_PATH), f"{ATM_CONFIG_PATH}.bak_{int(_t.time())}")  # IRON RULE
                write_yaml_value(ATM_CONFIG_PATH, kp, new_val)

            return admin_write(action="risk.config", target=f"atm_config:{field}",
                               old_value={field: old_val}, new_value={field: new_val},
                               apply_fn=_apply, operator=operator,
                               confirmed=bool(b.get("confirm")), token=b.get("token"))
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # strategy enablement — enable/disable a strategy per account
    if method == "POST" and base_path == "/api/v2/admin/strategy/enablement":
        try:
            from admin_write_guard import admin_write
            b = body or {}
            sid = (b.get("strategy_id") or "").strip()
            acct = (b.get("account") or "").strip()
            if not sid or not acct:
                return 400, {"ok": False, "error": "strategy_id and account required"}
            enabled = bool(b.get("enabled"))
            cur_row = _db_query("SELECT enabled FROM strategy_enablement WHERE strategy_id=%s AND account=%s",
                                (sid, acct), fetch="one")
            old_enabled = cur_row.get("enabled") if cur_row else None
            operator = (b.get("operator") or "operator")[:60]

            def _apply():
                _db_write("""INSERT INTO strategy_enablement (strategy_id, account, enabled, updated_at, updated_by)
                             VALUES (%s,%s,%s,NOW(),%s)
                             ON CONFLICT (strategy_id, account)
                             DO UPDATE SET enabled=EXCLUDED.enabled, updated_at=NOW(), updated_by=EXCLUDED.updated_by""",
                          (sid, acct, enabled, operator))

            return admin_write(action="strategy.enablement", target=f"{sid}:{acct}",
                               old_value={"enabled": old_enabled}, new_value={"enabled": enabled},
                               apply_fn=_apply, operator=operator,
                               confirmed=bool(b.get("confirm")), token=b.get("token"))
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── ATM state control (PAPER-ONLY, gate-interlocked) ──
    # Interlock runs FIRST: a live-account target is refused (403) before any guard/confirm/apply,
    # until paper_validation_policy.live_trading_allowed is TRUE. atm_state is global (paper-effective:
    # only paper auto-executes; live accounts are interlock-blocked here and not executed downstream).
    if method == "POST" and base_path == "/api/v2/admin/atm/set-state":
        try:
            from admin_write_guard import admin_write
            from live_trading_interlock import assert_writable, InterlockRefused, _conn as _il_conn
            b = body or {}
            account = (b.get("account") or "").strip()
            new_mode = (b.get("mode") or "").strip().lower()
            VALID = {"disabled", "dry_run", "active", "paused"}
            if not account:
                return 400, {"ok": False, "error": "account required"}
            if new_mode not in VALID:
                return 400, {"ok": False, "error": f"mode must be one of {sorted(VALID)}"}
            # ── HARD INTERLOCK (before guard/confirm/apply) ──
            _ic = _il_conn()
            try:
                assert_writable(_ic, account, action=f"set ATM {new_mode}")
            except InterlockRefused as e:
                return 403, {"ok": False, "error": e.reason,
                             "interlock": "live_trading_gate", "detail": e.detail}
            finally:
                _ic.close()
            operator = (b.get("operator") or "operator")[:60]
            reason = b.get("reason") or None
            row = _db_query("SELECT mode, config_hash FROM atm_state WHERE id=1", fetch="one") or {}
            old_mode = row.get("mode", "disabled")
            cfg_hash = row.get("config_hash", "")

            def _apply():
                _db_write("UPDATE atm_state SET mode=%s, last_state_change_at=NOW(), "
                          "last_state_change_by=%s, pause_reason=%s WHERE id=1",
                          (new_mode, operator, reason))
                _db_write("INSERT INTO atm_state_events (old_mode, new_mode, changed_by, reason, config_hash) "
                          "VALUES (%s,%s,%s,%s,%s)", (old_mode, new_mode, operator, reason, cfg_hash))

            return admin_write(action="atm.set_state", target=f"atm_state:{account}",
                               old_value={"mode": old_mode}, new_value={"mode": new_mode},
                               apply_fn=_apply, operator=operator,
                               confirmed=bool(b.get("confirm")), token=b.get("token"))
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Add/Edit a broker API connection (guarded + gate-interlocked) — the ATM "manage APIs" modal ──
    # environment ∈ {paper,sandbox,live,import,read-only}. Enabling api_write on a LIVE account is a
    # live-arming action → refused by the interlock until the gate passes. New accounts get a default
    # DISABLED policy. Secrets are NOT stored here (keys live in .env/keyring); this records the
    # connection config + capability flags only.
    if method == "POST" and base_path == "/api/v2/admin/broker-account/api":
        try:
            from admin_write_guard import admin_write
            from live_trading_interlock import assert_writable, InterlockRefused, _conn as _il_conn
            b = body or {}
            acct = (b.get("account_key") or "").strip().lower().replace(" ", "_")
            broker = (b.get("broker") or "").strip().lower()
            env = (b.get("environment") or "").strip().lower()
            if not acct or not broker:
                return 400, {"ok": False, "error": "account_key and broker required"}
            if env not in BROKER_ENVIRONMENTS:
                return 400, {"ok": False, "error": f"environment must be one of {BROKER_ENVIRONMENTS}"}
            read_en = bool(b.get("api_read_enabled"))
            write_en = bool(b.get("api_write_enabled"))
            # ── HARD INTERLOCK: enabling WRITE on a live account is live-arming → gate-gated ──
            if write_en and env == "live":
                _ic = _il_conn()
                try:
                    assert_writable(_ic, acct, action="enable api_write on live account")
                except InterlockRefused as e:
                    return 403, {"ok": False, "error": e.reason, "interlock": "live_trading_gate", "detail": e.detail}
                except Exception:
                    # account may not exist in accounts table yet → treat live+write as refused (fail-closed)
                    return 403, {"ok": False, "error": "live api_write refused (gate not passed / account unknown)",
                                 "interlock": "live_trading_gate"}
                finally:
                    _ic.close()
            disp = (b.get("display_name") or acct).strip()[:120]
            adapter = (b.get("broker_adapter") or (f"scripts.{broker}_adapter" if broker in ("alpaca", "schwab") else None))
            caps = {k: bool(b.get(k)) for k in ("supports_equities", "supports_options", "supports_fractional",
                    "supports_bracket_orders", "supports_stop_orders", "supports_trailing_stops", "supports_cancel_replace")}
            operator = (b.get("operator") or "operator")[:60]
            existing = _db_query("SELECT id, environment, api_read_enabled, api_write_enabled, broker_adapter "
                                 "FROM broker_accounts WHERE account_key=%s", (acct,), fetch="one")
            old_val = {k: _json_clean(existing.get(k)) for k in ("environment", "api_read_enabled", "api_write_enabled", "broker_adapter")} if existing else {}
            new_val = {"environment": env, "api_read_enabled": read_en, "api_write_enabled": write_en, "broker_adapter": adapter}

            def _apply():
                _db_write("""INSERT INTO broker_accounts
                    (account_key, display_name, broker, environment, is_enabled, api_read_enabled, api_write_enabled,
                     supports_equities, supports_options, supports_fractional, supports_bracket_orders,
                     supports_stop_orders, supports_trailing_stops, supports_cancel_replace, broker_adapter,
                     connection_status, updated_at)
                    VALUES (%s,%s,%s,%s,TRUE,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'configured',now())
                    ON CONFLICT (account_key) DO UPDATE SET display_name=EXCLUDED.display_name,
                      broker=EXCLUDED.broker, environment=EXCLUDED.environment,
                      api_read_enabled=EXCLUDED.api_read_enabled, api_write_enabled=EXCLUDED.api_write_enabled,
                      supports_equities=EXCLUDED.supports_equities, supports_options=EXCLUDED.supports_options,
                      supports_fractional=EXCLUDED.supports_fractional, supports_bracket_orders=EXCLUDED.supports_bracket_orders,
                      supports_stop_orders=EXCLUDED.supports_stop_orders, supports_trailing_stops=EXCLUDED.supports_trailing_stops,
                      supports_cancel_replace=EXCLUDED.supports_cancel_replace, broker_adapter=EXCLUDED.broker_adapter,
                      updated_at=now()""",
                    (acct, disp, broker, env, read_en, write_en, caps["supports_equities"], caps["supports_options"],
                     caps["supports_fractional"], caps["supports_bracket_orders"], caps["supports_stop_orders"],
                     caps["supports_trailing_stops"], caps["supports_cancel_replace"], adapter))
                # ensure a default (DISABLED) policy exists for a new account
                _db_write("""INSERT INTO account_automation_policies (account_id, automation_mode, approval_policy, source, updated_by)
                    SELECT id,'DISABLED','PROPOSAL_ONLY','default_seed',%s FROM broker_accounts WHERE account_key=%s
                    ON CONFLICT (account_id) DO NOTHING""", (operator, acct))

            return admin_write(action="broker.api_config", target=f"account:{acct}",
                               old_value=old_val, new_value=new_val, apply_fn=_apply, operator=operator,
                               confirmed=bool(b.get("confirm")), token=b.get("token"))
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Broker-account automation policy PATCH (guarded + gate-interlocked) ──
    # AUTO_LIVE (or AUTO_PAPER on a live account) is refused by the interlock until the live gate
    # passes. AUTO_PAPER requires an api_write_enabled account. No live arming here.
    if method == "POST" and base_path == "/api/v2/admin/broker-account/policy":
        try:
            from admin_write_guard import admin_write
            from live_trading_interlock import assert_writable, InterlockRefused, _conn as _il_conn
            import json as _j
            b = body or {}
            acct = (b.get("account") or "").strip()
            if not acct:
                return 400, {"ok": False, "error": "account required"}
            ba = _db_query("SELECT id, environment, api_write_enabled FROM broker_accounts WHERE account_key=%s",
                           (acct,), fetch="one")
            if not ba:
                return 404, {"ok": False, "error": f"account {acct} not found"}
            new_mode = (b.get("automation_mode") or "").strip().upper()
            VALID_MODES = {"DISABLED", "MANUAL_REVIEW", "AUTO_PAPER", "AUTO_LIVE", "PAUSED_ENTRIES", "EMERGENCY_STOP"}
            if new_mode and new_mode not in VALID_MODES:
                return 400, {"ok": False, "error": f"invalid automation_mode (one of {sorted(VALID_MODES)})"}
            # ── AUTO_LIVE: gated by ACCOUNT ENVIRONMENT, not the mode label.
            #    PAPER/sandbox account -> no real-money risk (paper endpoint) -> ALLOWED (settable).
            #    LIVE account -> real money -> gate-interlocked (403 until the live-trading gate passes).
            #    Real live execution remains independently governed by live_trading_interlock at order time. ──
            if new_mode == "AUTO_LIVE" and ba["environment"] == "live":
                _ic = _il_conn()
                try:
                    assert_writable(_ic, acct, action="set AUTO_LIVE")
                except InterlockRefused as e:
                    return 403, {"ok": False, "error": e.reason, "interlock": "live_trading_gate", "detail": e.detail}
                finally:
                    _ic.close()
            # ── HARD INTERLOCK: AUTO_PAPER on a LIVE account refused until the gate passes ──
            if new_mode == "AUTO_PAPER" and ba["environment"] == "live":
                _ic = _il_conn()
                try:
                    assert_writable(_ic, acct, action=f"set automation {new_mode}")
                except InterlockRefused as e:
                    return 403, {"ok": False, "error": e.reason, "interlock": "live_trading_gate", "detail": e.detail}
                finally:
                    _ic.close()
            if new_mode == "AUTO_PAPER" and not ba["api_write_enabled"]:
                return 400, {"ok": False, "error": "AUTO_PAPER requires an api_write_enabled account"}
            EDITABLE = {"automation_mode", "approval_policy", "risk_per_trade_pct", "max_new_positions_per_day",
                        "max_concurrent_positions", "max_strategy_allocation_pct", "max_sector_allocation_pct",
                        "daily_loss_pause_pct", "market_hours_only", "require_fresh_quote", "require_stop_defined",
                        "require_target_defined",
                        # Percent-of-equity sizing controls (operator 2026-06-19) — admin-editable, audited.
                        "sizing_engine", "max_position_allocation_pct",
                        "max_risk_dollars_per_trade", "max_notional_per_trade"}
            fields = {k: v for k, v in b.items() if k in EDITABLE}
            if "automation_mode" in fields:
                fields["automation_mode"] = new_mode
            if "sizing_engine" in fields and fields["sizing_engine"] not in ("percent_equity", "fixed_dollar"):
                return 400, {"ok": False, "error": "sizing_engine must be 'percent_equity' or 'fixed_dollar'"}
            # Guard the percentages so an admin typo can't blow up sizing (whole-percent units: 5 = 5%).
            for _pk in ("risk_per_trade_pct", "max_position_allocation_pct", "max_strategy_allocation_pct",
                        "max_sector_allocation_pct", "daily_loss_pause_pct"):
                if _pk in fields and fields[_pk] is not None:
                    try:
                        _pv = float(fields[_pk])
                    except (TypeError, ValueError):
                        return 400, {"ok": False, "error": f"{_pk} must be a number (whole percent, e.g. 5 = 5%)"}
                    if _pv < 0 or _pv > 100:
                        return 400, {"ok": False, "error": f"{_pk} out of range 0–100 (whole percent)"}
            # display_name is the editable section/account NAME (lives on broker_accounts)
            disp_new = b.get("display_name")
            disp_new = disp_new.strip()[:120] if isinstance(disp_new, str) and disp_new.strip() else None
            if not fields and not disp_new:
                return 400, {"ok": False, "error": "no editable policy fields or display_name supplied"}
            operator = (b.get("operator") or "operator")[:60]
            old = _db_query("SELECT * FROM account_automation_policies WHERE account_id=%s",
                            (ba["id"],), fetch="one") or {}
            old_disp = _db_query("SELECT display_name FROM broker_accounts WHERE id=%s", (ba["id"],), fetch="one")
            old_val = {k: _json_clean(old.get(k)) for k in fields}
            new_val = dict(fields)
            if disp_new:
                old_val["display_name"] = (old_disp or {}).get("display_name")
                new_val["display_name"] = disp_new

            def _apply():
                if fields:
                    sets = ", ".join(f"{k}=%s" for k in fields) + ", updated_at=now(), updated_by=%s, source='database'"
                    _db_write(f"UPDATE account_automation_policies SET {sets} WHERE account_id=%s",
                              (*fields.values(), operator, ba["id"]))
                if disp_new:
                    _db_write("UPDATE broker_accounts SET display_name=%s, updated_at=now() WHERE id=%s", (disp_new, ba["id"]))
                _db_write("INSERT INTO account_automation_policy_audit (account_id, old_policy, new_policy, changed_by, change_reason) "
                          "VALUES (%s,%s,%s,%s,%s)", (ba["id"], _j.dumps(old_val), _j.dumps(new_val), operator, b.get("reason")))

            return admin_write(action="broker.automation_policy", target=f"account:{acct}",
                               old_value=old_val, new_value=new_val, apply_fn=_apply, operator=operator,
                               confirmed=bool(b.get("confirm")), token=b.get("token"))
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Proposal controls: approve / adjust-approve / edit-criteria (guarded + gate-interlocked) ──
    # Interlock runs FIRST on the proposal's target account; live targets are refused until the gate
    # passes. Approved proposals go to the paper (alpaca) path; no live broker is reached.
    if method == "POST" and base_path in ("/api/v2/admin/proposal/approve",
                                          "/api/v2/admin/proposal/adjust-approve",
                                          "/api/v2/admin/proposal/edit-criteria"):
        try:
            from admin_write_guard import admin_write
            from live_trading_interlock import assert_writable, InterlockRefused, _conn as _il_conn
            b = body or {}
            pid = b.get("proposal_id")
            if not pid:
                return 400, {"ok": False, "error": "proposal_id required"}
            prop = _db_query("SELECT id, symbol, status, target_account, proposed_account, "
                             "proposed_entry, proposed_stop, proposed_target1, proposed_target2, proposed_shares "
                             "FROM paper_trade_proposals WHERE id=%s", (pid,), fetch="one")
            if not prop:
                return 404, {"ok": False, "error": f"proposal {pid} not found"}
            acct = prop.get("target_account") or prop.get("proposed_account") or os.environ.get("DEFAULT_PAPER_ACCOUNT")
            kind = base_path.rsplit("/", 1)[-1]
            # ── HARD INTERLOCK (before guard/confirm/apply) ──
            _ic = _il_conn()
            try:
                assert_writable(_ic, acct, action=f"proposal {kind}")
            except InterlockRefused as e:
                return 403, {"ok": False, "error": e.reason,
                             "interlock": "live_trading_gate", "detail": e.detail}
            finally:
                _ic.close()
            operator = (b.get("operator") or "operator")[:60]
            EDITABLE = {"proposed_entry", "proposed_stop", "proposed_target1", "proposed_target2", "proposed_shares"}
            edits = {}
            for k, v in (b.get("fields") or {}).items():
                if k not in EDITABLE:
                    return 400, {"ok": False, "error": f"field not editable: {k}"}
                try:
                    edits[k] = float(v)
                except (TypeError, ValueError):
                    return 400, {"ok": False, "error": f"field {k} must be numeric"}
            is_approve = kind == "approve"
            is_adjust = kind == "adjust-approve"
            is_edit = kind == "edit-criteria"
            if (is_adjust or is_edit) and not edits:
                return 400, {"ok": False, "error": "fields required for adjust/edit"}
            old_val = {k: _json_clean(prop.get(k)) for k in edits}
            new_val = dict(edits)
            if is_approve or is_adjust:
                old_val["status"] = prop.get("status")
                new_val["status"] = "APPROVED_FOR_PAPER_TEST"

            def _apply():
                if edits:
                    sets = ", ".join(f"{k}=%s" for k in edits) + ", updated_at=NOW()"
                    _db_write(f"UPDATE paper_trade_proposals SET {sets} WHERE id=%s", (*edits.values(), pid))
                if is_approve or is_adjust:
                    _db_write("UPDATE paper_trade_proposals SET status='APPROVED_FOR_PAPER_TEST', "
                              "approved_at=NOW(), approved_by=%s, updated_at=NOW() WHERE id=%s", (operator, pid))

            action = ("proposal.approve" if is_approve else
                      "proposal.adjust_approve" if is_adjust else "proposal.edit_criteria")
            return admin_write(action=action, target=f"proposal:{pid}:{prop.get('symbol')}",
                               old_value=old_val, new_value=new_val, apply_fn=_apply, operator=operator,
                               confirmed=bool(b.get("confirm")), token=b.get("token"))
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Research Topic Registry CRUD (guarded via admin_write -> admin_audit_log) ──
    if method == "POST" and base_path == "/api/v2/admin/topic/upsert":
        try:
            from admin_write_guard import admin_write
            import json as _json
            b = body or {}
            tid = (b.get("topic_id") or "").strip().lower().replace(" ", "_")
            if not tid:
                return 400, {"ok": False, "error": "topic_id required"}
            display = (b.get("display_name") or tid).strip()[:120]
            owner = (b.get("owner") or "shared").strip().lower()
            if owner not in ("tradeai", "hermes", "shared"):
                return 400, {"ok": False, "error": "owner must be tradeai|hermes|shared"}
            priority = int(b.get("priority") or 5)
            enabled = bool(b.get("enabled", True))
            sq = b.get("search_queries") or []
            vq = b.get("video_queries") or []
            if isinstance(sq, str):
                sq = [s.strip() for s in sq.splitlines() if s.strip()]
            if isinstance(vq, str):
                vq = [s.strip() for s in vq.splitlines() if s.strip()]
            max_age = int(b.get("max_age_days") or 30)
            min_art = int(b.get("min_articles") or 3)
            operator = (b.get("operator") or "operator")[:60]
            existing = _db_query("SELECT display_name, owner, priority, enabled, search_queries, "
                                 "video_queries, max_age_days, min_articles FROM topic_monitor WHERE topic_id=%s",
                                 (tid,), fetch="one")
            old_value = {k: _json_clean(v) for k, v in existing.items()} if existing else None
            new_value = {"display_name": display, "owner": owner, "priority": priority,
                         "enabled": enabled, "search_queries": sq, "video_queries": vq,
                         "max_age_days": max_age, "min_articles": min_art}

            def _apply():
                _db_write("""INSERT INTO topic_monitor
                        (topic_id, display_name, owner, priority, enabled, search_queries,
                         video_queries, max_age_days, min_articles, updated_at)
                    VALUES (%s,%s,%s,%s,%s,%s::jsonb,%s::jsonb,%s,%s,NOW())
                    ON CONFLICT (topic_id) DO UPDATE SET
                        display_name=EXCLUDED.display_name, owner=EXCLUDED.owner,
                        priority=EXCLUDED.priority, enabled=EXCLUDED.enabled,
                        search_queries=EXCLUDED.search_queries, video_queries=EXCLUDED.video_queries,
                        max_age_days=EXCLUDED.max_age_days, min_articles=EXCLUDED.min_articles,
                        updated_at=NOW()""",
                    (tid, display, owner, priority, enabled, _json.dumps(sq), _json.dumps(vq),
                     max_age, min_art))

            return admin_write(action="topic.upsert", target=f"topic:{tid}",
                               old_value=old_value, new_value=new_value,
                               apply_fn=_apply, operator=operator,
                               confirmed=bool(b.get("confirm")), token=b.get("token"))
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if method == "POST" and base_path == "/api/v2/admin/topic/toggle":
        try:
            from admin_write_guard import admin_write
            b = body or {}
            tid = (b.get("topic_id") or "").strip()
            if not tid:
                return 400, {"ok": False, "error": "topic_id required"}
            enabled = bool(b.get("enabled"))
            row = _db_query("SELECT enabled FROM topic_monitor WHERE topic_id=%s", (tid,), fetch="one")
            if not row:
                return 404, {"ok": False, "error": f"topic not found: {tid}"}
            operator = (b.get("operator") or "operator")[:60]

            def _apply():
                _db_write("UPDATE topic_monitor SET enabled=%s, updated_at=NOW() WHERE topic_id=%s",
                          (enabled, tid))

            return admin_write(action="topic.toggle", target=f"topic:{tid}",
                               old_value={"enabled": row.get("enabled")}, new_value={"enabled": enabled},
                               apply_fn=_apply, operator=operator,
                               confirmed=bool(b.get("confirm")), token=b.get("token"))
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if method == "POST" and base_path == "/api/v2/admin/topic/delete":
        try:
            from admin_write_guard import admin_write
            b = body or {}
            tid = (b.get("topic_id") or "").strip()
            if not tid:
                return 400, {"ok": False, "error": "topic_id required"}
            row = _db_query("SELECT display_name, owner, enabled FROM topic_monitor WHERE topic_id=%s",
                            (tid,), fetch="one")
            if not row:
                return 404, {"ok": False, "error": f"topic not found: {tid}"}
            operator = (b.get("operator") or "operator")[:60]

            def _apply():
                _db_write("DELETE FROM topic_monitor WHERE topic_id=%s", (tid,))

            return admin_write(action="topic.delete", target=f"topic:{tid}",
                               old_value={k: _json_clean(v) for k, v in row.items()}, new_value=None,
                               apply_fn=_apply, operator=operator,
                               confirmed=bool(b.get("confirm")), token=b.get("token"))
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # Static routes
