    # ── Agent Collaboration Dashboard v3 — Mission-Group Cockpit ─────────
    if base_path == "/api/v2/agent-collaboration":
        try:
            from datetime import datetime, timezone, timedelta
            _now_utc = datetime.now(timezone.utc)
            _jc = lambda rows: [{k: _json_clean(v) for k, v in r.items()} for r in rows]

            # MISSION GROUPS — cluster raw threads into operator packs
            # ══════════════════════════════════════════════════════════

            missions = []

            # ── M1: Risk & Stops — triggered stops ──
            stops = _db_query("""
                SELECT e.symbol, e.priority, e.created_at,
                       b.thesis_status, b.what_changed, b.confidence
                FROM agent_event_queue e
                LEFT JOIN LATERAL (
                    SELECT thesis_status, what_changed, confidence
                    FROM aegis_portfolio_briefs WHERE symbol=e.symbol
                    ORDER BY observed_at DESC LIMIT 1
                ) b ON true
                WHERE e.event_type='STOP_TRIGGERED' AND e.status='pending'
                ORDER BY e.created_at DESC
            """) or []
            if stops:
                syms = [s["symbol"] for s in stops]
                missions.append({
                    "mission_id": "risk_stop_review",
                    "mission_type": "risk",
                    "title": f"Stop Review — {len(stops)} triggered positions",
                    "severity": "critical",
                    "status": "blocked",
                    "thread_count": len(stops),
                    "blocked_count": len(stops),
                    "ready_count": 0,
                    "agents": ["Risk", "Aegis", "Steph"],
                    "primary_owner": "operator",
                    "primary_blocker": f"{len(stops)} stops breached",
                    "next_action": {"label": f"Review stop breach: {', '.join(syms[:5])}", "reason": "Positions hit stop prices — decide hold/sell/adjust", "url": "/v2/recovery-watch"},
                    "updated_at": _json_clean(stops[0]["created_at"]),
                    "threads": [{
                        "subject": s["symbol"], "status": "blocked",
                        "detail": s.get("what_changed") or f"{s['symbol']} stop triggered",
                        "thesis": s.get("thesis_status"),
                        "confidence": _json_clean(s.get("confidence")),
                    } for s in stops],
                })

            # ── M1b: Portfolio heat ──
            heat_alerts = _db_query("""
                SELECT symbol, severity, created_at FROM alert_events
                WHERE alert_type='strategic_alert' AND severity='warning'
                AND created_at > NOW() - INTERVAL '7 days'
                ORDER BY created_at DESC LIMIT 3
            """) or []
            if heat_alerts:
                missions.append({
                    "mission_id": "risk_heat", "mission_type": "risk",
                    "title": "Portfolio heat above threshold",
                    "severity": "high", "status": "ready",
                    "thread_count": 1, "blocked_count": 0, "ready_count": 1,
                    "agents": ["Risk", "Aegis"],
                    "primary_owner": "operator", "primary_blocker": None,
                    "next_action": {"label": "Review portfolio heat and concentration", "reason": "Heat 7.2% above 5% threshold", "url": "/v2/risk"},
                    "updated_at": _json_clean(heat_alerts[0]["created_at"]),
                    "threads": [],
                })

            # ── M2: Paper Proposals ──
            proposals = _db_query("""
                SELECT id, symbol, setup_type, status, signal_score, signal_decision, created_at
                FROM paper_trade_proposals
                WHERE status IN ('PENDING','RISK_BLOCKED','APPROVED_FOR_PAPER_TEST')
                ORDER BY CASE status WHEN 'PENDING' THEN 0 WHEN 'RISK_BLOCKED' THEN 1 ELSE 2 END, created_at DESC
            """) or []
            if proposals:
                pending = [p for p in proposals if p["status"] == "PENDING"]
                risk_bl = [p for p in proposals if p["status"] == "RISK_BLOCKED"]
                running = [p for p in proposals if p["status"] == "APPROVED_FOR_PAPER_TEST"]
                missions.append({
                    "mission_id": "proposals", "mission_type": "paper_proposal",
                    "title": f"Paper Proposal Queue — {len(pending)} ready, {len(risk_bl)} blocked, {len(running)} running",
                    "severity": "high" if pending else "medium",
                    "status": "ready" if pending else ("blocked" if risk_bl else "running"),
                    "thread_count": len(proposals), "blocked_count": len(risk_bl), "ready_count": len(pending),
                    "agents": ["Maria", "Steph", "Risk"],
                    "primary_owner": "operator" if pending else "system",
                    "primary_blocker": f"{len(risk_bl)} risk-gated" if risk_bl else None,
                    "next_action": {"label": f"Approve/reject {len(pending)} proposals: {', '.join(p['symbol'] for p in pending[:4])}", "reason": "Proposals awaiting operator decision", "url": "/v2/paper-proposals"} if pending else {"label": f"Review {len(risk_bl)} risk-blocked proposals", "reason": "Risk gate preventing execution"},
                    "updated_at": _json_clean(proposals[0]["created_at"]),
                    "threads": [{
                        "subject": p["symbol"], "status": "ready" if p["status"]=="PENDING" else ("blocked" if p["status"]=="RISK_BLOCKED" else "running"),
                        "detail": f"{p.get('setup_type','')} — {p['status']}",
                        "signal": p.get("signal_decision"),
                    } for p in proposals],
                })

            # ── M3: Aegis Brief Follow-ups (needs Steph) ──
            steph_briefs = _db_query("""
                SELECT DISTINCT ON (symbol) symbol, brief_type, thesis_status, what_changed,
                       confidence, escalation_reason, observed_at,
                       EXTRACT(EPOCH FROM (NOW() - observed_at)) / 3600 as age_hours
                FROM aegis_portfolio_briefs
                WHERE needs_steph_review = true AND observed_at > NOW() - INTERVAL '48 hours'
                ORDER BY symbol, observed_at DESC
            """) or []
            if steph_briefs:
                # Get Steph's last analysis per symbol and calibration quality
                _steph_cal = _db_query("SELECT accuracy, calibration_error, resolved, correct, incorrect, sample_size_status FROM agent_calibration_windows WHERE agent_name='steph'", fetch="one") or {}
                _steph_latest = _db_query("SELECT symbol, created_at FROM watchlist_agent_results WHERE agent='steph' ORDER BY created_at DESC LIMIT 1", fetch="one") or {}
                _steph_last_run = _json_clean(_steph_latest.get("created_at"))
                # Cron schedule context
                _steph_schedule = "Weekdays: every 15min 6AM-7PM, every 5min 8PM-11PM. Weekends: every 10min."
                _steph_next_pickup = "Next scheduled run within 10-15 minutes (if cron active)"

                _triggered = [b for b in steph_briefs if b.get("thesis_status") == "triggered"]
                _weakening = [b for b in steph_briefs if b.get("thesis_status") == "weakening"]
                _other = [b for b in steph_briefs if b.get("thesis_status") not in ("triggered", "weakening")]

                _brief_threads = []
                for b in steph_briefs:
                    # Get Steph's last result for this symbol
                    _sr = _db_query("SELECT recommendation, confidence, next_action, created_at FROM watchlist_agent_results WHERE agent='steph' AND symbol=%s ORDER BY created_at DESC LIMIT 1", [b["symbol"]], fetch="one")
                    _brief_threads.append({
                        "subject": b["symbol"],
                        "status": "blocked" if b.get("thesis_status") == "triggered" else "waiting",
                        "thesis": b.get("thesis_status"),
                        "detail": b.get("what_changed", "")[:120],
                        "confidence": _json_clean(b.get("confidence")),
                        "age_hours": round(float(b.get("age_hours") or 0), 1),
                        "observed_at": _json_clean(b.get("observed_at")),
                        "escalation_reason": b.get("escalation_reason"),
                        "steph_last_review": _json_clean(_sr.get("created_at")) if _sr else None,
                        "steph_recommendation": _sr.get("recommendation") if _sr else None,
                        "steph_confidence": _json_clean(_sr.get("confidence")) if _sr else None,
                        "steph_next_action": _sr.get("next_action") if _sr else None,
                    })

                steph_count = len(steph_briefs)
                missions.append({
                    "mission_id": "aegis_steph_followup", "mission_type": "morning_brief",
                    "title": f"Aegis briefs — {steph_count} need Steph review ({len(_triggered)} triggered, {len(_weakening)} weakening)",
                    "severity": "high" if _triggered else "medium",
                    "status": "blocked" if _triggered else "waiting",
                    "thread_count": steph_count, "blocked_count": len(_triggered), "ready_count": 0,
                    "agents": ["Aegis", "Steph"],
                    "primary_owner": "Steph",
                    "primary_blocker": f"{len(_triggered)} stops triggered — Steph review overdue" if _triggered else None,
                    "next_action": {
                        "label": f"Ask Steph to review {steph_count} flagged briefs ({len(_triggered)} triggered, {len(_weakening)} weakening)",
                        "reason": f"Aegis identified {len(_triggered)} triggered stops and {len(_weakening)} weakening theses needing technical review",
                    },
                    "updated_at": _json_clean(steph_briefs[0].get("observed_at")),
                    "threads": _brief_threads,
                    "agent_maturity": {
                        "agent": "steph",
                        "accuracy": _json_clean(_steph_cal.get("accuracy")),
                        "calibration_error": _json_clean(_steph_cal.get("calibration_error")),
                        "correct": _steph_cal.get("correct", 0),
                        "resolved": _steph_cal.get("resolved", 0),
                        "incorrect": _steph_cal.get("incorrect", 0),
                        "sample_size_status": _steph_cal.get("sample_size_status"),
                        "last_run": _steph_last_run,
                        "schedule": _steph_schedule,
                        "next_expected_pickup": _steph_next_pickup,
                    },
                })

            # ── M4: Research & Content Intelligence — stale topics ──
            stale_topics = _db_query("""
                SELECT symbol, created_at FROM alert_events
                WHERE alert_type='data_staleness' AND created_at > NOW()-INTERVAL '7 days'
                ORDER BY created_at DESC
            """) or []
            if stale_topics:
                missions.append({
                    "mission_id": "research_stale", "mission_type": "research_gap",
                    "title": f"Stale research topics — {len(stale_topics)} waiting",
                    "severity": "medium", "status": "stale",
                    "thread_count": len(stale_topics), "blocked_count": 0, "ready_count": 0,
                    "agents": ["Iris", "Aegis"],
                    "primary_owner": "Iris", "primary_blocker": "Content stale",
                    "next_action": {"label": f"Send {len(stale_topics)} stale topics to Iris for refresh", "reason": "Intelligence sources outdated — agents working with old data"},
                    "updated_at": _json_clean(stale_topics[0]["created_at"]),
                    "threads": [{
                        "subject": s["symbol"].replace("topic:", ""), "status": "stale",
                        "detail": f"Data staleness alert",
                    } for s in stale_topics],
                })

            # ── M5: Debates / Escalations ──
            debates = _db_query("""
                SELECT symbol, participants, consensus_recommendation, consensus_score,
                       escalated_to_alex, status, created_at
                FROM agent_debate_log ORDER BY created_at DESC LIMIT 10
            """) or []
            if debates:
                missions.append({
                    "mission_id": "debates", "mission_type": "ticker",
                    "title": f"Agent debates — {len(debates)} logged, {sum(1 for d in debates if d.get('escalated_to_alex'))} escalated to Alex",
                    "severity": "medium", "status": "completed",
                    "thread_count": len(debates), "blocked_count": 0, "ready_count": 0,
                    "agents": list(set(a for d in debates for a in (d.get("participants") or []))),
                    "primary_owner": "system", "primary_blocker": None,
                    "next_action": {"label": "Review debate outcomes", "reason": "Agent disagreements resolved — verify consensus"},
                    "updated_at": _json_clean(debates[0]["created_at"]),
                    "threads": [{
                        "subject": d["symbol"], "status": d.get("status", "completed"),
                        "detail": f"Consensus: {d.get('consensus_recommendation')} ({float(d.get('consensus_score') or 0):.0%})",
                    } for d in debates],
                })

            # ── M6: Agent Telemetry Health ──
            telem_items = []
            for tbl, label, last in [
                ("agent_debate_log", "Debate telemetry", None),
                ("agent_handoffs", "Handoff telemetry", None),
                ("agent_event_queue", "Event queue", None),
            ]:
                row = _db_query(f"SELECT MAX(created_at) as t FROM {tbl}", fetch="one") or {}
                ts = row.get("t")
                if ts:
                    hrs = (_now_utc - ts.replace(tzinfo=timezone.utc if ts.tzinfo is None else ts.tzinfo)).total_seconds() / 3600
                    if hrs > 48:
                        telem_items.append({"source": label, "last": _json_clean(ts), "hours_stale": round(hrs)})
            if telem_items:
                missions.append({
                    "mission_id": "telemetry_health", "mission_type": "system_health",
                    "title": f"Agent telemetry stale — {len(telem_items)} sources",
                    "severity": "low", "status": "stale",
                    "thread_count": len(telem_items), "blocked_count": 0, "ready_count": 0,
                    "agents": [], "primary_owner": "system",
                    "primary_blocker": "Telemetry feeds inactive",
                    "next_action": {"label": "Verify agent crons running on Monday", "reason": f"{', '.join(t['source'] for t in telem_items)} stale"},
                    "updated_at": _json_clean(telem_items[0]["last"]) if telem_items else None,
                    "threads": [{"subject": t["source"], "status": "stale", "detail": f"Last activity {t['hours_stale']}h ago"} for t in telem_items],
                })

            # ── M7: Handoff escalations to operator ──
            esc_handoffs = _db_query("""
                SELECT symbol, from_agent, intent, created_at
                FROM agent_handoffs WHERE to_agent='human_review'
                AND created_at > NOW()-INTERVAL '7 days'
                ORDER BY created_at DESC LIMIT 10
            """) or []
            if esc_handoffs:
                missions.append({
                    "mission_id": "operator_escalations", "mission_type": "alert",
                    "title": f"Operator escalations — {len(esc_handoffs)} items",
                    "severity": "high", "status": "ready",
                    "thread_count": len(esc_handoffs), "blocked_count": 0, "ready_count": len(esc_handoffs),
                    "agents": list(set(h["from_agent"] for h in esc_handoffs)),
                    "primary_owner": "operator", "primary_blocker": None,
                    "next_action": {"label": f"Review {len(esc_handoffs)} agent escalations", "reason": "Agents escalated conflicts/questions to operator", "url": None},
                    "updated_at": _json_clean(esc_handoffs[0]["created_at"]),
                    "threads": [{
                        "subject": h["symbol"] or "system", "status": "ready",
                        "detail": h["intent"][:80],
                    } for h in esc_handoffs],
                })

            # ── John's Next Actions (derived from missions) ──
            john_actions = []
            for m in missions:
                if m.get("next_action") and m.get("primary_owner") == "operator":
                    john_actions.append({
                        "mission_id": m["mission_id"],
                        "label": m["next_action"]["label"],
                        "reason": m["next_action"].get("reason", ""),
                        "severity": m["severity"],
                        "url": m["next_action"].get("url"),
                    })
            # Also add stale/system items as lower-priority actions
            for m in missions:
                if m.get("next_action") and m.get("primary_owner") != "operator" and m["status"] in ("stale", "waiting"):
                    john_actions.append({
                        "mission_id": m["mission_id"],
                        "label": m["next_action"]["label"],
                        "reason": m["next_action"].get("reason", ""),
                        "severity": m["severity"],
                        "url": m["next_action"].get("url"),
                    })

            # ── Summary ──
            _aegis_latest = _db_query("SELECT MAX(observed_at) as t FROM aegis_portfolio_briefs", fetch="one") or {}
            _latest_ts = None
            for m in missions:
                u = m.get("updated_at")
                if u and (not _latest_ts or u > str(_latest_ts)):
                    _latest_ts = u
            _dow = datetime.now().weekday()
            _hrs_trust = 999
            if _aegis_latest.get("t"):
                _hrs_trust = (_now_utc - _aegis_latest["t"].replace(tzinfo=timezone.utc if _aegis_latest["t"].tzinfo is None else _aegis_latest["t"].tzinfo)).total_seconds() / 3600
            _trust = "fresh" if _hrs_trust < 12 else ("weekend" if _dow in (5,6) and _hrs_trust < 60 else ("stale" if _hrs_trust < 48 else "degraded"))

            summary = {
                "total_missions": len(missions),
                "active_missions": sum(1 for m in missions if m["status"] not in ("completed",)),
                "blocked_missions": sum(1 for m in missions if m["status"] == "blocked"),
                "ready_for_operator": sum(1 for m in missions if m["primary_owner"] == "operator" and m["status"] in ("ready", "blocked")),
                "stale_missions": sum(1 for m in missions if m["status"] == "stale"),
                "last_aegis_synthesis_at": _json_clean(_aegis_latest.get("t")),
                "system_trust_state": _trust,
            }

            # ── Agent network ──
            network = _db_query("""
                SELECT from_agent, to_agent, COUNT(*) as cnt,
                  COUNT(*) FILTER (WHERE escalated=true) as escalated,
                  MAX(created_at) as latest
                FROM agent_handoffs GROUP BY from_agent, to_agent
                ORDER BY cnt DESC
            """) or []

            # ══════════════════════════════════════════════════════════
            # COLLABORATION SCORING — 7 derived fields
            # ══════════════════════════════════════════════════════════

            scoring = {}

            # 1. collaboration_outcome — per-handoff: completed vs open vs escalated
            _ho = _db_query("""
                SELECT
                  COUNT(*) as total,
                  COUNT(*) FILTER (WHERE status IN ('completed','done')) as completed,
                  COUNT(*) FILTER (WHERE status NOT IN ('completed','done')) as open,
                  COUNT(*) FILTER (WHERE escalated=true) as escalated
                FROM agent_handoffs
            """, fetch="one") or {}
            scoring["collaboration_outcome"] = {
                "total_handoffs": _ho.get("total", 0),
                "completed": _ho.get("completed", 0),
                "open": _ho.get("open", 0),
                "escalated": _ho.get("escalated", 0),
                "completion_rate": round(_ho["completed"] / _ho["total"], 3) if _ho.get("total") else None,
            }

            # 2. handoff_resolution_time — median time from created_at to latest status change
            _hrt = _db_query("""
                SELECT
                  AVG(EXTRACT(EPOCH FROM (COALESCE(
                    (SELECT MAX(h2.created_at) FROM agent_handoffs h2
                     WHERE h2.symbol=h.symbol AND h2.from_agent=h.to_agent AND h2.created_at > h.created_at),
                    h.created_at
                  ) - h.created_at)) / 3600) as avg_hours,
                  MIN(EXTRACT(EPOCH FROM (COALESCE(
                    (SELECT MAX(h2.created_at) FROM agent_handoffs h2
                     WHERE h2.symbol=h.symbol AND h2.from_agent=h.to_agent AND h2.created_at > h.created_at),
                    h.created_at
                  ) - h.created_at)) / 3600) as min_hours,
                  MAX(EXTRACT(EPOCH FROM (COALESCE(
                    (SELECT MAX(h2.created_at) FROM agent_handoffs h2
                     WHERE h2.symbol=h.symbol AND h2.from_agent=h.to_agent AND h2.created_at > h.created_at),
                    h.created_at
                  ) - h.created_at)) / 3600) as max_hours
                FROM agent_handoffs h
                WHERE h.status IN ('completed','done')
                AND h.created_at > NOW() - INTERVAL '30 days'
            """, fetch="one") or {}
            scoring["handoff_resolution_time"] = {
                "avg_hours": round(float(_hrt.get("avg_hours") or 0), 1),
                "min_hours": round(float(_hrt.get("min_hours") or 0), 1),
                "max_hours": round(float(_hrt.get("max_hours") or 0), 1),
                "period": "30d",
            }

            # 3. agent_agreement_score — from debate consensus_score
            _deb = _db_query("""
                SELECT
                  COUNT(*) as total_debates,
                  AVG(consensus_score) as avg_consensus,
                  COUNT(*) FILTER (WHERE consensus_score >= 0.7) as high_agreement,
                  COUNT(*) FILTER (WHERE consensus_score < 0.5) as low_agreement,
                  COUNT(*) FILTER (WHERE escalated_to_alex=true) as escalated
                FROM agent_debate_log
            """, fetch="one") or {}
            scoring["agent_agreement_score"] = {
                "total_debates": _deb.get("total_debates", 0),
                "avg_consensus": round(float(_deb.get("avg_consensus") or 0), 3),
                "high_agreement": _deb.get("high_agreement", 0),
                "low_agreement": _deb.get("low_agreement", 0),
                "escalated_to_alex": _deb.get("escalated", 0),
            }

            # 4. evidence_completeness — from watchlist_agent_results coverage
            _ev = _db_query("""
                SELECT
                  COUNT(DISTINCT symbol) as symbols_analyzed,
                  COUNT(*) as total_results,
                  COUNT(DISTINCT agent) as agents_active,
                  AVG(confidence) as avg_confidence,
                  COUNT(*) FILTER (WHERE confidence IS NULL OR confidence < 0.3) as low_confidence,
                  COUNT(*) FILTER (WHERE confidence >= 0.6) as high_confidence
                FROM watchlist_agent_results
                WHERE created_at > NOW() - INTERVAL '7 days'
            """, fetch="one") or {}
            scoring["evidence_completeness"] = {
                "symbols_analyzed_7d": _ev.get("symbols_analyzed", 0),
                "total_results_7d": _ev.get("total_results", 0),
                "agents_active": _ev.get("agents_active", 0),
                "avg_confidence": round(float(_ev.get("avg_confidence") or 0), 3),
                "low_confidence_count": _ev.get("low_confidence", 0),
                "high_confidence_count": _ev.get("high_confidence", 0),
            }

            # 5. stale_remediation_result — from state_freshness_history
            _sr = _db_query("""
                SELECT
                  COUNT(*) as total_checks,
                  COUNT(*) FILTER (WHERE ok=true) as fresh,
                  COUNT(*) FILTER (WHERE ok=false) as stale,
                  MAX(checked_at) as last_check
                FROM state_freshness_history
                WHERE checked_at = (SELECT MAX(checked_at) FROM state_freshness_history)
            """, fetch="one") or {}
            scoring["stale_remediation_result"] = {
                "total_products": _sr.get("total_checks", 0),
                "fresh": _sr.get("fresh", 0),
                "stale": _sr.get("stale", 0),
                "freshness_rate": round(_sr["fresh"] / _sr["total_checks"], 3) if _sr.get("total_checks") else None,
                "last_check": _json_clean(_sr.get("last_check")),
            }

            # 6. mission_raci_process_key — load RACI config and map to missions
            import yaml
            _raci_path = PROJECT_ROOT / "config" / "agent_raci.yaml"
            _raci_processes = []
            if _raci_path.exists():
                try:
                    _raci_cfg = yaml.safe_load(_raci_path.read_text()) or {}
                    _raci_processes = _raci_cfg.get("processes", [])
                except Exception:
                    pass
            scoring["mission_raci_process_key"] = {
                "processes_defined": len(_raci_processes),
                "processes": [{
                    "id": p.get("id"),
                    "name": p.get("name"),
                    "trigger": p.get("trigger"),
                    "frequency": p.get("frequency"),
                    "agents": list((p.get("raci") or {}).keys()),
                    "roles": p.get("raci", {}),
                } for p in _raci_processes],
                "source": "config/agent_raci.yaml",
            }

            # 7. collaboration_event_timeline — recent events across all collaboration tables
            _timeline = _db_query("""
                (SELECT 'handoff' as event_type, from_agent as agent, symbol, intent as detail, status, created_at
                 FROM agent_handoffs WHERE created_at > NOW() - INTERVAL '7 days' ORDER BY created_at DESC LIMIT 15)
                UNION ALL
                (SELECT 'event' as event_type, agents_to_notify::text as agent, symbol, event_type as detail, status, created_at
                 FROM agent_event_queue WHERE created_at > NOW() - INTERVAL '7 days' ORDER BY created_at DESC LIMIT 10)
                UNION ALL
                (SELECT 'debate' as event_type, participants::text as agent, symbol, consensus_recommendation as detail, status, created_at
                 FROM agent_debate_log ORDER BY created_at DESC LIMIT 5)
                UNION ALL
                (SELECT 'brief' as event_type, 'aegis' as agent, symbol, thesis_status as detail,
                        CASE WHEN needs_steph_review THEN 'needs_review' ELSE 'complete' END as status, observed_at as created_at
                 FROM aegis_portfolio_briefs WHERE observed_at > NOW() - INTERVAL '48 hours' AND (needs_steph_review=true OR thesis_status IN ('warning','danger','triggered'))
                 ORDER BY observed_at DESC LIMIT 10)
                ORDER BY created_at DESC LIMIT 30
            """) or []
            scoring["collaboration_event_timeline"] = _jc(_timeline)

            # ── Per-handoff drilldown data (recent, with timestamps) ──
            handoff_details = _db_query("""
                SELECT id, from_agent, to_agent, symbol, intent, status,
                       escalated, confidence, reason, created_at,
                       EXTRACT(EPOCH FROM (NOW() - created_at)) / 3600 as age_hours
                FROM agent_handoffs
                ORDER BY created_at DESC LIMIT 50
            """) or []

            # ── Agent quality metrics (from calibration) ──
            agent_quality = _db_query("""
                SELECT agent_name, accuracy, calibration_error,
                       overconfidence_score, underconfidence_score,
                       resolved, correct, incorrect, sample_size_status,
                       created_at as scored_at
                FROM agent_calibration_windows
                ORDER BY agent_name
            """) or []

            # ── Stale data products with duration ──
            stale_products = _db_query("""
                SELECT state_file, ok, age_hours, max_age_hours,
                       ROUND(CAST(age_hours - max_age_hours AS numeric), 1) as hours_overdue,
                       checked_at, source_script
                FROM state_freshness_history
                WHERE checked_at = (SELECT MAX(checked_at) FROM state_freshness_history)
                ORDER BY ok ASC, age_hours DESC
            """) or []

            # ── RACI process health (enrich with last-run timestamps) ──
            import yaml as _yaml
            _raci_path2 = PROJECT_ROOT / "config" / "agent_raci.yaml"
            _raci_health = []
            if _raci_path2.exists():
                try:
                    _rcfg = _yaml.safe_load(_raci_path2.read_text()) or {}
                    for p in _rcfg.get("processes", []):
                        agents_in = list((p.get("raci") or {}).keys())
                        # Find latest handoff/result for agents in this process
                        _latest_activity = None
                        for a in agents_in:
                            _la = _db_query(f"SELECT MAX(created_at) as t FROM watchlist_agent_results WHERE agent=%s", [a], fetch="one")
                            if _la and _la.get("t"):
                                if not _latest_activity or _la["t"] > _latest_activity:
                                    _latest_activity = _la["t"]
                        _age_h = None
                        if _latest_activity:
                            _age_h = round((_now_utc - _latest_activity.replace(tzinfo=timezone.utc if _latest_activity.tzinfo is None else _latest_activity.tzinfo)).total_seconds() / 3600, 1)
                        _raci_health.append({
                            "process_id": p.get("id"),
                            "process_name": p.get("name"),
                            "trigger": p.get("trigger"),
                            "frequency": p.get("frequency"),
                            "agents": agents_in,
                            "roles": p.get("raci", {}),
                            "last_activity": _json_clean(_latest_activity),
                            "age_hours": _age_h,
                            "health": "fresh" if _age_h and _age_h < 24 else ("stale" if _age_h and _age_h < 72 else "unknown"),
                        })
                except Exception:
                    pass

            return 200, {"ok": True, "data": {
                "summary": summary,
                "john_next_actions": john_actions[:7],
                "mission_groups": missions,
                "agent_network": _jc(network),
                "scoring": scoring,
                "handoff_details": _jc(handoff_details),
                "agent_quality": _jc(agent_quality),
                "stale_products": _jc(stale_products),
                "raci_health": _raci_health,
            }}
        except Exception as e:
            import traceback; traceback.print_exc()
            return 500, {"ok": False, "error": str(e)}

    # ── Session 29: Agent Calibration endpoints ───────────────────────────
    if base_path == "/api/v2/agent-calibration/status":
        try:
            status = {}
            for tbl, label in [("agent_recommendation_registry", "recommendations"),
                               ("agent_recommendation_outcome_links", "outcome_links"),
                               ("agent_calibration_events", "calibration_events"),
                               ("agent_calibration_windows", "calibration_windows"),
                               ("agent_weight_shadow_proposals", "weight_proposals"),
                               ("agent_disagreement_outcomes", "disagreements")]:
                r = _db_query(f"SELECT COUNT(*) as c FROM {tbl}", fetch="one")
                status[f"{label}_total"] = r["c"] if r else 0
            agents = _db_query("SELECT DISTINCT agent_name FROM agent_recommendation_registry ORDER BY agent_name") or []
            status["agents"] = [a["agent_name"] for a in agents]
            # Freshness timestamps
            _ts = _db_query("SELECT MAX(created_at) as t FROM agent_calibration_windows", fetch="one")
            status["last_calibration_run"] = _json_clean(_ts["t"]) if _ts and _ts.get("t") else None
            _ts2 = _db_query("SELECT MAX(recommendation_time) as t FROM agent_recommendation_registry", fetch="one")
            status["last_recommendation"] = _json_clean(_ts2["t"]) if _ts2 and _ts2.get("t") else None
            _ts3 = _db_query("SELECT MAX(created_at) as t FROM agent_recommendation_outcome_links", fetch="one")
            status["last_outcome_link"] = _json_clean(_ts3["t"]) if _ts3 and _ts3.get("t") else None
            return 200, {"ok": True, "data": status}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/agent-calibration/agents":
        try:
            rows = _db_query("""
                SELECT agent_name, COUNT(*) as total,
                       COUNT(DISTINCT symbol) as symbols
                FROM agent_recommendation_registry GROUP BY agent_name ORDER BY total DESC
            """) or []
            return 200, {"ok": True, "data": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path.startswith("/api/v2/agent-calibration/agents/") and base_path.count("/") == 5:
        try:
            agent = base_path.split("/")[-1]
            windows = _db_query("""
                SELECT * FROM agent_calibration_windows WHERE agent_name=%s
                ORDER BY created_at DESC LIMIT 10
            """, (agent,)) or []
            recs = _db_query("""
                SELECT recommendation_id, symbol, recommendation_type, confidence,
                       recommendation_time FROM agent_recommendation_registry
                WHERE agent_name=%s ORDER BY recommendation_time DESC LIMIT 20
            """, (agent,)) or []
            return 200, {"ok": True, "data": {
                "agent_name": agent,
                "windows": [{k: _json_clean(v) for k, v in w.items()} for w in windows],
                "recent_recommendations": [{k: _json_clean(v) for k, v in r.items()} for r in recs]
            }}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/agent-calibration/events":
        try:
            rows = _db_query("""
                SELECT calibration_event_id, agent_name, symbol, predicted_action,
                       predicted_confidence, actual_outcome, outcome_score,
                       calibration_error, explanation, created_at
                FROM agent_calibration_events ORDER BY created_at DESC LIMIT 50
            """) or []
            return 200, {"ok": True, "data": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/agent-calibration/windows":
        try:
            rows = _db_query("""
                SELECT window_id, agent_name, domain, recommendations, resolved,
                       correct, incorrect, accuracy, avg_confidence, calibration_error,
                       overconfidence_score, underconfidence_score, low_sample_size,
                       sample_size_status, recommendation, created_at
                FROM agent_calibration_windows ORDER BY created_at DESC LIMIT 50
            """) or []
            return 200, {"ok": True, "data": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/agent-calibration/recommendations":
        try:
            rows = _db_query("""
                SELECT recommendation_id, title, domain, recommendation_type, status,
                       sample_size, confidence, risk_level, created_at
                FROM learning_recommendations WHERE domain='agent_calibration'
                ORDER BY created_at DESC LIMIT 50
            """) or []
            return 200, {"ok": True, "data": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/agent-calibration/weight-proposals":
        try:
            rows = _db_query("""
                SELECT shadow_proposal_id, agent_name, domain, strategy_id,
                       current_weight, proposed_weight, weight_delta, reason,
                       sample_size, confidence, risk_level, status, created_at
                FROM agent_weight_shadow_proposals ORDER BY created_at DESC LIMIT 50
            """) or []
            return 200, {"ok": True, "data": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/agent-calibration/disagreements":
        try:
            rows = _db_query("""
                SELECT disagreement_id, symbol, agents_involved, disagreement_type,
                       winning_view, losing_view, outcome_summary, resolved, created_at
                FROM agent_disagreement_outcomes ORDER BY created_at DESC LIMIT 50
            """) or []
            return 200, {"ok": True, "data": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Per-agent comprehensive dashboard ────────────────
    if base_path == "/api/v2/agent-dashboard":
        try:
            agent_id = (query or {}).get("agent", [""])[0] if isinstance((query or {}).get("agent"), list) else (query or {}).get("agent", "")
            if not agent_id:
                return 400, {"ok": False, "error": "agent parameter required"}

            # Agent identity
            _llm_model = os.getenv("LOCAL_LLM_MODEL", "gemma3:4b")
            AGENT_IDENTITIES = {
                "steph": {"display": "Steph", "emoji": "📊", "role": "Income guardian / allocation strategist", "model": _llm_model},
                "maria": {"display": "Maria", "emoji": "🔬", "role": "Research analyst / catalyst verification", "model": _llm_model},
                "maria_research": {"display": "Maria Research", "emoji": "🔬", "role": "Deep research / two-pass RAG analysis", "model": _llm_model},
                "risk_agent": {"display": "Risk", "emoji": "🛡️", "role": "Risk management / stop coverage / portfolio heat", "model": _llm_model},
                "tax_agent": {"display": "Tax", "emoji": "💰", "role": "Tax optimization / Roth conversion / harvest", "model": _llm_model},
                "alex": {"display": "Alex", "emoji": "👔", "role": "CIO / escalation arbiter / strategic oversight", "model": _llm_model},
                "aegis": {"display": "Aegis", "emoji": "🏛️", "role": "Portfolio surveillance / overnight analysis", "model": _llm_model},
                "iris": {"display": "Iris", "emoji": "📚", "role": "Intelligence librarian / RAG coverage / taxonomy", "model": _llm_model},
                "social_scalp": {"display": "Social Scalp", "emoji": "📡", "role": "Social mention scanner / GO-WAIT-AVOID", "model": _llm_model},
                "scalp_critic": {"display": "Scalp Critic", "emoji": "🎯", "role": "Post-scan critic / catalyst validation", "model": _llm_model},
            }
            # Match agent_id loosely
            identity = AGENT_IDENTITIES.get(agent_id, {"display": agent_id, "emoji": "🤖", "role": "Agent", "model": _llm_model})

            # DB names this agent might use
            db_names = [agent_id]
            if agent_id == "steph": db_names.extend(["steph_allocation"])
            if agent_id == "risk": db_names.extend(["risk_agent"])
            if agent_id == "tax": db_names.extend(["tax_agent"])
            if agent_id == "aegis": db_names.extend(["aegis_core"])
            agent_filter = " OR ".join(f"agent ILIKE '%{n}%'" for n in db_names)

            # Stats
            stats_row = _db_query(f"""
                SELECT COUNT(*) as total, AVG(confidence) as avg_conf,
                       MAX(created_at) as last_run,
                       AVG(CASE WHEN created_at > NOW()-INTERVAL '30 days' THEN confidence END) as avg_conf_30d
                FROM watchlist_agent_results WHERE {agent_filter}
            """, fetch="one") or {}

            # Enrich stats from home tables (agents that don't write to watchlist_agent_results)
            _HOME_TABLES = {
                "alex": "SELECT COUNT(*) as cnt, MAX(created_at) as latest FROM cio_decisions",
                "aegis": "SELECT COUNT(*) as cnt, MAX(observed_at) as latest FROM aegis_portfolio_briefs",
            }
            if agent_id in _HOME_TABLES:
                _ht = _db_query(_HOME_TABLES[agent_id], fetch="one")
                if _ht and _ht.get("latest"):
                    cur_last = str(stats_row.get("last_run") or "")
                    ht_last = str(_ht["latest"])
                    if ht_last > cur_last:
                        stats_row["last_run"] = _ht["latest"]
                    stats_row["total"] = max(int(stats_row.get("total") or 0), int(_ht.get("cnt") or 0))

            # Confidence histogram (30d)
            histogram = _db_query(f"""
                SELECT width_bucket(confidence, 0, 1, 10) as bucket, COUNT(*) as cnt
                FROM watchlist_agent_results
                WHERE ({agent_filter}) AND created_at > NOW()-INTERVAL '30 days' AND confidence IS NOT NULL
                GROUP BY 1 ORDER BY 1
            """) or []

            # Confidence trend (14d rolling, last 90d)
            trend = _db_query(f"""
                SELECT created_at::date as date, AVG(confidence) as avg, COUNT(*) as n
                FROM watchlist_agent_results
                WHERE ({agent_filter}) AND created_at > NOW()-INTERVAL '90 days'
                GROUP BY 1 ORDER BY 1
            """) or []

            # Decision mix (30d)
            mix = _db_query(f"""
                SELECT recommendation, COUNT(*) as cnt
                FROM watchlist_agent_results
                WHERE ({agent_filter}) AND created_at > NOW()-INTERVAL '30 days'
                GROUP BY 1 ORDER BY 2 DESC
            """) or []

            # Recent results (25)
            recent = _db_query(f"""
                SELECT id, symbol, recommendation, confidence, summary,
                       created_at, model_used, reason_codes, request_type
                FROM watchlist_agent_results
                WHERE {agent_filter}
                ORDER BY created_at DESC LIMIT 25
            """) or []

            # Top symbols
            top_syms = _db_query(f"""
                SELECT symbol, COUNT(*) as cnt, AVG(confidence) as avg_conf
                FROM watchlist_agent_results
                WHERE ({agent_filter}) AND created_at > NOW()-INTERVAL '90 days'
                GROUP BY 1 ORDER BY 2 DESC LIMIT 15
            """) or []

            # Debates
            debates = _db_query(f"""
                SELECT id, symbol, debate_type, agents_involved, outcome_summary,
                       winning_view, created_at, resolved
                FROM agent_debate_log
                WHERE agents_involved::text ILIKE '%{agent_id}%'
                ORDER BY created_at DESC LIMIT 10
            """) or []

            # Intelligence rules / outcome lessons
            lessons = _db_query(f"""
                SELECT id, rule_type, strategy_id, symbol, rule_text, confidence_adjustment,
                       source_trade_id, created_at, changed_by
                FROM agent_intelligence_rules
                WHERE changed_by ILIKE '%{agent_id}%' OR changed_by ILIKE '%{db_names[0]}%'
                ORDER BY created_at DESC LIMIT 10
            """) or []

            # Calibration
            cal_count = _db_query("SELECT COUNT(*) as n FROM agent_calibration_windows", fetch="one") or {}

            # Performance history
            perf = _db_query(f"""
                SELECT * FROM agent_performance_history
                WHERE agent_name ILIKE '%{agent_id}%' OR agent_name ILIKE '%{db_names[0]}%'
                ORDER BY created_at DESC LIMIT 20
            """) or []

            # Agent-specific data
            agent_specific = {}
            if agent_id in ("steph", "steph_allocation"):
                try:
                    _h = _load_json(STATE_DIR / "holdings.json") or {}
                    _divs = _load_json(STATE_DIR / "dividend_calendar.json") or {}
                    _payers = _divs.get("payers", []) if isinstance(_divs, dict) else []
                    agent_specific = {
                        "type": "income_tracker",
                        "income_target": 55000,
                        "current_income": float(_divs.get("total_annual", 0)) if isinstance(_divs, dict) else 0,
                        "qualified_annual": float(_divs.get("qualified_annual", 0)) if isinstance(_divs, dict) else 0,
                        "monthly_average": float(_divs.get("monthly_average", 0)) if isinstance(_divs, dict) else 0,
                        "top_income_positions": sorted(
                            [{"symbol": p.get("symbol"), "income": float(p.get("annual_income", 0) or 0),
                              "yield_pct": p.get("yield_pct"), "account": p.get("account", "")}
                             for p in _payers if float(p.get("annual_income", 0) or 0) > 0],
                            key=lambda x: -x["income"])[:10],
                    }
                except Exception:
                    pass
            elif agent_id in ("aegis", "aegis_core"):
                agent_specific = {"type": "overnight_findings",
                    "briefs": [{k: _json_clean(v) for k, v in r.items()} for r in
                        (_db_query("SELECT id, brief_date, key_findings, created_at FROM aegis_portfolio_briefs ORDER BY created_at DESC LIMIT 5") or [])]}
            elif agent_id == "iris":
                agent_specific = {"type": "coverage",
                    "runs": [{k: _json_clean(v) for k, v in r.items()} for r in
                        (_db_query("SELECT id, run_type, symbols_processed, created_at FROM iris_run_log ORDER BY created_at DESC LIMIT 10") or [])]}

            result = {
                "agent_id": agent_id,
                "identity": identity,
                "stats": {
                    "lifetime_analyses": int(stats_row.get("total", 0) or 0),
                    "avg_confidence_all": round(float(stats_row.get("avg_conf", 0) or 0), 3),
                    "avg_confidence_30d": round(float(stats_row.get("avg_conf_30d", 0) or 0), 3),
                    "last_run_at": _json_clean(stats_row.get("last_run")),
                    "status": "healthy" if stats_row.get("last_run") and str(stats_row["last_run"]) > str(datetime.now() - timedelta(hours=72)) else "stale",
                },
                "confidence_histogram": [{k: _json_clean(v) for k, v in r.items()} for r in histogram],
                "confidence_trend": [{k: _json_clean(v) for k, v in r.items()} for r in trend],
                "decision_mix": {r["recommendation"]: r["cnt"] for r in mix},
                "recent_results": [{k: _json_clean(v) for k, v in r.items()} for r in recent],
                "top_symbols": [{k: _json_clean(v) for k, v in r.items()} for r in top_syms],
                "debates": [{k: _json_clean(v) for k, v in r.items()} for r in debates],
                "outcome_lessons": [{k: _json_clean(v) for k, v in r.items()} for r in lessons],
                "calibration": {
                    "samples": int(cal_count.get("n", 0) or 0),
                    "samples_needed": 20,
                    "ready": int(cal_count.get("n", 0) or 0) >= 20,
                },
                "performance_history": [{k: _json_clean(v) for k, v in r.items()} for r in perf],
                "agent_specific": agent_specific,
            }

            # V2 additions: event queue, handoffs, LLM routing, SLA
            try:
                # Event queue for this agent
                events = _db_query(f"""
                    SELECT event_type, symbol, priority, status, created_at, processed_at
                    FROM agent_event_queue
                    WHERE agents_to_notify::text ILIKE '%{agent_id}%'
                    ORDER BY created_at DESC LIMIT 20
                """) or []
                result["event_queue"] = [{k: _json_clean(v) for k, v in r.items()} for r in events]
                result["event_summary"] = {}
                for e in events:
                    et = e.get("event_type", "?")
                    result["event_summary"][et] = result["event_summary"].get(et, 0) + 1
            except Exception:
                result["event_queue"] = []
                result["event_summary"] = {}

            try:
                # Handoffs involving this agent
                handoffs = _db_query(f"""
                    SELECT id, from_agent, to_agent, intent, confidence, reason,
                           action_type, status, created_at
                    FROM agent_handoffs
                    WHERE from_agent ILIKE '%{agent_id}%' OR to_agent ILIKE '%{agent_id}%'
                    ORDER BY created_at DESC LIMIT 20
                """) or []
                result["handoffs"] = [{k: _json_clean(v) for k, v in r.items()} for r in handoffs]
                result["handoff_summary"] = {
                    "outgoing": sum(1 for h in handoffs if agent_id.lower() in (h.get("from_agent") or "").lower()),
                    "incoming": sum(1 for h in handoffs if agent_id.lower() in (h.get("to_agent") or "").lower()),
                }
            except Exception:
                result["handoffs"] = []
                result["handoff_summary"] = {"outgoing": 0, "incoming": 0}

            try:
                # LLM routing summary (from jsonl tail)
                import json as _json_mod
                llm_log = PROJECT_ROOT / "logs" / "llm_routing_audit.jsonl"
                llm_entries = []
                # LLM routing: caller field is empty, so we show system-wide stats
                # (all agents share process_watchlist_agent_jobs.py)
                if llm_log.exists():
                    with open(llm_log) as f:
                        lines = f.readlines()
                    for line in lines[-200:]:  # last 200 entries
                        try:
                            llm_entries.append(_json_mod.loads(line.strip()))
                        except Exception:
                            pass
                # Summarize last 100 relevant entries
                llm_entries = llm_entries[-100:]
                by_provider = {}
                for e in llm_entries:
                    p = e.get("provider", "unknown")
                    if p not in by_provider:
                        by_provider[p] = {"calls": 0, "ok": 0, "total_ms": 0, "fallbacks": 0}
                    by_provider[p]["calls"] += 1
                    if e.get("status") == "ok": by_provider[p]["ok"] += 1
                    by_provider[p]["total_ms"] += e.get("latency_ms", 0)
                    if e.get("fallback"): by_provider[p]["fallbacks"] += 1
                result["llm_routing"] = {
                    p: {"calls": v["calls"], "success_rate": round(v["ok"]/max(v["calls"],1)*100,1),
                        "avg_latency_ms": round(v["total_ms"]/max(v["calls"],1)),
                        "fallbacks": v["fallbacks"]}
                    for p, v in by_provider.items()
                }
                result["llm_total_calls"] = sum(v["calls"] for v in by_provider.values())
            except Exception:
                result["llm_routing"] = {}
                result["llm_total_calls"] = 0

            try:
                # SLA status — calendar-aware
                last_result = _db_query(f"SELECT MAX(created_at) as ts FROM watchlist_agent_results WHERE {agent_filter}", fetch="one") or {}
                last_ts = last_result.get("ts")
                if last_ts:
                    try:
                        age_min = (datetime.now(last_ts.tzinfo) - last_ts).total_seconds() / 60
                    except Exception:
                        age_min = (datetime.now() - last_ts.replace(tzinfo=None)).total_seconds() / 60
                else:
                    age_min = 999

                # Determine current window (ET)
                import pytz
                _et = pytz.timezone("US/Eastern")
                _now_et = datetime.now(_et)
                _dow = _now_et.weekday()
                _hr = _now_et.hour
                if _dow >= 5:  # Sat/Sun
                    _window = "weekend"
                    _sla_min = None  # no SLA on weekend
                    _color = "green" if age_min < 4320 else "amber"  # 72h = 3 days
                    _reason = f"Weekend idle — last update {age_min/60:.1f}h ago (expected idle until Mon)"
                elif 9 <= _hr < 16:
                    _window = "market_hours"
                    _sla_min = 15
                    _color = "green" if age_min <= 15 else "amber" if age_min <= 60 else "red"
                    _reason = f"Market hours: {age_min:.0f}m vs SLA {_sla_min}m"
                elif 16 <= _hr < 23:
                    _window = "evening"
                    _sla_min = 60
                    _color = "green" if age_min <= 60 else "amber" if age_min <= 180 else "red"
                    _reason = f"Evening: {age_min:.0f}m vs SLA {_sla_min}m"
                else:
                    _window = "overnight"
                    _sla_min = None
                    _color = "green" if age_min < 720 else "amber"
                    _reason = f"Overnight idle — {age_min/60:.1f}h since last"

                result["sla"] = {
                    "last_data_at": _json_clean(last_ts),
                    "age_minutes": round(age_min, 1),
                    "sla_minutes": _sla_min,
                    "window": _window,
                    "color": _color,
                    "reason": _reason,
                }
            except Exception:
                result["sla"] = {"color": "gray", "age_minutes": None, "window": "unknown"}

            return 200, {"ok": True, "data": result}
        except Exception as e:
            import traceback; traceback.print_exc()
            return 500, {"ok": False, "error": str(e)}

    # ── V3: RACI matrix endpoint ────────────────
    if base_path == "/api/v2/agent-detail/raci":
        try:
            agent_id = (query or {}).get("agent", [""])[0] if isinstance((query or {}).get("agent"), list) else (query or {}).get("agent", "")
            if not agent_id:
                return 400, {"ok": False, "error": "agent required"}
            import yaml as _yaml
            raci_path = PROJECT_ROOT / "config" / "agent_raci.yaml"
            if not raci_path.exists():
                return 200, {"ok": True, "data": {"processes": [], "note": "config/agent_raci.yaml not found"}}
            raci = _yaml.safe_load(open(raci_path))
            # Filter to processes where this agent appears
            agent_lower = agent_id.lower()
            my_processes = []
            for p in raci.get("processes", []):
                raci_map = p.get("raci", {})
                my_role = None
                for k, v in raci_map.items():
                    if k.lower() == agent_lower or agent_lower in k.lower():
                        my_role = v
                        break
                if my_role:
                    co_actors = [{"agent": k, "role": v} for k, v in raci_map.items() if k.lower() != agent_lower and agent_lower not in k.lower()]
                    my_processes.append({**p, "this_role": my_role, "co_actors": co_actors})
            # Peer summary
            peer_counts = {}
            for p in my_processes:
                for ca in p.get("co_actors", []):
                    peer = ca["agent"]
                    peer_counts.setdefault(peer, {"count": 0, "roles": []})
                    peer_counts[peer]["count"] += 1
                    peer_counts[peer]["roles"].append(ca["role"])
            peer_summary = [{"peer": k, "process_count": v["count"],
                             "dominant_relationship": max(set(v["roles"]), key=v["roles"].count) if v["roles"] else "?"}
                            for k, v in sorted(peer_counts.items(), key=lambda x: -x[1]["count"])]
            return 200, {"ok": True, "data": {"agent": agent_id, "processes": my_processes, "peer_summary": peer_summary}}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── V3: Escalation trace endpoint ────────────────
    if base_path == "/api/v2/agent-detail/escalation-trace":
        try:
            result_id = (query or {}).get("result_id", [""])[0] if isinstance((query or {}).get("result_id"), list) else (query or {}).get("result_id", "")
            if not result_id:
                return 400, {"ok": False, "error": "result_id required"}
            # Get the analysis
            analysis = _db_query("SELECT id, agent, symbol, recommendation, confidence, created_at FROM watchlist_agent_results WHERE id=%s", (result_id,), fetch="one")
            if not analysis:
                return 404, {"ok": False, "error": "result not found"}
            sym = analysis["symbol"]
            ts = analysis["created_at"]
            trace = []
            # Step 1: triggering event
            events = _db_query("""
                SELECT id, event_type, priority, created_at FROM agent_event_queue
                WHERE symbol=%s AND created_at BETWEEN %s - INTERVAL '30 minutes' AND %s
                ORDER BY created_at DESC LIMIT 1
            """, (sym, ts, ts)) or []
            if events:
                e = events[0]
                trace.append({"step": 1, "type": "event", "label": f"{e['event_type']}", "ts": _json_clean(e["created_at"])})
            # Step 2: the analysis itself
            trace.append({"step": 2, "type": "agent_call", "is_focus": True,
                          "label": f"{analysis['agent']}: {analysis['recommendation']} (conf {analysis['confidence']})",
                          "ts": _json_clean(ts)})
            # Step 3: peer recs at same time
            peers = _db_query("""
                SELECT agent, recommendation, confidence, created_at FROM watchlist_agent_results
                WHERE symbol=%s AND id != %s AND created_at BETWEEN %s - INTERVAL '24 hours' AND %s + INTERVAL '24 hours'
                ORDER BY created_at DESC LIMIT 5
            """, (sym, result_id, ts, ts)) or []
            for p in peers:
                trace.append({"step": 3, "type": "peer_call",
                              "label": f"{p['agent']}: {p['recommendation']} (conf {p['confidence']})",
                              "ts": _json_clean(p["created_at"])})
            # Step 4: debate if any
            debates = _db_query("""
                SELECT id, debate_type, outcome_summary, winning_view, created_at FROM agent_debate_log
                WHERE symbol=%s AND created_at BETWEEN %s - INTERVAL '1 hour' AND %s + INTERVAL '1 hour'
                ORDER BY created_at DESC LIMIT 1
            """, (sym, ts, ts)) or []
            if debates:
                d = debates[0]
                trace.append({"step": 4, "type": "debate", "label": f"Debate: {d['debate_type']}",
                              "detail": d["outcome_summary"], "ts": _json_clean(d["created_at"])})
            # Step 5: human queue
            jdq = _db_query("""
                SELECT id, status, created_at FROM john_decision_queue
                WHERE symbol=%s AND created_at BETWEEN %s - INTERVAL '1 hour' AND %s + INTERVAL '2 hours'
                ORDER BY created_at DESC LIMIT 1
            """, (sym, ts, ts)) or []
            if jdq:
                j = jdq[0]
                trace.append({"step": 5, "type": "human_queue", "label": f"Queued for operator ({j['status']})",
                              "ts": _json_clean(j["created_at"])})
            return 200, {"ok": True, "data": {"result_id": result_id, "symbol": sym, "trace": trace}}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Session 30: Weekly Learning Digest + Thesis Review ────────────────
    if base_path == "/api/v2/weekly-learning-digest":
        try:
            rows = _db_query("""
                SELECT digest_id, period_start, period_end, status, holdings_value,
                       paper_trades_closed, win_rate, low_sample_size, generated_at
                FROM weekly_learning_digests ORDER BY created_at DESC LIMIT 20
            """) or []
            return 200, {"ok": True, "data": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/weekly-learning-digest/latest":
        try:
            row = _db_query("""
                SELECT digest_id, period_start, period_end, status, holdings_value,
                       paper_trades_closed, win_rate, profit_factor, low_sample_size,
                       top_lessons, agent_summary, source_summary, strategy_summary,
                       thesis_summary, recommendations, human_review_items, digest_markdown
                FROM weekly_learning_digests ORDER BY created_at DESC LIMIT 1
            """, fetch="one")
            if not row:
                return 200, {"ok": True, "data": None, "message": "No digests generated yet"}
            return 200, {"ok": True, "data": {k: _json_clean(v) for k, v in row.items()}}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path.startswith("/api/v2/weekly-learning-digest/") and not base_path.endswith("/latest") and not base_path.endswith("/items") and not base_path.endswith("/generate") and not base_path.endswith("/send-telegram"):
        try:
            did = base_path.split("/")[-1]
            row = _db_query("SELECT * FROM weekly_learning_digests WHERE digest_id=%s", (did,), fetch="one")
            if not row:
                return 404, {"ok": False, "error": "Digest not found"}
            return 200, {"ok": True, "data": {k: _json_clean(v) for k, v in row.items()}}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/trade-thesis-reviews":
        try:
            rows = _db_query("""
                SELECT review_id, paper_trade_id, symbol, strategy_id, trade_status,
                       review_type, thesis_validity, thesis_score, execution_score,
                       risk_management_score, outcome_score, lesson_summary,
                       mistake_tags, strength_tags, low_sample_size, created_at
                FROM trade_thesis_reviews ORDER BY created_at DESC LIMIT 50
            """) or []
            return 200, {"ok": True, "data": [{k: _json_clean(v) for k, v in r.items()} for r in rows]}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path.startswith("/api/v2/trade-thesis-reviews/") and not base_path.endswith("/run"):
        try:
            rid = base_path.split("/")[-1]
            row = _db_query("SELECT * FROM trade_thesis_reviews WHERE review_id=%s", (rid,), fetch="one")
            if not row:
                return 404, {"ok": False, "error": "Review not found"}
            return 200, {"ok": True, "data": {k: _json_clean(v) for k, v in row.items()}}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    # ── Session 31: Backtesting + Champion/Challenger ─────────────────────
    if base_path == "/api/v2/backtesting/status":
        try:
            _q = query or {}
            _bf_strategy = _q.get("strategy")
            _bf_start = _q.get("start_date")
            _bf_end = _q.get("end_date")
            _bf_run = _q.get("run_id")
            _bf_run_type = _q.get("run_type")
            _bf_broker = _q.get("broker")
            _bf_account = _q.get("account")
            # Unfiltered totals
            status = {}
            for tbl, lbl in [("backtest_datasets","datasets"), ("strategy_backtest_runs","runs"),
                             ("strategy_backtest_trades","trades"), ("challenger_definitions","challengers"),
                             ("champion_challenger_results","comparisons")]:
                r = _db_query(f"SELECT COUNT(*) as c FROM {tbl}", fetch="one")
                status[f"{lbl}_total"] = r["c"] if r else 0
            # Honest real-vs-synthetic split (2026-06-11): 96% of backtest rows are champion/simulation
            # seeds; blended totals misread as real coverage. Surface the split explicitly.
            try:
                _split = _db_query("""SELECT COALESCE(r.run_type,'?') rt, COUNT(t.simulated_trade_id) c
                                      FROM strategy_backtest_trades t
                                      LEFT JOIN strategy_backtest_runs r ON r.run_id = t.run_id
                                      GROUP BY 1""") or []
                status["rows_by_run_type"] = {r["rt"]: r["c"] for r in _split}
                status["real_replay_rows"] = sum(c for k, c in status["rows_by_run_type"].items()
                                                 if k and not k.startswith("champion"))
                status["synthetic_rows"] = status.get("rows_by_run_type", {}).get("champion", 0)
            except Exception:
                pass
            # Filtered counts — use JOIN for run_type/broker/account
            _tw, _tp = [], []
            if _bf_strategy:
                _tw.append("sbt.strategy_id=%s"); _tp.append(_bf_strategy)
            if _bf_start:
                _tw.append("COALESCE(sbt.entry_time, sbt.signal_time) >= %s::date"); _tp.append(_bf_start)
            if _bf_end:
                _tw.append("COALESCE(sbt.entry_time, sbt.signal_time) <= (%s::date + interval '1 day')"); _tp.append(_bf_end)
            if _bf_run:
                _tw.append("sbt.run_id=%s"); _tp.append(_bf_run)
            if _bf_run_type:
                _tw.append("r.run_type=%s"); _tp.append(_bf_run_type)
            if _bf_broker:
                _tw.append("sbt.broker=%s"); _tp.append(_bf_broker)
            if _bf_account:
                _tw.append("sbt.account=%s"); _tp.append(_bf_account)
            _twhere = " AND ".join(_tw) if _tw else "1=1"
            _need_join = _bf_run_type
            if _need_join:
                _ft = _db_query(f"SELECT COUNT(*) as c FROM strategy_backtest_trades sbt LEFT JOIN strategy_backtest_runs r ON r.run_id=sbt.run_id WHERE {_twhere}", _tp, fetch="one")
            else:
                _ft = _db_query(f"SELECT COUNT(*) as c FROM strategy_backtest_trades sbt WHERE {_twhere}", _tp, fetch="one")
            status["trades_filtered"] = _ft["c"] if _ft else 0
            _rw, _rp = [], []
            if _bf_strategy:
                _rw.append("strategy_id=%s"); _rp.append(_bf_strategy)
            if _bf_start:
                _rw.append("start_date >= %s::date"); _rp.append(_bf_start)
            if _bf_end:
                _rw.append("end_date <= %s::date"); _rp.append(_bf_end)
            if _bf_run_type:
                _rw.append("run_type=%s"); _rp.append(_bf_run_type)
            if _bf_run:
                _rw.append("run_id=%s"); _rp.append(_bf_run)
            _rwhere = " AND ".join(_rw) if _rw else "1=1"
            _fr = _db_query(f"SELECT COUNT(*) as c FROM strategy_backtest_runs WHERE {_rwhere}", _rp, fetch="one")
            status["runs_filtered"] = _fr["c"] if _fr else 0
            status["filters_active"] = bool(_bf_strategy or _bf_start or _bf_end or _bf_run or _bf_run_type or _bf_broker or _bf_account)
            # Classification completeness
            _cls = _db_query("""SELECT COUNT(*) AS total,
                COUNT(*) FILTER (WHERE strategy_id IS NOT NULL AND strategy_id <> '' AND strategy_id <> 'unknown') AS classified
                FROM strategy_backtest_trades""", fetch="one") or {}
            _cls_total = _cls.get("total", 0)
            _cls_done = _cls.get("classified", 0)
            status["classification_total"] = _cls_total
            status["classification_classified"] = _cls_done
            status["classification_unclassified"] = _cls_total - _cls_done
            status["classification_pct"] = round(100 * _cls_done / max(_cls_total, 1), 1)
            # Per-pipeline last-run timestamps — "Last run" is otherwise ambiguous across distinct
            # pipelines (strategy backtester vs trade-backtest engine vs LLM review vs edge), which made
            # the single badge look stale while other pipelines were fresh.
            def _maxts(sql):
                try:
                    r = _db_query(sql, fetch="one")
                    return _json_clean(list(r.values())[0]) if r else None
                except Exception:
                    return None
            status["last_runs"] = {
                "strategy_backtester": _maxts("SELECT MAX(created_at) m FROM strategy_backtest_runs"),
                "trade_backtest_engine": _maxts("SELECT MAX(computed_at) m FROM trade_backtest_results"),
                "llm_review": _maxts("SELECT MAX(generated_at) m FROM trade_llm_reviews"),
                "edge_comparison": _maxts("SELECT MAX(updated_at) m FROM trade_edge_comparison"),
            }
            status["last_run_overall"] = max([v for v in status["last_runs"].values() if v], default=None)
            return 200, {"ok": True, "data": status}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/backtesting/data-quality" and method == "GET":
        # ADVISORY per-tab data-trust scorecard. Read-only; never affects GO/WAIT or trading.
        try:
            def _c(sql):
                r = _db_query(sql, fetch="one"); return (list(r.values())[0] if r else 0) or 0
            def _tier(p):
                if p is None:
                    return "no_data"
                return "excellent" if p >= 0.9 else "usable" if p >= 0.6 else "advisory" if p >= 0.25 else "untrusted"
            def _pct(n, d):
                return round(n / d, 3) if d else None
            tabs = {}
            # Entry Quality — trade_backtest_results linked to trade_instance
            eq = _c("SELECT COUNT(*) c FROM trade_backtest_results")
            eql = _c("SELECT COUNT(*) c FROM trade_backtest_results WHERE trade_instance_id IS NOT NULL")
            tabs["entry_quality"] = {"rows": eq, "linked": eql, "pct": _pct(eql, eq), "tier": _tier(_pct(eql, eq)),
                                     "basis": "trade_instance-linked backtest rows"}
            # AI Trade Eval — structured evals linked to trade_instance
            ev = _c("SELECT COUNT(*) c FROM trade_llm_reviews WHERE review_stage='structured_backtest_eval'")
            evl = _c("SELECT COUNT(*) c FROM trade_llm_reviews WHERE review_stage='structured_backtest_eval' AND trade_instance_id IS NOT NULL")
            tabs["trade_eval"] = {"rows": ev, "linked": evl, "pct": _pct(evl, ev), "tier": _tier(_pct(evl, ev)),
                                  "basis": "structured evals linked to a canonical trade_instance"}
            # Edge Comparison — all keyed by trade_instance
            ec = _c("SELECT COUNT(*) c FROM trade_edge_comparison")
            ecl = _c("SELECT COUNT(*) c FROM trade_edge_comparison WHERE trade_instance_id IS NOT NULL")
            tabs["edge_comparison"] = {"rows": ec, "linked": ecl, "pct": _pct(ecl, ec), "tier": _tier(_pct(ecl, ec)),
                                       "basis": "edge rows keyed to trade_instance"}
            # Hermes Reflections — reflection coverage of closed trade_instances
            hbl = _c("SELECT COUNT(*) c FROM trade_instances ti WHERE lower(coalesce(status,''))='closed' AND NOT EXISTS (SELECT 1 FROM hermes_research_intelligence h WHERE h.trade_instance_id=ti.id)")
            hlk = _c("SELECT COUNT(DISTINCT trade_instance_id) c FROM hermes_research_intelligence WHERE trade_instance_id IS NOT NULL")
            _hd = hlk + hbl
            tabs["hermes_reflections"] = {"linked": hlk, "backlog": hbl, "pct": _pct(hlk, _hd), "tier": _tier(_pct(hlk, _hd)),
                                          "basis": "closed trades with a trade-linked reflection"}
            # LLM Review Coverage — clean (non-error, non-stale) fraction
            lr = _c("SELECT COUNT(*) c FROM trade_llm_reviews")
            lrbad = _c("SELECT COUNT(*) c FROM trade_llm_reviews WHERE status IN ('error','superseded_stale_cost_basis')")
            tabs["llm_review_coverage"] = {"rows": lr, "clean": lr - lrbad, "pct": _pct(lr - lrbad, lr), "tier": _tier(_pct(lr - lrbad, lr)),
                                           "basis": "non-error, non-stale reviews (infra errors retryable, separate)"}
            # Missed Opportunities — advisory by nature (sim outcomes, MIXED-heavy)
            tabs["missed"] = {"tier": "advisory", "basis": "deduped by proposal_id; sim outcomes incl MIXED — advisory by design"}
            summary = {t: tabs[t]["tier"] for t in tabs}
            return 200, {"ok": True, "data": {"tabs": tabs, "tab_tiers": summary,
                         "legend": {"excellent": ">=90% canonical-linked/clean", "usable": ">=60%",
                                    "advisory": ">=25% or simulation/mixed", "untrusted": "<25% or stale/error"},
                         "note": "ADVISORY ONLY — base-data trust per tab; does not affect GO/WAIT or trading."}}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

