            _sp.Popen([str(PROJECT_ROOT / ".venv/bin/python"),
                       str(PROJECT_ROOT / "scripts/trailing_stop_analyzer.py")],
                      cwd=str(PROJECT_ROOT), stdout=_sp.PIPE, stderr=_sp.STDOUT)
