    if base_path == "/api/v2/atm/strategy-health":
        try:
            import sys as _sys; _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
            from atm_classifier_health import get_health_detail
            from atm_config_manager import load_config, is_bucket2_excluded, is_same_day_skip, get_strategy_filter
            cfg, _ = load_config()
            sf = get_strategy_filter()
            min_health = sf.get("min_classifier_health", 0.5)
            strats = _db_query("SELECT DISTINCT strategy_id FROM strategy_signals WHERE strategy_id IS NOT NULL") or []
            result = []
            for s in strats:
                sid = s["strategy_id"]
                detail = get_health_detail(sid)
                result.append({
                    "strategy_id": sid,
                    "classifier_health": detail["score"],
                    "has_baseline": detail["has_baseline"],
                    "closed_trades": detail["closed_trades"],
                    "wins": detail["wins"],
                    "avg_r": detail["avg_r"],
                    "eligible": detail["score"] >= min_health,
                    "bucket2_excluded": is_bucket2_excluded(sid),
                    "same_day_skip": is_same_day_skip(sid),
                })
            return 200, {"ok": True, "data": sorted(result, key=lambda x: (-x["classifier_health"], x["strategy_id"])),
                         "min_classifier_health": min_health}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/atm/accounts":
        try:
            rows = _db_query("""
                SELECT a.*, COALESCE(p.open_count, 0) as positions_open,
                       COALESCE(t.new_today, 0) as new_today
                FROM accounts a
                LEFT JOIN (SELECT target_account, COUNT(*) as open_count
                           FROM paper_trades WHERE status='open' GROUP BY target_account) p
                    ON p.target_account = a.account_label
                LEFT JOIN (SELECT target_account, COUNT(*) as new_today
                           FROM paper_trades WHERE created_at::date = CURRENT_DATE GROUP BY target_account) t
                    ON t.target_account = a.account_label
                ORDER BY a.id
            """) or []
            return 200, {"ok": True, "data": rows}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/atm/queue-preview":
        try:
            import sys as _sys; _sys.path.insert(0, str(PROJECT_ROOT / "scripts"))
            from atm_config_manager import (load_config, get_enabled_accounts,
                                             is_bucket2_excluded, is_same_day_skip, get_strategy_filter)
            from atm_classifier_health import get_health
            _qp_cfg, _ = load_config()
            _qp_sf = get_strategy_filter()
            _qp_min_health = _qp_sf.get("min_classifier_health", 0.5)
            _qp_enabled = set(get_enabled_accounts())
            rows = _db_query("""
                SELECT id, symbol, strategy_id, target_account, status, atm_action,
                       proposed_entry, proposed_stop, proposed_target1, proposed_shares
                FROM paper_trade_proposals
                WHERE status = 'PENDING'
                ORDER BY created_at ASC LIMIT 20
            """) or []
            # Predict decision for each proposal
            for r in rows:
                sid = r.get("strategy_id") or ""
                target = r.get("target_account") or ""
                action = r.get("atm_action")
                if action == "force_approve":
                    r["predicted_decision"] = "would_approve"
                    r["predicted_reason"] = "force_approve override"
                elif action == "force_reject":
                    r["predicted_decision"] = "would_reject"
                    r["predicted_reason"] = "force_reject override"
                elif action == "force_skip":
                    r["predicted_decision"] = "would_skip"
                    r["predicted_reason"] = "force_skip override"
                elif target not in _qp_enabled:
                    r["predicted_decision"] = "would_defer"
                    r["predicted_reason"] = f"account {target} not enabled"
                elif is_bucket2_excluded(sid):
                    r["predicted_decision"] = "would_defer"
                    r["predicted_reason"] = "B-1 bucket2 observation active"
                elif is_same_day_skip(sid):
                    r["predicted_decision"] = "would_defer"
                    r["predicted_reason"] = "same_day_strategy_atm_cadence_too_slow"
                else:
                    h = get_health(sid)
                    if h < _qp_min_health:
                        r["predicted_decision"] = "would_reject"
                        r["predicted_reason"] = f"classifier_health {h:.3f} < {_qp_min_health}"
                    else:
                        r["predicted_decision"] = "would_approve"
                        r["predicted_reason"] = "all gates pass"
            return 200, {"ok": True, "data": rows}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/atm/mode" and method == "POST":
        try:
            new_mode = (body or {}).get("mode", "disabled")
            changed_by = (body or {}).get("changed_by", "dashboard")
            if new_mode not in ("disabled", "dry_run", "active", "paused"):
                return 400, {"ok": False, "error": f"Invalid mode: {new_mode}"}
            from db_adapter import _get_conn as _gc_mode
            conn = _gc_mode()
            cur = conn.cursor()
            cur.execute("SELECT mode FROM atm_state WHERE id=1")
            old = cur.fetchone()[0]
            cur.execute("UPDATE atm_state SET mode=%s, last_state_change_at=NOW(), last_state_change_by=%s WHERE id=1",
                        (new_mode, changed_by))
            cur.execute("INSERT INTO atm_state_events (old_mode, new_mode, changed_by) VALUES (%s,%s,%s)",
                        (old, new_mode, changed_by))
            conn.commit()
            return 200, {"ok": True, "old_mode": old, "new_mode": new_mode}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/atm/proposal-action" and method == "POST":
        try:
            pid = (body or {}).get("proposal_id")
            action = (body or {}).get("action")
            set_by = (body or {}).get("set_by", "dashboard")
            if not pid or action not in ("force_approve", "force_reject", "force_skip", None, "clear"):
                return 400, {"ok": False, "error": "Invalid proposal_id or action"}
            from db_adapter import _get_conn as _gc_action
            conn = _gc_action()
            cur = conn.cursor()
            if action == "clear":
                cur.execute("UPDATE paper_trade_proposals SET atm_action=NULL, atm_action_set_by=NULL, atm_action_set_at=NULL WHERE id=%s", (pid,))
            else:
                cur.execute("UPDATE paper_trade_proposals SET atm_action=%s, atm_action_set_by=%s, atm_action_set_at=NOW() WHERE id=%s",
                            (action, set_by, pid))
            conn.commit()
            return 200, {"ok": True, "proposal_id": pid, "action": action}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

    if base_path == "/api/v2/atm/enrichment-status":
        try:
            proposals = _db_query("""
                SELECT id, symbol, strategy_id, enrichment_status, enrichment_failures,
                       enrichment_last_attempt_at, enrichment_last_error
                FROM paper_trade_proposals
                WHERE status = 'PENDING'
                ORDER BY created_at ASC
            """) or []
            last_run = _db_query("SELECT last_enrichment_at FROM atm_state WHERE id=1", fetch="one") or {}
            # Per-proposal step detail from enrichment_log (latest per step)
            for p in proposals:
                steps = _db_query("""
                    SELECT step, success, duration_seconds, error_message, completed_at
                    FROM enrichment_log
                    WHERE proposal_id = %s
                    ORDER BY completed_at DESC
                """, (p["id"],)) or []
                # Deduplicate to latest per step
                seen = {}
                for s in steps:
                    if s["step"] not in seen:
                        seen[s["step"]] = s
                p["steps"] = seen
            summary = {
                "total": len(proposals),
                "complete": sum(1 for p in proposals if p.get("enrichment_status") == "COMPLETE"),
                "in_progress": sum(1 for p in proposals if p.get("enrichment_status") == "IN_PROGRESS"),
                "pending": sum(1 for p in proposals if p.get("enrichment_status") in (None, "PENDING")),
                "failed": sum(1 for p in proposals if p.get("enrichment_status") == "FAILED"),
            }
            return 200, {"ok": True, "data": proposals, "summary": summary,
                         "last_enrichment_at": str(last_run.get("last_enrichment_at") or "")}
        except Exception as e:
            return 500, {"ok": False, "error": str(e)}

